/**
 * PRIVATE PREVIEW GATE — one tiny helper shared by every unreleased customer
 * feature ("dedicated", "modbuilder"). Keep this file IDENTICAL on every branch
 * that carries it: it has no feature-specific imports.
 *
 * Who is allowed: the accounts whose email is in the allowlist for that feature.
 *   1. Setting `preview_access_emails_<feature>` (comma-separated), if that row exists;
 *   2. else Setting `preview_access_emails` (shared by every feature), if that row exists;
 *   3. else DEFAULT_PREVIEW_EMAILS below (the owner's own customer account).
 * An empty Setting value means "nobody". Matching is case-insensitive on the
 * account's email. A DB error fails CLOSED (nobody is a preview user).
 *
 * Callers decide what "not allowed" looks like (normally `notFound()`, so the
 * feature is indistinguishable from a route that does not exist).
 */
import { getSetting } from "./settings";

export const PREVIEW_FEATURES = ["dedicated", "modbuilder"] as const;
export type PreviewFeature = (typeof PREVIEW_FEATURES)[number];

export const PREVIEW_ACCESS_SETTING = "preview_access_emails";
export const DEFAULT_PREVIEW_EMAILS = ["nicholas.sj.albanese@gmail.com"];

/** Sentinel: getSetting returns it only when no Setting row exists. */
const UNSET = "\u0000unset";

export function parsePreviewEmails(raw: string | null | undefined): string[] {
  return (raw ?? "")
    .split(/[,\s;]+/)
    .map((e) => e.trim().toLowerCase())
    .filter((e) => e.includes("@"));
}

/** Pure decision (unit-tested). */
export function emailInPreviewList(email: string | null | undefined, list: readonly string[]): boolean {
  const e = (email ?? "").trim().toLowerCase();
  return !!e && list.some((x) => x.trim().toLowerCase() === e);
}

export async function previewAllowlist(feature: PreviewFeature): Promise<string[]> {
  if (!(PREVIEW_FEATURES as readonly string[]).includes(feature)) return [];
  const own = await getSetting(`${PREVIEW_ACCESS_SETTING}_${feature}`, UNSET);
  if (own !== UNSET) return parsePreviewEmails(own);
  const shared = await getSetting(PREVIEW_ACCESS_SETTING, UNSET);
  if (shared !== UNSET) return parsePreviewEmails(shared);
  return [...DEFAULT_PREVIEW_EMAILS];
}

/** True only for a signed-in account on the feature's allowlist. Never throws. */
export async function isPreviewUser(
  user: { email?: string | null } | null | undefined,
  feature: PreviewFeature,
): Promise<boolean> {
  if (!user?.email) return false;
  try {
    return emailInPreviewList(user.email, await previewAllowlist(feature));
  } catch {
    return false; // fail CLOSED
  }
}

// Names used by the mod builder (merged 2026-10-06): kept as aliases so both
// features share this one file.
export const PREVIEW_ACCESS_DEFAULT = DEFAULT_PREVIEW_EMAILS.join(",");
export const emailAllowed = emailInPreviewList;

"use server";

// Admin: grant / revoke Cyrus tokens, comp a model tier, tune the economy Settings.
// Same gate as the page (/admin/cyrus-tokens): billing area AND the real signed-in
// account on the private-preview list. Every action is audit-logged.
import { notFound, redirect } from "next/navigation";
import { randomBytes } from "node:crypto";
import { db } from "../../db";
import { realUser } from "../../auth";
import { requireArea } from "../../rbac";
import { isPreviewUser } from "../../preview-access";
import { clearTokenConfigCache, CYRUS_TOKEN_DEFAULTS, TOKEN_SETTING_KEYS, loadTokenConfig, type TokenSettingKey } from "./config";
import { creditTokens, revokeTokens } from "./ledger";

const DAY = 86_400_000;
const PATH = "/admin/cyrus-tokens";

async function guard() {
  const admin = await requireArea("billing");
  if (!(await isPreviewUser(await realUser(), "modbuilder"))) notFound();
  return admin;
}

async function targetUser(raw: FormDataEntryValue | null) {
  const v = String(raw ?? "").trim();
  if (!v) return null;
  return db.user.findFirst({ where: v.includes("@") ? { email: { equals: v, mode: "insensitive" } } : { id: v } });
}

const back = (q: string) => redirect(`${PATH}?${q}`);

export async function adminGrantTokens(fd: FormData) {
  const admin = await guard();
  const u = await targetUser(fd.get("user"));
  const amount = Math.floor(Number(fd.get("amount")));
  const note = String(fd.get("note") ?? "").trim().slice(0, 200);
  if (!u) back("err=" + encodeURIComponent("No such account."));
  if (!(amount > 0 && amount <= 1_000_000)) back("err=" + encodeURIComponent("Amount must be 1 to 1,000,000."));
  const cfg = await loadTokenConfig();
  const days = Math.floor(Number(fd.get("days"))) || cfg.adminGrantExpiryDays;
  const r = await creditTokens({
    userId: u!.id, amount, kind: "grant", source: "admin", sourceRef: admin.id,
    // A fresh key per submit; a double-submit within the same request id is prevented by the form token.
    idemKey: `admin:${String(fd.get("token") || randomBytes(8).toString("hex"))}`,
    expiresAt: new Date(Date.now() + Math.min(3650, Math.max(1, days)) * DAY),
    note: note || "Admin grant", actorId: admin.id,
  });
  await db.auditLog.create({ data: { userId: admin.id, action: "cyrus.tokens.grant", detail: `${u!.email} +${r.amount} ${note}`.slice(0, 500) } }).catch(() => {});
  back(r.created ? `ok=${encodeURIComponent(`Granted ${r.amount} tokens to ${u!.email}.`)}` : "ok=" + encodeURIComponent("Already applied."));
}

export async function adminRevokeTokens(fd: FormData) {
  const admin = await guard();
  const u = await targetUser(fd.get("user"));
  const amount = Math.floor(Number(fd.get("amount")));
  const note = String(fd.get("note") ?? "").trim().slice(0, 200);
  if (!u) back("err=" + encodeURIComponent("No such account."));
  if (!(amount > 0)) back("err=" + encodeURIComponent("Amount must be positive."));
  const r = await revokeTokens({ userId: u!.id, amount, idemKey: `admin-revoke:${String(fd.get("token") || randomBytes(8).toString("hex"))}`, note: note || "Admin revoke", actorId: admin.id });
  await db.auditLog.create({ data: { userId: admin.id, action: "cyrus.tokens.revoke", detail: `${u!.email} -${r.revoked} ${note}`.slice(0, 500) } }).catch(() => {});
  back(`ok=${encodeURIComponent(`Removed ${r.revoked} tokens from ${u!.email} (never below zero, never a running build's hold).`)}`);
}

export async function adminSetTierOverride(fd: FormData) {
  const admin = await guard();
  const u = await targetUser(fd.get("user"));
  const tier = String(fd.get("tier") ?? "");
  const days = Math.floor(Number(fd.get("days")));
  if (!u) back("err=" + encodeURIComponent("No such account."));
  const t = tier === "katara" || tier === "saka" || tier === "all" ? tier : null;
  const until = t && days > 0 ? new Date(Date.now() + days * DAY) : null;
  await db.cyrusTokenAccount.upsert({ where: { userId: u!.id }, create: { userId: u!.id, tierOverride: t, tierOverrideUntil: until }, update: { tierOverride: t, tierOverrideUntil: until } });
  await db.auditLog.create({ data: { userId: admin.id, action: "cyrus.tokens.tier", detail: `${u!.email} ${t ?? "none"}${until ? ` until ${until.toISOString().slice(0, 10)}` : ""}` } }).catch(() => {});
  back(`ok=${encodeURIComponent(t ? `${u!.email} now has ${t} models${until ? ` until ${until.toISOString().slice(0, 10)}` : ""}.` : `Override removed for ${u!.email}.`)}`);
}

export async function adminSaveTokenSettings(fd: FormData) {
  const admin = await guard();
  const changed: string[] = [];
  for (const k of TOKEN_SETTING_KEYS) {
    if (!fd.has(k)) continue;
    const v = String(fd.get(k) ?? "").trim();
    if (k === "cyrus_tok_reserve_table") { try { JSON.parse(v); } catch { back("err=" + encodeURIComponent("Reserve table must be valid JSON.")); } }
    const row = await db.setting.findUnique({ where: { key: k } });
    const def = CYRUS_TOKEN_DEFAULTS[k as TokenSettingKey];
    if (v === "" || v === def) { if (row) { await db.setting.delete({ where: { key: k } }); changed.push(`${k}=default`); } continue; }
    if (row?.value === v) continue;
    await db.setting.upsert({ where: { key: k }, update: { value: v }, create: { key: k, value: v } });
    changed.push(`${k}=${v.slice(0, 60)}`);
  }
  clearTokenConfigCache();
  if (changed.length) await db.auditLog.create({ data: { userId: admin.id, action: "cyrus.tokens.settings", detail: changed.join(" ").slice(0, 1000) } }).catch(() => {});
  back(`ok=${encodeURIComponent(changed.length ? `Saved ${changed.length} setting(s).` : "No changes.")}`);
}
// Cyrus token ledger: the ONLY code that moves tokens. Server only; plain module
// (safe in the worker). See docs/DOCUMENTATION.md "Cyrus token economy".
//
// Invariants:
//  - Every write runs in one transaction that first locks the account row (FOR UPDATE),
//    so all of one account's token operations are serialised.
//  - CyrusTokenLedger is append-only; `idemKey` is UNIQUE. An operation whose key already
//    exists is a no-op that reports `created: false` (webhook retries, re-runs, double clicks).
//  - Balance = SUM(lot.remaining) over unexpired lots. Due lots are expired (with a ledger
//    row) at the start of every operation, so a stale lot is never spent.
//  - Reserving moves nothing: it only raises `reserved`. Settling spends the ACTUAL cost
//    from lots (soonest-expiring first) and drops the hold. Nothing goes below zero; a cost
//    above what the account holds is recorded as a write-off (Nxeon absorbs it).
import { Prisma } from "@prisma/client";
import { db } from "../../db";

export type Tx = Prisma.TransactionClient;
const DAY = 86_400_000;

export type LedgerKind = "grant" | "purchase" | "reserve" | "spend" | "release" | "refund" | "expire" | "revoke";
export type LotSource = "server_initial" | "server_renewal" | "plan" | "topup" | "admin" | "refund";

class Duplicate extends Error {}

function isUniqueViolation(e: unknown): boolean {
  return (e as { code?: string })?.code === "P2002";
}

async function lock(tx: Tx, userId: string): Promise<{ createdAt: Date }> {
  await tx.$executeRaw`INSERT INTO "CyrusTokenAccount" ("userId", "updatedAt") VALUES (${userId}, now()) ON CONFLICT ("userId") DO NOTHING`;
  const rows = await tx.$queryRaw<{ createdAt: Date }[]>`SELECT "createdAt" FROM "CyrusTokenAccount" WHERE "userId" = ${userId} FOR UPDATE`;
  return rows[0];
}

async function sums(tx: Tx, userId: string): Promise<{ balance: number; reserved: number }> {
  const [b, r] = await Promise.all([
    tx.cyrusTokenLot.aggregate({ where: { userId, remaining: { gt: 0 } }, _sum: { remaining: true } }),
    tx.cyrusTokenReservation.aggregate({ where: { userId, status: "held" }, _sum: { amount: true } }),
  ]);
  return { balance: b._sum.remaining ?? 0, reserved: r._sum.amount ?? 0 };
}

async function store(tx: Tx, userId: string, extra: Prisma.CyrusTokenAccountUpdateInput = {}): Promise<{ balance: number; reserved: number }> {
  const s = await sums(tx, userId);
  await tx.cyrusTokenAccount.update({ where: { userId }, data: { balance: s.balance, reserved: s.reserved, ...extra } });
  return s;
}

type LedgerRow = Omit<Prisma.CyrusTokenLedgerUncheckedCreateInput, "balanceAfter" | "reservedAfter" | "userId" | "kind" | "delta" | "idemKey"> & {
  kind: LedgerKind; delta: number; idemKey: string;
};

async function writeLedger(tx: Tx, userId: string, row: LedgerRow, after: { balance: number; reserved: number }) {
  return tx.cyrusTokenLedger.create({ data: { ...row, userId, balanceAfter: after.balance, reservedAfter: after.reserved } });
}

async function exists(tx: Tx, idemKey: string) {
  return !!(await tx.cyrusTokenLedger.findUnique({ where: { idemKey }, select: { id: true } }));
}

/** Expire every due lot of this account (one ledger row per lot, idempotent per lot). */
async function expireDue(tx: Tx, userId: string, now: Date): Promise<number> {
  const due = await tx.cyrusTokenLot.findMany({ where: { userId, remaining: { gt: 0 }, expiresAt: { lte: now } }, orderBy: { expiresAt: "asc" } });
  let total = 0;
  for (const lot of due) {
    const key = `expire:${lot.id}`;
    if (await exists(tx, key)) continue;
    await tx.cyrusTokenLot.update({ where: { id: lot.id }, data: { remaining: 0 } });
    total += lot.remaining;
    const after = await sums(tx, userId);
    await writeLedger(tx, userId, { kind: "expire", delta: -lot.remaining, idemKey: key, source: lot.source, sourceRef: lot.sourceRef, lotId: lot.id, note: "expired" }, after);
  }
  if (due.length) await store(tx, userId);
  return total;
}

/** Take up to `amount` from the account's lots, soonest-expiring first. */
async function drawLots(tx: Tx, userId: string, amount: number, where: Prisma.CyrusTokenLotWhereInput = {}): Promise<{ taken: number; draws: { lotId: string; n: number }[] }> {
  if (amount <= 0) return { taken: 0, draws: [] };
  const lots = await tx.cyrusTokenLot.findMany({
    where: { userId, remaining: { gt: 0 }, ...where },
    orderBy: [{ expiresAt: { sort: "asc", nulls: "last" } }, { createdAt: "asc" }],
  });
  let left = amount;
  const draws: { lotId: string; n: number }[] = [];
  for (const lot of lots) {
    if (left <= 0) break;
    const n = Math.min(left, lot.remaining);
    await tx.cyrusTokenLot.update({ where: { id: lot.id }, data: { remaining: lot.remaining - n } });
    draws.push({ lotId: lot.id, n });
    left -= n;
  }
  return { taken: amount - left, draws };
}

async function run<T>(userId: string, fn: (tx: Tx, acct: { createdAt: Date }) => Promise<T>): Promise<T | typeof DUP> {
  try {
    return await db.$transaction(async (tx) => fn(tx, await lock(tx, userId)), { timeout: 20_000, maxWait: 10_000 });
  } catch (e) {
    if (e instanceof Duplicate || isUniqueViolation(e)) return DUP;
    throw e;
  }
}
const DUP = Symbol("duplicate");

// ---------------------------------------------------------------------------
// Credits
// ---------------------------------------------------------------------------

export type CreditInput = {
  userId: string;
  amount: number;
  kind: "grant" | "purchase" | "refund";
  source: LotSource;
  sourceRef?: string | null;
  idemKey: string;
  expiresAt?: Date | null;
  note?: string | null;
  meta?: Prisma.InputJsonValue;
  actorId?: string | null;
  now?: Date;
  /** Runs under the account lock before crediting: cap the amount (abuse limits). */
  clamp?: (tx: Tx, amount: number, now: Date) => Promise<{ amount: number; note?: string }>;
};

export type CreditResult = { created: boolean; amount: number; lotId: string | null; note?: string | null };

/** Add tokens (a new lot). Idempotent on idemKey; a zero amount still writes the row (so a capped grant is final). */
export async function creditTokens(i: CreditInput): Promise<CreditResult> {
  const now = i.now ?? new Date();
  const r = await run(i.userId, async (tx) => {
    if (await exists(tx, i.idemKey)) throw new Duplicate();
    await expireDue(tx, i.userId, now);
    let amount = Math.max(0, Math.floor(i.amount));
    let note = i.note ?? null;
    if (i.clamp) {
      const c = await i.clamp(tx, amount, now);
      if (c.amount < amount) note = [note, c.note].filter(Boolean).join("; ") || null;
      amount = Math.max(0, Math.floor(c.amount));
    }
    let lotId: string | null = null;
    if (amount > 0) {
      const lot = await tx.cyrusTokenLot.create({ data: { userId: i.userId, source: i.source, sourceRef: i.sourceRef ?? null, amount, remaining: amount, expiresAt: i.expiresAt ?? null } });
      lotId = lot.id;
    }
    const after = await store(tx, i.userId, amount > 0 ? { lifetimeGranted: { increment: amount } } : {});
    await writeLedger(tx, i.userId, { kind: i.kind, delta: amount, idemKey: i.idemKey, source: i.source, sourceRef: i.sourceRef ?? null, lotId, note, meta: i.meta, actorId: i.actorId ?? null }, after);
    return { created: true, amount, lotId, note };
  });
  if (r === DUP) {
    const prev = await db.cyrusTokenLedger.findUnique({ where: { idemKey: i.idemKey } });
    return { created: false, amount: prev?.delta ?? 0, lotId: prev?.lotId ?? null, note: prev?.note };
  }
  return r;
}

// ---------------------------------------------------------------------------
// Builds: reserve -> settle / release
// ---------------------------------------------------------------------------

export type ReserveResult =
  | { ok: true; amount: number; created: boolean; available: number }
  | { ok: false; code: "insufficient_tokens" | "daily_cap"; available: number; need: number; usedToday?: number; cap?: number };

/**
 * Hold tokens for a build. `pick(available)` returns the amount to hold (or null = not
 * enough). `dailyCap(createdAt)` bounds reserve+spend per rolling 24 h. Idempotent per buildId.
 */
export async function reserveTokens(i: {
  userId: string; buildId: string; model: string; need: number;
  pick: (available: number) => number | null;
  dailyCap: (accountCreatedAt: Date) => number;
  allowShort?: boolean;
  now?: Date;
}): Promise<ReserveResult> {
  const now = i.now ?? new Date();
  const r = await run(i.userId, async (tx, acct) => {
    const prev = await tx.cyrusTokenReservation.findUnique({ where: { buildId: i.buildId } });
    if (prev) return { ok: true as const, amount: prev.amount, created: false, available: 0 };
    await expireDue(tx, i.userId, now);
    const s = await sums(tx, i.userId);
    const available = Math.max(0, s.balance - s.reserved);
    let amount = i.pick(available);
    if (amount === null) {
      if (!i.allowShort) return { ok: false as const, code: "insufficient_tokens" as const, available, need: i.need };
      amount = Math.min(available, i.need);
    }
    const since = new Date(now.getTime() - DAY);
    const recent = await tx.cyrusTokenReservation.findMany({ where: { userId: i.userId, createdAt: { gt: since } }, select: { status: true, amount: true, charged: true } });
    const usedToday = recent.reduce((a, x) => a + (x.status === "held" ? x.amount : x.charged ?? 0), 0);
    const cap = i.dailyCap(acct.createdAt);
    if (!i.allowShort && usedToday + amount > cap) return { ok: false as const, code: "daily_cap" as const, available, need: amount, usedToday, cap };
    await tx.cyrusTokenReservation.create({ data: { buildId: i.buildId, userId: i.userId, model: i.model, amount, status: "held", createdAt: now } });
    const after = await store(tx, i.userId);
    await writeLedger(tx, i.userId, { kind: "reserve", delta: 0, idemKey: `reserve:${i.buildId}`, buildId: i.buildId, model: i.model, meta: { hold: amount } }, after);
    return { ok: true as const, amount, created: true, available: available - amount };
  });
  if (r === DUP) return { ok: true, amount: 0, created: false, available: 0 };
  return r;
}

export type SettleResult = { settled: boolean; charged: number; writeoff: number; released: number; reason: string };

/**
 * Finish a build's hold: spend `charge` tokens (the ACTUAL cost, decided by the caller),
 * release the rest. Idempotent: a reservation that is no longer held is returned as-is.
 */
export async function settleReservation(i: { buildId: string; charge: number; reason: string; costUsd?: number | null; now?: Date }): Promise<SettleResult | null> {
  const res = await db.cyrusTokenReservation.findUnique({ where: { buildId: i.buildId } });
  if (!res) return null;
  const now = i.now ?? new Date();
  const r = await run(res.userId, async (tx) => {
    const cur = await tx.cyrusTokenReservation.findUnique({ where: { buildId: i.buildId } });
    if (!cur || cur.status !== "held") return { settled: false, charged: cur?.charged ?? 0, writeoff: 0, released: 0, reason: "already" };
    await expireDue(tx, res.userId, now);
    const want = Math.max(0, Math.ceil(i.charge));
    const { taken, draws } = await drawLots(tx, res.userId, want);
    const writeoff = want - taken;
    await tx.cyrusTokenReservation.update({ where: { buildId: i.buildId }, data: { status: want > 0 ? "settled" : "released", charged: taken, costUsd: i.costUsd ?? null, settledAt: now } });
    const after = await store(tx, res.userId, taken > 0 ? { lifetimeSpent: { increment: taken } } : {});
    const released = Math.max(0, cur.amount - taken);
    await writeLedger(tx, res.userId, {
      kind: want > 0 ? "spend" : "release",
      delta: -taken,
      idemKey: `settle:${i.buildId}`,
      buildId: i.buildId,
      model: cur.model,
      note: i.reason,
      meta: { hold: cur.amount, released, writeoff, costUsd: i.costUsd ?? null, draws },
    }, after);
    return { settled: true, charged: taken, writeoff, released, reason: i.reason };
  });
  if (r === DUP) return { settled: false, charged: 0, writeoff: 0, released: 0, reason: "already" };
  return r;
}

// ---------------------------------------------------------------------------
// Revoke / expire / rollover
// ---------------------------------------------------------------------------

/** Remove up to `amount` unspent tokens (refunds, admin revoke). Never below zero. Idempotent. */
export async function revokeTokens(i: {
  userId: string; amount: number; idemKey: string; note?: string; actorId?: string | null; sourceRef?: string | null;
  /** Restrict to these lots (e.g. the lot a refunded invoice granted); falls back to nothing else. */
  lotIds?: string[];
  meta?: Prisma.InputJsonValue;
  now?: Date;
}): Promise<{ created: boolean; revoked: number }> {
  const now = i.now ?? new Date();
  const r = await run(i.userId, async (tx) => {
    if (await exists(tx, i.idemKey)) throw new Duplicate();
    await expireDue(tx, i.userId, now);
    // Never take tokens a running build already holds.
    const s0 = await sums(tx, i.userId);
    const free = Math.max(0, s0.balance - s0.reserved);
    const want = Math.min(Math.max(0, Math.floor(i.amount)), free);
    const { taken, draws } = await drawLots(tx, i.userId, want, i.lotIds ? { id: { in: i.lotIds } } : {});
    const after = await store(tx, i.userId);
    await writeLedger(tx, i.userId, { kind: "revoke", delta: -taken, idemKey: i.idemKey, sourceRef: i.sourceRef ?? null, note: i.note ?? null, actorId: i.actorId ?? null, meta: { requested: i.amount, draws, ...(i.meta && typeof i.meta === "object" ? (i.meta as object) : {}) } }, after);
    return { created: true, revoked: taken };
  });
  if (r === DUP) return { created: false, revoked: 0 };
  return r;
}

/** Shorten the expiry of an account's lots of one source (a plan ended). Not a token move. */
export async function capLotExpiry(userId: string, source: LotSource, expiresAt: Date): Promise<number> {
  const r = await db.cyrusTokenLot.updateMany({
    where: { userId, source, remaining: { gt: 0 }, OR: [{ expiresAt: null }, { expiresAt: { gt: expiresAt } }] },
    data: { expiresAt },
  });
  return r.count;
}

/** Expire due lots for one account (or every account with due lots). */
export async function expireDueLots(userId?: string, now = new Date()): Promise<number> {
  const users = userId
    ? [userId]
    : (await db.cyrusTokenLot.findMany({ where: { remaining: { gt: 0 }, expiresAt: { lte: now } }, select: { userId: true }, distinct: ["userId"], take: 500 })).map((x) => x.userId);
  let total = 0;
  for (const u of users) {
    const r = await run(u, async (tx) => expireDue(tx, u, now));
    if (r !== DUP) total += r;
  }
  return total;
}

// ---------------------------------------------------------------------------
// Reads
// ---------------------------------------------------------------------------

export type TokenSummary = {
  balance: number;
  reserved: number;
  available: number;
  bySource: Record<string, number>;
  nextExpiry: { at: string; amount: number } | null;
  lifetimeGranted: number;
  lifetimeSpent: number;
};

/** Live summary (ignores lots that are past expiry but not swept yet). */
export async function tokenSummary(userId: string, now = new Date()): Promise<TokenSummary> {
  const live = { userId, remaining: { gt: 0 }, OR: [{ expiresAt: null }, { expiresAt: { gt: now } }] };
  const [lots, held, acct] = await Promise.all([
    db.cyrusTokenLot.findMany({ where: live, select: { source: true, remaining: true, expiresAt: true }, orderBy: { expiresAt: { sort: "asc", nulls: "last" } } }),
    db.cyrusTokenReservation.aggregate({ where: { userId, status: "held" }, _sum: { amount: true } }),
    db.cyrusTokenAccount.findUnique({ where: { userId } }),
  ]);
  const bySource: Record<string, number> = {};
  let balance = 0;
  for (const l of lots) { balance += l.remaining; bySource[l.source] = (bySource[l.source] ?? 0) + l.remaining; }
  const first = lots.find((l) => l.expiresAt);
  const reserved = held._sum.amount ?? 0;
  return {
    balance, reserved, available: Math.max(0, balance - reserved), bySource,
    nextExpiry: first?.expiresAt ? { at: first.expiresAt.toISOString(), amount: lots.filter((l) => l.expiresAt && l.expiresAt.getTime() === first.expiresAt!.getTime()).reduce((a, l) => a + l.remaining, 0) } : null,
    lifetimeGranted: acct?.lifetimeGranted ?? 0,
    lifetimeSpent: acct?.lifetimeSpent ?? 0,
  };
}

export async function ledgerPage(userId: string, opts: { take?: number; before?: string | null } = {}) {
  const take = Math.min(100, Math.max(1, opts.take ?? 30));
  const rows = await db.cyrusTokenLedger.findMany({
    where: { userId, ...(opts.before ? { createdAt: { lt: new Date(opts.before) } } : {}) },
    orderBy: [{ createdAt: "desc" }, { id: "desc" }],
    take: take + 1,
  });
  return { rows: rows.slice(0, take), more: rows.length > take };
}
// Cyrus builds and tokens: gate + reserve when a build starts, settle when it ends.
// Server only; plain module (store.ts calls settleBuildTokens from the worker sweep too).
import type { ModBuild, User } from "@prisma/client";
import { db } from "../../db";
import { cyrusModel, isCyrusModel, type CyrusModelId } from "../models";
import { readCyrusMeta } from "../meta";
import { loadTokenConfig } from "./config";
import { canUseModel, complexityOf, dailyCapFor, defaultModelFor, reserveAmount, reserveRange, settleCharge, TIER_LABEL, tierForModel, fmt } from "./economy";
import { reserveTokens, settleReservation } from "./ledger";
import { tierOf, tokensActiveFor } from "./access";

const DAY = 86_400_000;

export type BuildGate =
  | { ok: true; model: CyrusModelId | undefined; reserved: number | null; tracked: boolean }
  | { ok: false; status: number; code: "model_locked" | "insufficient_tokens" | "daily_cap"; error: string; need?: number; available?: number; model?: CyrusModelId; tier?: string };

/**
 * Decide the model and hold tokens for a build that is about to start. Call AFTER the
 * request is validated and rate-limited, BEFORE the ModBuild row is created, with the id
 * the row will get. Accounts outside the token economy (not live, not preview) pass
 * through unchanged (`tracked: false`), keeping the pre-token behaviour.
 */
export async function gateBuild(i: { user: User; buildId: string; requested: CyrusModelId | undefined; baseModel: CyrusModelId | undefined; text: string; now?: Date }): Promise<BuildGate> {
  const cfg = await loadTokenConfig();
  if (!(await tokensActiveFor(i.user, cfg))) return { ok: true, model: i.requested ?? i.baseModel, reserved: null, tracked: false };
  const now = i.now ?? new Date();
  const tier = await tierOf(i.user.id, cfg, now);
  let model: CyrusModelId = i.requested ?? i.baseModel ?? defaultModelFor(tier);
  // A change to a version built on a locked model falls back to the best allowed one
  // unless the customer explicitly asked for the locked model.
  if (!i.requested && !canUseModel(tier, model)) model = defaultModelFor(tier);
  if (cfg.enforce && !canUseModel(tier, model)) {
    const need = tierForModel(model);
    return { ok: false, status: 403, code: "model_locked", model, tier, error: `${cyrusModel(model).name} unlocks with the ${TIER_LABEL[need]} plan. Get tokens to unlock it, or pick ${tier === "free" || tier === "katara" ? "Katara" : "Saka"}.` };
  }
  const range = reserveRange(model, complexityOf(i.text), cfg);
  const r = await reserveTokens({
    userId: i.user.id, buildId: i.buildId, model, need: range[0], now,
    pick: (available) => reserveAmount(available, range),
    dailyCap: () => dailyCapFor(i.user.createdAt, now, cfg),
    allowShort: !cfg.enforce,
  });
  if (!r.ok) {
    if (r.code === "daily_cap") return { ok: false, status: 429, code: "daily_cap", error: `You've used today's Cyrus limit (${fmt(r.cap ?? 0)} tokens a day). It frees up over the next 24 hours.` };
    return { ok: false, status: 402, code: "insufficient_tokens", need: range[0], available: r.available, model, error: `This build needs about ${fmt(range[0])} tokens and you have ${fmt(r.available)}. Get tokens to keep building.` };
  }
  return { ok: true, model, reserved: r.amount, tracked: true };
}

/** A build that never reached the builder (create failed): give the whole hold back. */
export async function releaseBuildTokens(buildId: string): Promise<void> {
  await settleReservation({ buildId, charge: 0, reason: "not_started" }).catch((e) => console.error("[cyrus-tokens] release failed", buildId, (e as Error).message));
}

/**
 * Settle a FINISHED build against its hold. Idempotent (no-op for unheld or non-terminal
 * builds), so the routes, the page loader and the worker can all call it.
 */
export async function settleBuildTokens(row: Pick<ModBuild, "id" | "userId" | "status" | "errorCode" | "costUsd" | "cyrus">, now = new Date()): Promise<void> {
  if (row.status !== "succeeded" && row.status !== "failed") return;
  const res = await db.cyrusTokenReservation.findUnique({ where: { buildId: row.id } });
  if (!res || res.status !== "held") return;
  const cfg = await loadTokenConfig();
  const model: CyrusModelId = isCyrusModel(res.model) ? res.model : (readCyrusMeta(row.cyrus).model ?? "saka");
  const freeFailuresUsed = await db.cyrusTokenLedger.count({ where: { userId: row.userId, note: "failed_free", createdAt: { gt: new Date(now.getTime() - cfg.freeFailuresDays * DAY) } } });
  const d = settleCharge({ status: row.status, errorCode: row.errorCode, costUsd: row.costUsd || 0, model, freeFailuresUsed }, cfg);
  await settleReservation({ buildId: row.id, charge: d.charge, reason: d.reason, costUsd: row.costUsd || 0, now });
}

export async function safeSettle(row: Parameters<typeof settleBuildTokens>[0]): Promise<void> {
  try { await settleBuildTokens(row); } catch (e) { console.error("[cyrus-tokens] settle failed", row.id, (e as Error).message); }
}

