/// One row per account that ever held Cyrus tokens. Locked FOR UPDATE by every
/// ledger operation, so all of one account's token writes are serialised.
/// `balance` and `reserved` are caches: the truth is SUM(CyrusTokenLot.remaining)
/// over unexpired lots, and SUM(CyrusTokenReservation.amount) over held holds.
model CyrusTokenAccount {
  userId          String    @id
  balance         Int       @default(0)
  reserved        Int       @default(0)
  lifetimeGranted Int       @default(0)
  lifetimeSpent   Int       @default(0)
  /// Admin comp: "katara" | "saka" | "all" — entitles models without a paid plan.
  tierOverride    String?
  tierOverrideUntil DateTime?
  createdAt       DateTime  @default(now())
  updatedAt       DateTime  @updatedAt
}

/// A bucket of tokens with its own source and expiry. Spends draw from the
/// soonest-expiring lot first. `remaining` only ever goes down (spend, expire, revoke).
model CyrusTokenLot {
  id        String    @id @default(cuid())
  userId    String
  /// server_initial | server_renewal | plan | topup | admin | refund
  source    String
  /// serverId / Stripe invoice id / Checkout session id / admin user id / build id
  sourceRef String?
  amount    Int
  remaining Int
  expiresAt DateTime?
  createdAt DateTime  @default(now())

  @@index([userId, expiresAt])
  @@index([source, createdAt])
}

/// Append-only. Never updated or deleted. `idemKey` is UNIQUE: replaying a grant,
/// a webhook or a settle can never write a second row (and so never moves tokens twice).
model CyrusTokenLedger {
  id           String   @id @default(cuid())
  userId       String
  /// grant | purchase | reserve | spend | release | refund | expire | revoke
  kind         String
  /// Signed change to the account balance (reserve/release are 0: they move `reserved`).
  delta        Int
  balanceAfter Int
  reservedAfter Int     @default(0)
  idemKey      String   @unique
  source       String?
  sourceRef    String?
  buildId      String?
  lotId        String?
  model        String?
  note         String?
  meta         Json?
  /// Admin who made a manual grant/revoke.
  actorId      String?
  createdAt    DateTime @default(now())

  @@index([userId, createdAt])
  @@index([kind, createdAt])
  @@index([sourceRef])
}

/// Tokens held for one build while it runs (keyed by the ModBuild id).
model CyrusTokenReservation {
  buildId   String    @id
  userId    String
  model     String
  amount    Int
  /// held | settled | released
  status    String    @default("held")
  charged   Int?
  costUsd   Float?
  createdAt DateTime  @default(now())
  settledAt DateTime?

  @@index([userId, status])
  @@index([status, createdAt])
}

/// The account's Cyrus plan (Stripe Billing subscription). One per account; a
