+    tokens: { input: uncached + cacheWrite + cacheRead, cacheRead, output, uncached, cacheWrite },
+    turnsDetail: rows.slice(0, MAX_TURN_ROWS),
+    toolCalls: { ...meter.tools },
+    apiMs: meter.result ? n(meter.result.duration_api_ms) || null : null,
