+
+// ------------------------------------------------------------- stages ----
+function stage(rec, name) {
+  if (!rec.usage || typeof rec.usage !== "object") rec.usage = { stages: {}, autofix: 0, savedRepairs: 0 };
+  if (!rec.usage.stages[name]) rec.usage.stages[name] = { n: 0, ms: 0 };
+  return rec.usage.stages[name];
+}
+/** Wall time of a non-AI stage (validate, precheck, compile, scan, autofix, reuse). */
+function addTime(rec, name, ms) {
+  const s = stage(rec, name);
+  s.n += 1;
+  s.ms += Math.max(0, Math.round(ms));
+}
+/** One AI call into its stage (classify / generate / change / repair / repair-safety). */
+function addCall(rec, call) {
+  const s = stage(rec, call.kind || "generate");
+  s.n += 1;
+  s.ms += n(call.durationMs);
+  s.costUsd = +((s.costUsd || 0) + n(call.costUsd)).toFixed(4);
+  s.turns = (s.turns || 0) + n(call.turns);
