    // Cold email: unread replies in the reply inbox.
    soft(db.conversation.count({ where: { unread: true } })),
    // Jobs: failures in the last 24h (same window as the command center card).
    soft(db.job.count({ where: { status: "FAILED", updatedAt: { gte: new Date(Date.now() - 24 * 3600_000) } } })),
  ]);

  // Per-route attention counts. An item's badge is the SUM of its own and its
  // children's counts, and <AdminSubTabs /> repeats each child's own count.
  const badges: Record<string, number> = {
    "/admin/chat": chatUnread,
    "/admin/support": ticketsAwaiting,
    "/admin/dms": dmsAwaiting,
    "/admin/abuse": abuseOpen,
    "/admin/feedback": feedbackNew,
    "/admin/improvements": improvementsProposed,
    "/admin/coldemail/inbox": coldEmailUnread,
    "/admin/jobs": jobsFailed24h,
  };

  // RBAC-filter the registry (lib/admin-nav.ts) into what the shell renders.
  // An item links to its first ACCESSIBLE child so no role is ever handed a
  // link that just bounces it to /admin.
  const nav: ShellNavGroup[] = ADMIN_NAV_GROUPS.map((g) => ({
    key: g.key,
    label: g.label,
    items: g.items.flatMap((it): ShellNavItem[] => {
      if (!entryLive(it, flags)) return [];
      const kids = (it.children ?? []).filter((c) => allowedEntry(c, it.area));
      if (it.children?.length ? kids.length === 0 : !allowedEntry(it)) return [];
      const members = kids.length ? kids : [it];
      const sum = members.reduce((n, c) => n + (badges[c.href] ?? 0), 0);
      return [{
        key: it.key,
        label: it.label,
        href: members[0].href,
        icon: it.icon,
        more: it.more,
        badge: sum > 0 ? sum : undefined,
        children: kids.length
          ? kids.map((c) => ({ label: c.label, href: c.href, badge: badges[c.href] > 0 ? badges[c.href] : undefined }))
          : undefined,
      }];
    }),
  })).filter((g) => g.items.length > 0);

  const allowedHrefs = nav.flatMap((g) => g.items.flatMap((i) => (i.children ?? [{ href: i.href }]).map((c) => c.href)));
  const allowedSet = new Set(allowedHrefs);
  const routes: ShellRoute[] = flatAdminRoutes()
    .filter((r) => allowedSet.has(r.href))
    .map((r) => ({ label: r.label, href: r.href, group: r.group, parent: r.parent, keywords: r.keywords }));

  const alerts = await loadShellAlerts(user.role);
  const liveChat = await hasAreaAccess(user, "liveChat").catch(() => false);
  const ui = parseUiCookie((await cookies()).get(ADM_UI_COOKIE)?.value);

  return (
    <>
      {/* Before first paint: scope class + the admin's own theme/density
          preference, so there is no flash of the wrong theme. See
          app/admin/admin-shell.css for why these are NOT the customer
          portal's `data-theme`. */}
      <script
        dangerouslySetInnerHTML={{
          __html:
            "try{var d=document.documentElement;d.classList.add('adm-portal');d.removeAttribute('data-theme');" +
            "var t=localStorage.getItem('nxeon.admin.theme');if(t==='light'||t==='dark')d.setAttribute('data-adm-theme',t);" +
            "if(localStorage.getItem('nxeon.admin.density')==='compact')d.setAttribute('data-adm-density','compact')}catch(e){}",
        }}
      />
      <AdminShell
        nav={nav}
        routes={routes}
        user={{ name: user.name, email: user.email, role: user.role, avatarUrl: user.avatarUrl }}
        alerts={alerts}
        initialUi={ui}
        notifications={notifications.map((n) => ({
          id: n.id,
          title: n.title,
          body: n.body,
          href: n.href,
          readAt: n.readAt ? n.readAt.toISOString() : null,
          createdAt: n.createdAt.toISOString(),
        }))}
      >
        {/* Sub-navigation for items with children, mounted once here so every
            grouped page gets its tab bar without per-page wiring. */}
        <AdminSubTabs badges={badges} allowed={allowedHrefs} />
        {liveChat ? (
          /* ONE live-chat store + event stream per admin tab, mounted at the
             layout so it survives client navigation: the /admin/chat workspace
             and the persistent dock (every other /admin page) share it, and
             ChatNotifier plays the sound / desktop alert from the same stream
             (it replaced the old 10 s unread-count poll). */
          <StaffChatProvider>
            <ChatNotifier />
            {children}
            <ChatDock />
          </StaffChatProvider>
        ) : (
          children
        )}
      </AdminShell>
    </>
  );
}
