async function requireViewer(mode: "read" | "write" = "write"): Promise<{ user: User | null; allowed: boolean }> {
  let user: User | null = null;
  let real: User | null = null;
  try {
    [user, real] = await Promise.all([currentUser(), realUser()]);
  } catch {
    user = null;
  }
  const a = await cyrusAccessFor(user);
  if (mode === "write" && user && (!real || real.id !== user.id)) return { user: null, allowed: a.allowed };
  return { user, allowed: a.allowed };
}

