/* Dependency-free SVG charts, safe to render in server components. */

function pathFrom(points: [number, number][], smooth = true): string {
  if (points.length === 0) return "";
  if (!smooth || points.length < 3) {
    return points.map(([x, y], i) => `${i === 0 ? "M" : "L"}${x.toFixed(2)},${y.toFixed(2)}`).join(" ");
  }
  let d = `M${points[0][0].toFixed(2)},${points[0][1].toFixed(2)}`;
  for (let i = 1; i < points.length; i++) {
    const [x0, y0] = points[i - 1];
    const [x1, y1] = points[i];
    const cx = (x0 + x1) / 2;
    d += ` C${cx.toFixed(2)},${y0.toFixed(2)} ${cx.toFixed(2)},${y1.toFixed(2)} ${x1.toFixed(2)},${y1.toFixed(2)}`;
  }
  return d;
}

function scale(data: number[], w: number, h: number, pad = 2, max?: number): [number, number][] {
  const mx = max ?? Math.max(...data, 1e-9);
  const mn = 0;
  const n = Math.max(data.length - 1, 1);
  return data.map((v, i) => [
    (i / n) * (w - pad * 2) + pad,
    h - pad - ((v - mn) / (mx - mn || 1)) * (h - pad * 2),
  ]);
}

export function Sparkline({
  data,
  width = 120,
  height = 36,
  stroke = "#8a70fb",
  id,
}: {
  data: number[];
  width?: number;
  height?: number;
  stroke?: string;
  id: string;
}) {
  if (data.length === 0) return null;
  const pts = scale(data, width, height);
  const line = pathFrom(pts);
  const area = `${line} L${pts[pts.length - 1][0].toFixed(2)},${height} L${pts[0][0].toFixed(2)},${height} Z`;
  return (
    <svg width={width} height={height} viewBox={`0 0 ${width} ${height}`} className="overflow-visible">
      <defs>
        <linearGradient id={`sg-${id}`} x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stopColor={stroke} stopOpacity="0.35" />
          <stop offset="100%" stopColor={stroke} stopOpacity="0" />
        </linearGradient>
      </defs>
      <path d={area} fill={`url(#sg-${id})`} />
      <path d={line} fill="none" stroke={stroke} strokeWidth="1.5" strokeLinecap="round" />
    </svg>
  );
}

export function AreaChart({
  series,
  width = 720,
  height = 220,
  id,
  yLabel,
  xLabels = [],
  maxY,
}: {
  series: { name: string; data: number[]; color: string }[];
  width?: number;
  height?: number;
  id: string;
  yLabel?: (v: number) => string;
  xLabels?: string[];
  maxY?: number;
}) {
  const all = series.flatMap((s) => s.data);
  if (all.length === 0) return <p className="text-sm text-slate-500">No data yet.</p>;
  const max = maxY ?? Math.max(...all, 1e-9);
  const padL = 46;
  const padB = 22;
  const cw = width - padL - 8;
  const ch = height - padB - 8;
  const gridLines = 4;

  return (
    <div className="w-full overflow-x-auto">
      <svg
        width="100%"
        viewBox={`0 0 ${width} ${height}`}
        preserveAspectRatio="none"
        className="min-w-[480px]"
        style={{ height }}
      >
        <defs>
          {series.map((s, si) => (
            <linearGradient key={si} id={`ag-${id}-${si}`} x1="0" y1="0" x2="0" y2="1">
              <stop offset="0%" stopColor={s.color} stopOpacity="0.30" />
              <stop offset="100%" stopColor={s.color} stopOpacity="0" />
            </linearGradient>
          ))}
        </defs>
        {Array.from({ length: gridLines + 1 }, (_, i) => {
          const y = 8 + (ch / gridLines) * i;
          const v = max * (1 - i / gridLines);
          return (
            <g key={i}>
              <line x1={padL} x2={width - 8} y1={y} y2={y} stroke="rgba(255,255,255,0.05)" />
              <text x={padL - 8} y={y + 3.5} textAnchor="end" fontSize="10" fill="#64748b">
                {yLabel ? yLabel(v) : v.toFixed(0)}
              </text>
            </g>
          );
        })}
        {xLabels.map((l, i) => (
          <text
            key={i}
            x={padL + (cw / Math.max(xLabels.length - 1, 1)) * i}
            y={height - 6}
            // Edge labels anchor inward so a longer label ("Sep 28") isn't clipped by the viewBox.
            textAnchor={xLabels.length > 1 && i === 0 ? "start" : xLabels.length > 1 && i === xLabels.length - 1 ? "end" : "middle"}
            fontSize="10"
            fill="#64748b"
          >
            {l}
          </text>
        ))}
        {series.map((s, si) => {
          const pts: [number, number][] = s.data.map((v, i) => [
            padL + (i / Math.max(s.data.length - 1, 1)) * cw,
            8 + ch - (v / max) * ch,
          ]);
          const line = pathFrom(pts);
          const area = `${line} L${(padL + cw).toFixed(2)},${8 + ch} L${padL},${8 + ch} Z`;
          return (
            <g key={si}>
              <path d={area} fill={`url(#ag-${id}-${si})`} />
              <path d={line} fill="none" stroke={s.color} strokeWidth="2" strokeLinecap="round" />
            </g>
          );
        })}
      </svg>
    </div>
  );
}

// Cyrus metadata kept in ModBuild.cyrus (additive Json column). Client-safe.
//
// Per BUILD:   model (which Cyrus model was picked), attachments (pasted images).
// Per PROJECT: kept on the project's ROOT build only: title, favourite, notes,
//              headBuildId (the version the owner "restored" / marked current).
import { isCyrusModel, type CyrusModelId } from "./models";

export type CyrusAttachment = { n: number; name: string; type: string; size: number };

export type CyrusMeta = {
  model?: CyrusModelId;
  attachments?: CyrusAttachment[];
  title?: string;
  favourite?: boolean;
  notes?: string;
  headBuildId?: string;
};

export const CYRUS_NOTES_MAX = 4000;
export const CYRUS_TITLE_MAX = 60;

/** Read whatever is in the column into a clean CyrusMeta (never throws). */
export function readCyrusMeta(raw: unknown): CyrusMeta {
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return {};
  const r = raw as Record<string, unknown>;
  const out: CyrusMeta = {};
  if (isCyrusModel(r.model)) out.model = r.model;
  if (Array.isArray(r.attachments)) {
    out.attachments = r.attachments
      .filter((a): a is Record<string, unknown> => !!a && typeof a === "object")
      .map((a) => ({ n: Number(a.n) || 0, name: String(a.name ?? "image").slice(0, 120), type: String(a.type ?? ""), size: Number(a.size) || 0 }))
      .filter((a) => a.n > 0 && /^image\/(png|jpeg|webp|gif)$/.test(a.type))
      .slice(0, 8);
  }
  if (typeof r.title === "string" && r.title.trim()) out.title = r.title.trim().slice(0, CYRUS_TITLE_MAX);
  if (r.favourite === true) out.favourite = true;
  if (typeof r.notes === "string" && r.notes) out.notes = r.notes.slice(0, CYRUS_NOTES_MAX);
  if (typeof r.headBuildId === "string" && /^[A-Za-z0-9_-]{1,64}$/.test(r.headBuildId)) out.headBuildId = r.headBuildId;
  return out;
}

export type ProjectPatch = { title?: string | null; favourite?: boolean; notes?: string; headBuildId?: string | null };

/**
 * Validate a PATCH body for project meta. Returns the patch or an error string.
 * `allowedHeads` = ids of the project's succeeded builds (a head must be one).
 */
export function parseProjectPatch(body: unknown, allowedHeads: string[]): { ok: true; patch: ProjectPatch } | { ok: false; error: string } {
  if (!body || typeof body !== "object") return { ok: false, error: "Bad request" };
  const b = body as Record<string, unknown>;
  const patch: ProjectPatch = {};
  if ("title" in b) {
    if (b.title === null || b.title === "") patch.title = null;
    else if (typeof b.title === "string") {
      const t = b.title.replace(/[\u0000-\u001f]/g, "").trim();
      if (t.length > CYRUS_TITLE_MAX) return { ok: false, error: `Keep the name under ${CYRUS_TITLE_MAX} characters.` };
      patch.title = t || null;
    } else return { ok: false, error: "Bad title" };
  }
  if ("favourite" in b) {
    if (typeof b.favourite !== "boolean") return { ok: false, error: "Bad favourite" };
    patch.favourite = b.favourite;
  }
  if ("notes" in b) {
    if (typeof b.notes !== "string") return { ok: false, error: "Bad notes" };
    if (b.notes.length > CYRUS_NOTES_MAX) return { ok: false, error: `Notes are limited to ${CYRUS_NOTES_MAX.toLocaleString("en-US")} characters.` };
    patch.notes = b.notes;
  }
  if ("headBuildId" in b) {
    if (b.headBuildId === null) patch.headBuildId = null;
    else if (typeof b.headBuildId === "string" && allowedHeads.includes(b.headBuildId)) patch.headBuildId = b.headBuildId;
    else return { ok: false, error: "You can only restore a version that finished building." };
  }
  if (!Object.keys(patch).length) return { ok: false, error: "Nothing to change" };
  return { ok: true, patch };
}

/** Apply a patch to stored meta (pure). */
export function applyProjectPatch(meta: CyrusMeta, p: ProjectPatch): CyrusMeta {
  const out: CyrusMeta = { ...meta };
// Who may use the AI Mod Builder: private preview, feature "modbuilder".
// Both the effective user AND the real signed-in account must be on the
// allowlist, so impersonation can neither open it for someone else nor reveal
// it while the owner is looking at a customer's portal.
import { notFound } from "next/navigation";
import type { User } from "@prisma/client";
import { currentUser, realUser } from "../auth";
import { isPreviewUser } from "../preview-access";

export async function modBuilderUser(): Promise<User | null> {
  const [user, real] = await Promise.all([currentUser(), realUser()]);
  if (!user || !real || user.id !== real.id) return null;
  return (await isPreviewUser(user, "modbuilder")) ? user : null;
}

/** Pages: 404 for everyone outside the preview. */
export async function requireModBuilderUser(): Promise<User> {
  const u = await modBuilderUser();
  if (!u) notFound();
  return u;
}

/** Page metadata that names the feature only for preview users (a 404 must not leak it). */
export async function modBuilderMetadata(title: string) {
  const ok = !!(await modBuilderUser().catch(() => null));
  return { title: ok ? title : "Page not found", robots: { index: false, follow: false } };
}

