// Cyrus admin: the maths behind the Overview, Builds and Users tabs. PURE (no DB, no clock unless
// passed in, no network) and client-safe. Unit-tested in test/cyrus-admin.test.ts.
//
// Everything here works on rows the pages already read from the DB (ModBuild, CyrusTokenReservation,
// CyrusTokenLedger), so a number on screen is always a real count or sum, never an estimate.

const DAY = 86_400_000;

// ---------------------------------------------------------------------------
// Build outcome
// ---------------------------------------------------------------------------

export type BuildOutcome = "succeeded" | "failed" | "refused" | "cancelled" | "running";
export const BUILD_OUTCOMES: BuildOutcome[] = ["succeeded", "failed", "refused", "cancelled", "running"];

/** One build as the admin maths sees it. `model` / `game` already resolved by the caller. */
export type BuildLite = {
  id: string;
  userId: string;
  status: string;
  errorCode: string | null;
  costUsd: number;
  durationMs: number | null;
  createdAt: Date;
  model: string | null;
  game: string;
};

/** A refusal (safety) and a cancel are failures in the DB; the admin counts them apart. */
export function buildOutcome(b: { status: string; errorCode: string | null }): BuildOutcome {
  if (b.status === "succeeded") return "succeeded";
  if (b.status !== "failed") return "running";
  if (b.errorCode === "refused") return "refused";
  if (b.errorCode === "cancelled" || b.errorCode === "admin_cancelled") return "cancelled";
  return "failed";
}

// ---------------------------------------------------------------------------
// Statistics
// ---------------------------------------------------------------------------

/** Nearest-rank percentile (p in 0..100). null for an empty list. */
export function percentile(values: number[], p: number): number | null {
  const v = values.filter((x) => Number.isFinite(x)).sort((a, b) => a - b);
  if (!v.length) return null;
  const rank = Math.ceil((Math.min(100, Math.max(0, p)) / 100) * v.length);
  return v[Math.max(0, rank - 1)];
}

export function mean(values: number[]): number | null {
  const v = values.filter((x) => Number.isFinite(x));
  return v.length ? v.reduce((a, x) => a + x, 0) / v.length : null;
}

export type OutcomeCounts = Record<BuildOutcome, number> & { total: number; finished: number };

export function countOutcomes(rows: { status: string; errorCode: string | null }[]): OutcomeCounts {
  const c = { succeeded: 0, failed: 0, refused: 0, cancelled: 0, running: 0, total: 0, finished: 0 } as OutcomeCounts;
  for (const r of rows) {
    c[buildOutcome(r)] += 1;
    c.total += 1;
  }
  c.finished = c.total - c.running;
  return c;
}

/** Share of FINISHED builds (running ones are not in the denominator). null when nothing finished. */
export function rate(c: OutcomeCounts, k: Exclude<BuildOutcome, "running">): number | null {
  return c.finished ? c[k] / c.finished : null;
}

export type GroupStats = {
  key: string;
  counts: OutcomeCounts;
  avgMs: number | null;
  p95Ms: number | null;
  costUsd: number;
};

/** Outcome counts + timing per group (game, model, "game · model"). Sorted by volume. */
export function statsBy(rows: BuildLite[], keyOf: (b: BuildLite) => string): GroupStats[] {
  const groups = new Map<string, BuildLite[]>();
  for (const r of rows) {
    const k = keyOf(r);
    (groups.get(k) ?? groups.set(k, []).get(k)!).push(r);
  }
  return [...groups.entries()]
    .map(([key, list]) => {
      const done = list.filter((b) => buildOutcome(b) !== "running" && (b.durationMs ?? 0) > 0).map((b) => b.durationMs!);
      return { key, counts: countOutcomes(list), avgMs: mean(done), p95Ms: percentile(done, 95), costUsd: list.reduce((a, b) => a + (b.costUsd || 0), 0) };
    })
    .sort((a, b) => b.counts.total - a.counts.total || a.key.localeCompare(b.key));
}

/** UTC day key "2026-10-08". */
export const dayKey = (d: Date) => d.toISOString().slice(0, 10);

/** Builds per UTC day for the last `days` days (oldest first), split by outcome. */
export function perDay(rows: { createdAt: Date; status: string; errorCode: string | null }[], days: number, now: Date) {
  const start = Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()) - (days - 1) * DAY;
  const out = Array.from({ length: days }, (_, i) => {
    const day = dayKey(new Date(start + i * DAY));
    return { day, succeeded: 0, failed: 0, refused: 0, cancelled: 0, running: 0, total: 0 };
  });
  for (const r of rows) {
    const i = Math.floor((r.createdAt.getTime() - start) / DAY);
    if (i < 0 || i >= days) continue;
    out[i][buildOutcome(r)] += 1;
    out[i].total += 1;
  }
  return out;
}

// ---------------------------------------------------------------------------
// Margin: AI cost vs tokens charged
// ---------------------------------------------------------------------------

export type SettledHold = { model: string; charged: number | null; costUsd: number | null; status: string };

export type ModelMargin = {
  model: string;
  builds: number;
  costUsd: number;
  tokensCharged: number;
  /** tokens charged per USD of measured AI cost (null when the AI cost nothing). */
  tokensPerUsd: number | null;
  /** What the charged tokens are worth at the reference price (USD per token, see below). */
  valueUsd: number;
  marginUsd: number;
  /** marginUsd / valueUsd (null when nothing was charged). */
  marginPct: number | null;
};

/**
 * Margin by model from settled token holds. `usdPerToken` is the reference price of one token,
 * normally the top-up price (1 / cyrus_tok_topup_tokens_per_usd). This is a REFERENCE margin: real
 * revenue depends on how each customer got their tokens (granted tokens with a game server or by an
 * admin earn nothing directly, plan tokens earn the plan price). The page says so next to the table.
 */
export function marginByModel(holds: SettledHold[], usdPerToken: number): ModelMargin[] {
  const by = new Map<string, { builds: number; costUsd: number; tokensCharged: number }>();
  for (const h of holds) {
    if (h.status === "held") continue;
    const m = by.get(h.model) ?? { builds: 0, costUsd: 0, tokensCharged: 0 };
    m.builds += 1;
    m.costUsd += h.costUsd ?? 0;
    m.tokensCharged += h.charged ?? 0;
    by.set(h.model, m);
  }
  const order = ["katara", "saka", "yakko"];
  return [...by.entries()]
    .map(([model, m]) => marginRow(model, m, usdPerToken))
    .sort((a, b) => (order.indexOf(a.model) + 1 || 99) - (order.indexOf(b.model) + 1 || 99) || a.model.localeCompare(b.model));
}

export function marginRow(model: string, m: { builds: number; costUsd: number; tokensCharged: number }, usdPerToken: number): ModelMargin {
  const valueUsd = m.tokensCharged * (usdPerToken > 0 ? usdPerToken : 0);
  const marginUsd = valueUsd - m.costUsd;
  return {
    model,
    builds: m.builds,
    costUsd: m.costUsd,
    tokensCharged: m.tokensCharged,
    tokensPerUsd: m.costUsd > 0 ? m.tokensCharged / m.costUsd : null,
    valueUsd,
    marginUsd,
    marginPct: valueUsd > 0 ? marginUsd / valueUsd : null,
  };
}

export function totalMargin(rows: ModelMargin[], usdPerToken: number): ModelMargin {
  return marginRow("all", rows.reduce((a, r) => ({ builds: a.builds + r.builds, costUsd: a.costUsd + r.costUsd, tokensCharged: a.tokensCharged + r.tokensCharged }), { builds: 0, costUsd: 0, tokensCharged: 0 }), usdPerToken);
}

// ---------------------------------------------------------------------------
// Builds table filter (search params -> filter -> Prisma where)
// ---------------------------------------------------------------------------

export type BuildFilter = {
  q: string;
  outcome: BuildOutcome | "";
  model: string;
  game: string;
  days: number;
  page: number;
};

export const BUILD_PAGE_SIZE = 50;
const DAY_CHOICES = [1, 7, 30, 90, 365];

/** Parse untrusted search params into a safe filter (bad values fall back to "no filter"). */
export function parseBuildFilter(sp: Record<string, string | string[] | undefined>): BuildFilter {
  const one = (k: string) => {
    const v = sp[k];
    return (Array.isArray(v) ? v[0] : v ?? "").trim();
  };
  const outcome = one("outcome");
  const model = one("model").toLowerCase();
  const game = one("game").toLowerCase();
  const days = Number(one("days"));
  const page = Math.floor(Number(one("page")));
  return {
    q: one("q").slice(0, 120),
    outcome: (BUILD_OUTCOMES as string[]).includes(outcome) ? (outcome as BuildOutcome) : "",
    model: /^[a-z0-9-]{1,20}$/.test(model) ? model : "",
    game: /^[a-z0-9-]{1,30}$/.test(game) ? game : "",
    days: DAY_CHOICES.includes(days) ? days : 30,
    page: Number.isFinite(page) && page > 0 ? Math.min(page, 1000) : 1,
  };
}

/** Prisma `where` for the DB-side part of the filter (outcome + date + id/prompt/plugin search). */
export function buildWhere(f: BuildFilter, now: Date, userIds: string[] = []) {
  const and: Record<string, unknown>[] = [{ createdAt: { gt: new Date(now.getTime() - f.days * DAY) } }];
  if (f.outcome === "succeeded") and.push({ status: "succeeded" });
  else if (f.outcome === "running") and.push({ status: { notIn: ["succeeded", "failed"] } });
  else if (f.outcome === "refused") and.push({ status: "failed", errorCode: "refused" });
  else if (f.outcome === "cancelled") and.push({ status: "failed", errorCode: { in: ["cancelled", "admin_cancelled"] } });
  else if (f.outcome === "failed") and.push({ status: "failed", OR: [{ errorCode: null }, { errorCode: { notIn: ["refused", "cancelled", "admin_cancelled"] } }] });
  if (f.model) and.push({ cyrus: { path: ["model"], equals: f.model } });
  if (f.q) {
    const or: Record<string, unknown>[] = [
      { id: f.q },
      { pluginName: { contains: f.q, mode: "insensitive" } },
      { prompt: { contains: f.q, mode: "insensitive" } },
      { changeRequest: { contains: f.q, mode: "insensitive" } },
    ];
    if (userIds.length) or.push({ userId: { in: userIds } });
    and.push({ OR: or });
  }
  return { AND: and };
}

/** The same filter applied in memory (used for the game filter, which is derived, and in tests). */
export function matchBuild(b: BuildLite & { prompt?: string; pluginName?: string | null; email?: string | null }, f: BuildFilter, now: Date): boolean {
  if (b.createdAt.getTime() <= now.getTime() - f.days * DAY) return false;
  if (f.outcome && buildOutcome(b) !== f.outcome) return false;
  if (f.model && b.model !== f.model) return false;
  if (f.game && b.game !== f.game) return false;
  if (f.q) {
    const q = f.q.toLowerCase();
    const hay = [b.id, b.pluginName ?? "", b.prompt ?? "", b.email ?? ""].join("\n").toLowerCase();
    if (!hay.includes(q)) return false;
  }
  return true;
}

/** Query string for a filter (only non-default parts), for links and pagination. */
export function filterQuery(f: BuildFilter, patch: Partial<BuildFilter> = {}): string {
  const g = { ...f, ...patch };
  const p = new URLSearchParams();
  if (g.q) p.set("q", g.q);
  if (g.outcome) p.set("outcome", g.outcome);
  if (g.model) p.set("model", g.model);
  if (g.game) p.set("game", g.game);
  if (g.days !== 30) p.set("days", String(g.days));
  if (g.page > 1) p.set("page", String(g.page));
  const s = p.toString();
  return s ? `?${s}` : "";
}

// ---------------------------------------------------------------------------
// Things that need a human
// ---------------------------------------------------------------------------

export type Attention = { level: "red" | "amber"; code: string; text: string; href?: string };

const LOST_CODES = ["unreachable", "lost", "unavailable"];

/**
 * Builds stuck in a running state, builds the portal lost contact with, holds left after a build
 * finished (a settle that never ran), and a service that is down while builds are in flight.
 */
