}

// ---------------------------------------------------------------------------
// Abuse signals (per user, derived from real rows)
// ---------------------------------------------------------------------------

export type AbuseSignal = { level: "red" | "amber"; code: string; text: string };

export function abuseSignals(i: {
  builds30d: { status: string; errorCode: string | null; costUsd: number }[];
