// Every Cyrus-related Setting in one list, with what it does and its safe default. PURE and
// client-safe; unit-tested in test/cyrus-admin.test.ts. The Audit & settings tab renders this and
// writes through lib/actions-cyrus-admin.ts (validateSettingValue below, audited before/after).
//
// `owner` says which branch reads the setting. A setting whose code is not merged yet still shows
// here (marked "not merged yet") so the owner can see the whole picture before the merges, but it
// does nothing until that code lands.
import { CYRUS_TOKEN_DEFAULTS, TOKEN_SETTING_KEYS } from "../tokens/config";
import { CYRUS_GAMES } from "../games";
import { gameStatusKey } from "../game-status";

export type SettingType = "bool" | "int" | "number" | "enum" | "emails" | "text" | "json";

export type CyrusSettingDef = {
  key: string;
  label: string;
  description: string;
  type: SettingType;
  default: string;
  options?: string[];
  min?: number;
  max?: number;
  group: "launch" | "safety" | "games" | "lifecycle" | "tokens";
  /** Branch whose code reads it ("base" = already on feature/cyrus-v6). */
  owner: "base" | "admin" | "lifecycle" | "capabilities";
  /** Edited on another screen (link) instead of inline here. */
  editAt?: string;
  /** Flipping it ON affects customers or money: the form asks for a confirm. */
  risky?: boolean;
};

const tokenRange: Record<string, [number, number]> = {
  cyrus_tok_tokens_per_usd: [1, 100000],
  cyrus_tok_mult_katara: [0.1, 20],
  cyrus_tok_mult_saka: [0.1, 20],
  cyrus_tok_mult_yakko: [0.1, 20],
  cyrus_tok_failed_charge_pct: [0, 100],
};

function tokenDef(k: (typeof TOKEN_SETTING_KEYS)[number]): CyrusSettingDef {
  const d = CYRUS_TOKEN_DEFAULTS[k];
  const bool = d === "true" || d === "false";
  const json = k === "cyrus_tok_reserve_table";
  const price = /^cyrus_tok_price_/.test(k);
  const num = !bool && !json && !price;
  const r = tokenRange[k];
  return {
    key: k,
    label: k.replace(/^cyrus_tok_/, "").replace(/_/g, " "),
    description: "Token economy number (docs: \"Cyrus token economy\"). A blank or bad value falls back to the default, never to 0.",
    type: bool ? "bool" : json ? "json" : price ? "text" : /mult_|per_usd$|pct$/.test(k) ? "number" : "int",
    default: d,
    ...(num ? { min: r?.[0] ?? 0, max: r?.[1] ?? 1_000_000 } : {}),
    group: "tokens",
    owner: "base",
    ...(json || price ? { editAt: "/admin/cyrus-tokens" } : {}),
    risky: k === "cyrus_tok_live" || k === "cyrus_tok_enforce",
  };
}

export const CYRUS_SETTINGS: CyrusSettingDef[] = [
  { key: "cyrus_mods_public_enabled", label: "Cyrus mods public launch", description: "Off: NxLabs Cyrus pages, /mods/cyrus, community, downloads and forks 404 for everyone except preview accounts. On: published pages are public and indexable.", type: "bool", default: "false", group: "launch", owner: "base", risky: true },
  { key: "preview_access_emails_modbuilder", label: "Cyrus preview accounts", description: "Comma-separated emails that may use Cyrus (and see this admin section) during the private preview. Empty = nobody. Unset = the owner's account.", type: "emails", default: "", group: "launch", owner: "base", risky: true },
  { key: "cyrus_mod_networking_enabled", label: "Mod networking (global kill switch)", description: "Allows generated mods to use the network through the vetted Nxeon wrapper and a declared host list. OFF blocks all mod networking. Read by the capabilities branch.", type: "bool", default: "false", group: "safety", owner: "capabilities", risky: true },
  { key: "cyrus_lifecycle_enabled", label: "Installed-mod health watch", description: "Worker sweep: Broken warnings from game logs, auto-disable after a crash loop right after an install, opt-in auto-updates.", type: "bool", default: "false", group: "lifecycle", owner: "lifecycle", risky: true },
  { key: "cyrus_compat_watch_enabled", label: "Creator compat watch", description: "Worker sweep that warns a mod's creator when a game/loader version change makes the mod likely stale.", type: "bool", default: "false", group: "lifecycle", owner: "lifecycle" },
  { key: "cyrus_compat_watch_dry_run", label: "Compat watch dry run", description: "On: the compat watch only records and logs what it would send. Off: creators are notified (and emailed if they allow it).", type: "bool", default: "true", group: "lifecycle", owner: "lifecycle", risky: true },
  { key: "cyrus_install_published_enabled", label: "Install other creators' mods", description: "Lets customers install other creators' PUBLISHED Cyrus mods from NxLabs onto their servers.", type: "bool", default: "false", group: "lifecycle", owner: "lifecycle", risky: true },
  ...CYRUS_GAMES.map((g): CyrusSettingDef => ({
    key: gameStatusKey(g.id),
    label: `${g.name} status`,
    description: `Overrides lib/cyrus/games.ts (file default: ${g.status}). Edit it on Games & models (only games with a real build pipeline can be live).`,
    type: "enum",
    options: ["live", "soon", "disabled"],
    default: "",
    group: "games",
    owner: "admin",
    editAt: "/admin/cyrus/games",
  })),
  { key: "cyrus_suspensions", label: "Suspended accounts", description: "JSON list of accounts suspended from building or the community. Edit it on Users & tokens.", type: "json", default: "[]", group: "safety", owner: "admin", editAt: "/admin/cyrus/users" },
  ...TOKEN_SETTING_KEYS.map(tokenDef),
];

export const cyrusSettingDef = (key: string) => CYRUS_SETTINGS.find((s) => s.key === key) ?? null;

const EMAIL_RE = /^[^\s@,;]+@[^\s@,;]+\.[^\s@,;]+$/;

/**
 * Validate an inline edit. Returns the value to store, "" to clear (back to default), or an error.
 * Settings with `editAt` (JSON, game status, Stripe price ids) are refused here: they have their own
 * screen with its own validation.
 */
export function validateSettingValue(key: string, raw: string): { ok: true; value: string } | { ok: false; error: string } {
  const def = cyrusSettingDef(key);
  if (!def) return { ok: false, error: "Not a Cyrus setting." };
  if (def.editAt) return { ok: false, error: `Edit this on ${def.editAt}.` };
  const v = raw.trim();
  if (v === "" || v === def.default) return { ok: true, value: "" };
  switch (def.type) {
    case "bool":
      return v === "true" || v === "false" ? { ok: true, value: v } : { ok: false, error: "Use true or false." };
    case "enum":
      return def.options?.includes(v) ? { ok: true, value: v } : { ok: false, error: `Use one of: ${def.options?.join(", ")}.` };
    case "int":
    case "number": {
      const n = Number(v);
      if (!Number.isFinite(n) || (def.type === "int" && !Number.isInteger(n))) return { ok: false, error: def.type === "int" ? "Use a whole number." : "Use a number." };
