// Cyrus admin: the networking review queue (mods that declare network hosts). PURE helpers.
//
// The capabilities branch (feature/cyrus-v6-capabilities) defines the real manifest
// (`nx-capabilities.yml` -> build metadata) and the helpers in lib/cyrus/capabilities.ts. Until it
// is merged, `declaredNetwork` below reads the shapes that branch's brief describes, defensively,
// from ModBuild.result / ModBuild.cyrus. It is the ONE place to point at the real helper on merge.
//
// Review decisions live in one Setting, `cyrus_net_reviews` (JSON map rootBuildId -> decision).
// The decision is enforced by the capabilities code (install/publish refuse a "blocked" mod, and
// nothing networks while the global switch `cyrus_mod_networking_enabled` is off).

export const NET_REVIEWS_KEY = "cyrus_net_reviews";
export const NET_KILL_SWITCH = "cyrus_mod_networking_enabled";

export type NetHost = { host: string; purpose: string | null; sendsPlayerData: boolean | null };
export type NetDecision = { decision: "approved" | "blocked"; by: string; at: string; note: string; hosts: string[] };

const HOST_RE = /^(?=.{1,253}$)([a-z0-9-]{1,63}\.)+[a-z]{2,63}$/i;

function hostOf(x: unknown): NetHost | null {
  if (typeof x === "string") return HOST_RE.test(x.trim()) ? { host: x.trim().toLowerCase(), purpose: null, sendsPlayerData: null } : null;
  if (!x || typeof x !== "object") return null;
  const r = x as Record<string, unknown>;
  const h = typeof r.host === "string" ? r.host.trim().toLowerCase() : "";
  if (!HOST_RE.test(h)) return null;
  const pd = r.sendsPlayerData ?? r.playerData ?? r.writesPlayerData;
  return { host: h, purpose: typeof r.purpose === "string" ? r.purpose.slice(0, 200) : null, sendsPlayerData: typeof pd === "boolean" ? pd : null };
}

/** Hosts a build declares, from whichever field holds the capability manifest. null = declares none. */
export function declaredNetwork(result: unknown, cyrus?: unknown): NetHost[] | null {
  for (const src of [result, cyrus]) {
    if (!src || typeof src !== "object") continue;
    const cap = (src as Record<string, unknown>).capabilities;
    if (!cap || typeof cap !== "object") continue;
    const c = cap as Record<string, unknown>;
    const net = c.network && typeof c.network === "object" ? (c.network as Record<string, unknown>) : c;
    const list = Array.isArray(net.hosts) ? net.hosts : Array.isArray(c.hosts) ? c.hosts : null;
    if (!list) continue;
    const hosts = list.map(hostOf).filter((h): h is NetHost => !!h);
    const uniq = [...new Map(hosts.map((h) => [h.host, h])).values()].slice(0, 50);
    if (uniq.length) return uniq;
  }
  return null;
}

export function parseNetReviews(raw: string | null | undefined): Record<string, NetDecision> {
  let v: unknown;
  try {
    v = JSON.parse(raw || "{}");
  } catch {
    return {};
  }
  if (!v || typeof v !== "object" || Array.isArray(v)) return {};
  const out: Record<string, NetDecision> = {};
  for (const [k, d] of Object.entries(v as Record<string, unknown>)) {
    if (!/^[A-Za-z0-9_-]{1,64}$/.test(k) || !d || typeof d !== "object") continue;
    const r = d as Record<string, unknown>;
    if (r.decision !== "approved" && r.decision !== "blocked") continue;
    out[k] = { decision: r.decision, by: String(r.by ?? ""), at: String(r.at ?? ""), note: String(r.note ?? "").slice(0, 300), hosts: Array.isArray(r.hosts) ? r.hosts.map(String).slice(0, 50) : [] };
  }
  return out;
}

/**
 * Review state of one mod. An approval covers exactly the hosts that were reviewed: if a new version
 * declares a host that was not approved, the mod goes back to "pending".
 */
export function reviewState(hosts: NetHost[], d: NetDecision | undefined): "pending" | "approved" | "blocked" | "changed" {
  if (!d) return "pending";
  if (d.decision === "blocked") return "blocked";
  const ok = new Set(d.hosts);
  return hosts.every((h) => ok.has(h.host)) ? "approved" : "changed";
}

