"use server";

/**
 * Cyrus admin (/admin/cyrus) writes. Every action:
 *  - is permission-checked: requireArea(<the action's area>) from lib/cyrus/admin/perms.ts (role),
 *    the real signed-in account on the "modbuilder" preview list (same gate as the pages), and never
 *    while impersonating;
 *  - is audited with before/after (lib/cyrus/admin/audit.ts -> AuditLog, category cyrus_admin);
 *  - moves tokens ONLY through the economy module (lib/cyrus/tokens/ledger.ts creditTokens /
 *    revokeTokens: idempotent, locked, append-only ledger). No direct balance edits, no money.
 *  - is reversible where possible (refund -> undo refund, suspend -> lift, takedown -> restore,
 *    setting -> back to default, game status -> file default).
 * Each form redirects back to the page it came from with ?ok= or ?err=.
 */
import { notFound, redirect } from "next/navigation";
import { randomBytes } from "node:crypto";
import type { User } from "@prisma/client";
import { db } from "./db";
import { impersonating, realUser } from "./auth";
import { requireArea } from "./rbac";
import { isPreviewUser, parsePreviewEmails } from "./preview-access";
import { CYRUS_ADMIN_ACTIONS, CYRUS_ADMIN_BASE, type CyrusAdminAction } from "./cyrus/admin/perms";
import { cyrusAudit } from "./cyrus/admin/audit";
import { cyrusSettingDef, validateSettingValue } from "./cyrus/admin/settings-catalog";
import { NET_KILL_SWITCH, NET_REVIEWS_KEY, parseNetReviews } from "./cyrus/admin/networking";
import { canSetGameStatus, gameStatusKey, isGameStatus } from "./cyrus/game-status";
import { clearCyrusGameStatusCache } from "./cyrus/game-status.server";
import { CYRUS_SUSPENSIONS_KEY, loadSuspensions, pruneSuspensions, removeSuspension, SUSPENSION_SCOPES, upsertSuspension, type SuspensionScope } from "./cyrus/suspensions";
import { creditTokens, revokeTokens, tokenSummary } from "./cyrus/tokens/ledger";
import { clearTokenConfigCache, loadTokenConfig } from "./cyrus/tokens/config";
import { svcCancel } from "./modbuilder/client";
import { syncBuild } from "./modbuilder/store";
import { safeSettle } from "./cyrus/tokens/builds";
import { isTerminal } from "./modbuilder/types";
import { createModBuild } from "./modbuilder/create";
import { readCyrusMeta } from "./cyrus/meta";

const DAY = 86_400_000;

// ── plumbing ────────────────────────────────────────────────────────────────

function backTo(fd: FormData): string {
  const b = String(fd.get("back") ?? "");
  return b.startsWith(CYRUS_ADMIN_BASE) && !b.includes("//") && b.length < 300 ? b : CYRUS_ADMIN_BASE;
}

function go(fd: FormData, kind: "ok" | "err", msg: string, path?: string): never {
  const base = path ?? backTo(fd);
  const [p, q = ""] = base.split("?");
  const params = new URLSearchParams(q);
  params.delete("ok");
  params.delete("err");
  params.set(kind, msg.slice(0, 300));
  redirect(`${p}?${params.toString()}`);
}

async function guard(action: CyrusAdminAction): Promise<User> {
  const admin = await requireArea(CYRUS_ADMIN_ACTIONS[action]);
  if (await impersonating()) redirect("/dashboard");
  if (!(await isPreviewUser(await realUser(), "modbuilder"))) notFound();
  return admin;
}

async function targetUser(raw: FormDataEntryValue | null) {
  const v = String(raw ?? "").trim();
  if (!v || v.length > 200) return null;
  return db.user.findFirst({ where: v.includes("@") ? { email: { equals: v, mode: "insensitive" } } : { id: v }, select: { id: true, email: true } });
}

const str = (fd: FormData, k: string, max = 300) => String(fd.get(k) ?? "").trim().slice(0, max);
const confirmed = (fd: FormData) => fd.get("confirm") === "1" || fd.get("confirm") === "on";

async function setOrClear(key: string, value: string | null) {
  if (value === null || value === "") await db.setting.deleteMany({ where: { key } });
  else await db.setting.upsert({ where: { key }, update: { value }, create: { key, value } });
}

async function settingValue(key: string): Promise<string | null> {
  return (await db.setting.findUnique({ where: { key } }))?.value ?? null;
}

// ── builds ──────────────────────────────────────────────────────────────────

/** Cancel a running build at the service. With `force`, a build the service cannot be reached for is failed locally. */
export async function adminCyrusCancelBuild(fd: FormData) {
  const admin = await guard("build.cancel");
  const id = str(fd, "buildId", 64);
  const row = await db.modBuild.findUnique({ where: { id } });
  if (!row) go(fd, "err", "No such build.");
  if (isTerminal(row.status)) go(fd, "err", `That build already ${row.status}.`);
  let svcOk = true;
  try {
    await svcCancel(id);
  } catch {
    svcOk = false;
  }
  let after = row;
  if (svcOk) {
    after = await syncBuild(row).catch(() => row);
  } else if (fd.get("force") === "1") {
    after = await db.modBuild.update({ where: { id }, data: { status: "failed", errorCode: "admin_cancelled", error: "This build was stopped by Nxeon support.", finishedAt: new Date() } });
    await safeSettle(after);
  } else {
    go(fd, "err", "The builder could not be reached. Tick 'force' to stop it on our side only.");
  }
  await cyrusAudit({ actorId: admin.id, action: "build.cancel", target: `build:${id}`, before: { status: row.status }, after: { status: after.status, errorCode: after.errorCode, forced: !svcOk }, note: str(fd, "note") });
  go(fd, "ok", svcOk ? `Cancel sent to the builder (now: ${after.status}).` : "Build stopped on our side (the builder was unreachable).");
}

/** Refund tokens a finished build was charged (once per build, up to what it was charged). */
export async function adminCyrusRefundBuild(fd: FormData) {
  const admin = await guard("build.refund");
  const id = str(fd, "buildId", 64);
  const res = await db.cyrusTokenReservation.findUnique({ where: { buildId: id } });
  if (!res || res.status === "held") go(fd, "err", "This build has no settled token charge to refund.");
  const charged = res.charged ?? 0;
  const amount = Math.floor(Number(fd.get("amount") || charged));
  if (!(amount > 0 && amount <= charged)) go(fd, "err", `Refund 1 to ${charged} tokens (what this build was charged).`);
  const note = str(fd, "note", 200);
  const cfg = await loadTokenConfig();
  const before = await tokenSummary(res.userId);
  const r = await creditTokens({
    userId: res.userId, amount, kind: "refund", source: "refund", sourceRef: id,
    idemKey: `admin-refund:${id}`,
    expiresAt: new Date(Date.now() + cfg.adminGrantExpiryDays * DAY),
    note: `Refund for a build${note ? `: ${note}` : ""}`.slice(0, 200),
    meta: { buildId: id, charged, by: admin.id },
    actorId: admin.id,
  });
  if (!r.created) go(fd, "err", "This build was already refunded (one refund per build; undo it first to change the amount).");
  const after = await tokenSummary(res.userId);
  await cyrusAudit({ actorId: admin.id, action: "build.refund", target: `build:${id}`, before: { balance: before.balance, charged }, after: { balance: after.balance, refunded: r.amount, lotId: r.lotId }, note });
  go(fd, "ok", `Refunded ${r.amount} tokens.`);
}

/** Undo a refund: takes back what is still unspent of the refund's own lot (never below zero). */
export async function adminCyrusUndoRefund(fd: FormData) {
  const admin = await guard("build.refund.undo");
  const id = str(fd, "buildId", 64);
  const row = await db.cyrusTokenLedger.findUnique({ where: { idemKey: `admin-refund:${id}` } });
  if (!row?.lotId) go(fd, "err", "No refund to undo for this build.");
  const lot = await db.cyrusTokenLot.findUnique({ where: { id: row.lotId } });
  const before = await tokenSummary(row.userId);
  const r = await revokeTokens({ userId: row.userId, amount: lot?.remaining ?? 0, lotIds: [row.lotId], idemKey: `admin-refund-undo:${id}:${randomBytes(4).toString("hex")}`, note: "Refund reversed by Nxeon", actorId: admin.id, sourceRef: id });
  const after = await tokenSummary(row.userId);
  await cyrusAudit({ actorId: admin.id, action: "build.refund.undo", target: `build:${id}`, before: { balance: before.balance, refunded: row.delta }, after: { balance: after.balance, revoked: r.revoked } });
  go(fd, "ok", r.revoked ? `Took back ${r.revoked} of the ${row.delta} refunded tokens${r.revoked < row.delta ? " (the rest were already spent)" : ""}.` : "Nothing left to take back (already spent or held by a running build).");
}

/** Start the same request again for the customer (a real build: AI cost + the customer's tokens are held as usual). */
export async function adminCyrusRerunBuild(fd: FormData) {
  const admin = await guard("build.rerun");
  if (!confirmed(fd)) go(fd, "err", "Tick the box to confirm a real re-run.");
  const id = str(fd, "buildId", 64);
  const row = await db.modBuild.findUnique({ where: { id } });
  if (!row) go(fd, "err", "No such build.");
  if (!isTerminal(row.status)) go(fd, "err", "That build is still running.");
  const user = await db.user.findUnique({ where: { id: row.userId } });
  if (!user) go(fd, "err", "The build's account no longer exists.");
  const model = readCyrusMeta(row.cyrus).model;
  const body: Record<string, unknown> = row.baseBuildId && row.changeRequest
    ? { baseBuildId: row.baseBuildId, changeRequest: row.changeRequest, ...(model ? { model } : {}) }
    : { prompt: row.prompt, mcVersion: row.mcVersion, ...(model ? { model } : {}) };
  const r = await createModBuild(user, body);
  if (!r.ok) {
    await cyrusAudit({ actorId: admin.id, action: "build.rerun", target: `build:${id}`, before: { status: row.status }, after: { refused: r.status, error: String(r.json.error ?? "") } });
    go(fd, "err", `Re-run refused: ${String(r.json.error ?? r.status)}`);
  }
  await cyrusAudit({ actorId: admin.id, action: "build.rerun", target: `build:${id}`, before: { status: row.status }, after: { newBuildId: r.build.id, status: r.build.status, reservedTokens: r.reserved }, note: str(fd, "note") });
  go(fd, "ok", `Re-run started as ${r.build.id}.`, `${CYRUS_ADMIN_BASE}/builds/${r.build.id}`);
}

// ── users and tokens ────────────────────────────────────────────────────────

export async function adminCyrusGrant(fd: FormData) {
  const admin = await guard("tokens.grant");
  const u = await targetUser(fd.get("user"));
  if (!u) go(fd, "err", "No such account.");
  const amount = Math.floor(Number(fd.get("amount")));
  if (!(amount > 0 && amount <= 1_000_000)) go(fd, "err", "Amount must be 1 to 1,000,000.");
  const cfg = await loadTokenConfig();
  const days = Math.min(3650, Math.max(1, Math.floor(Number(fd.get("days"))) || cfg.adminGrantExpiryDays));
  const note = str(fd, "note", 200);
  const before = await tokenSummary(u.id);
  const r = await creditTokens({
    userId: u.id, amount, kind: "grant", source: "admin", sourceRef: admin.id,
    idemKey: `admin:${str(fd, "token", 40) || randomBytes(8).toString("hex")}`,
    expiresAt: new Date(Date.now() + days * DAY), note: note || "Admin grant", actorId: admin.id,
  });
  const after = await tokenSummary(u.id);
  await cyrusAudit({ actorId: admin.id, action: "tokens.grant", target: `user:${u.id}`, before: { balance: before.balance }, after: { balance: after.balance, granted: r.amount, expiresInDays: days, duplicate: !r.created }, note });
  go(fd, "ok", r.created ? `Granted ${r.amount} tokens to ${u.email}.` : "Already applied (double submit).");
}

export async function adminCyrusRevoke(fd: FormData) {
  const admin = await guard("tokens.revoke");
  const u = await targetUser(fd.get("user"));
  if (!u) go(fd, "err", "No such account.");
  const amount = Math.floor(Number(fd.get("amount")));
  if (!(amount > 0)) go(fd, "err", "Amount must be positive.");
  const note = str(fd, "note", 200);
  const before = await tokenSummary(u.id);
  const r = await revokeTokens({ userId: u.id, amount, idemKey: `admin-revoke:${str(fd, "token", 40) || randomBytes(8).toString("hex")}`, note: note || "Admin revoke", actorId: admin.id });
  const after = await tokenSummary(u.id);
  await cyrusAudit({ actorId: admin.id, action: "tokens.revoke", target: `user:${u.id}`, before: { balance: before.balance }, after: { balance: after.balance, revoked: r.revoked }, note });
  go(fd, "ok", `Removed ${r.revoked} tokens (never below zero, never a running build's hold).`);
}

/** Comp a model tier (unlocks models; adds no tokens). Blank tier removes the comp. */
export async function adminCyrusComp(fd: FormData) {
  const admin = await guard("tokens.comp");
  const u = await targetUser(fd.get("user"));
  if (!u) go(fd, "err", "No such account.");
  const tier = str(fd, "tier", 10);
  const t = tier === "katara" || tier === "saka" || tier === "all" ? tier : null;
  const days = Math.floor(Number(fd.get("days")));
  const until = t && days > 0 ? new Date(Date.now() + Math.min(3650, days) * DAY) : null;
  const prev = await db.cyrusTokenAccount.findUnique({ where: { userId: u.id }, select: { tierOverride: true, tierOverrideUntil: true } });
  await db.cyrusTokenAccount.upsert({ where: { userId: u.id }, create: { userId: u.id, tierOverride: t, tierOverrideUntil: until }, update: { tierOverride: t, tierOverrideUntil: until } });
  await cyrusAudit({ actorId: admin.id, action: "tokens.comp", target: `user:${u.id}`, before: { tier: prev?.tierOverride ?? null, until: prev?.tierOverrideUntil?.toISOString() ?? null }, after: { tier: t, until: until?.toISOString() ?? null }, note: str(fd, "note") });
  go(fd, "ok", t ? `${u.email} now has ${t === "all" ? "all models" : t}${until ? ` until ${until.toISOString().slice(0, 10)}` : ""}.` : `Comp removed for ${u.email}.`);
}

export async function adminCyrusSuspend(fd: FormData) {
  const admin = await guard("user.suspend");
  const u = await targetUser(fd.get("user"));
  if (!u) go(fd, "err", "No such account.");
  if (u.id === admin.id) go(fd, "err", "You can't suspend yourself.");
  const scopes = SUSPENSION_SCOPES.filter((s) => fd.get(`scope_${s}`) === "1" || fd.get(`scope_${s}`) === "on") as SuspensionScope[];
  if (!scopes.length) go(fd, "err", "Pick what to suspend (building, community or both).");
  const reason = str(fd, "reason", 300);
  if (reason.length < 3) go(fd, "err", "Give a short reason (it is kept in the audit log).");
  const days = Math.floor(Number(fd.get("days")));
  const now = new Date();
  const list = pruneSuspensions(await loadSuspensions(), now);
  const before = list.find((s) => s.userId === u.id) ?? null;
  const entry = { userId: u.id, scopes, reason, by: admin.id, at: now.toISOString(), until: days > 0 ? new Date(now.getTime() + Math.min(3650, days) * DAY).toISOString() : null };
  await setOrClear(CYRUS_SUSPENSIONS_KEY, JSON.stringify(upsertSuspension(list, entry)));
  await cyrusAudit({ actorId: admin.id, action: "user.suspend", target: `user:${u.id}`, before, after: entry, note: reason });
  go(fd, "ok", `${u.email} suspended from ${scopes.join(" + ")}${entry.until ? ` until ${entry.until.slice(0, 10)}` : ""}.`);
}

export async function adminCyrusUnsuspend(fd: FormData) {
  const admin = await guard("user.unsuspend");
  const userId = str(fd, "userId", 64);
  const list = await loadSuspensions();
  const before = list.find((s) => s.userId === userId) ?? null;
  if (!before) go(fd, "err", "That account is not suspended.");
  const next = removeSuspension(list, userId);
  await setOrClear(CYRUS_SUSPENSIONS_KEY, next.length ? JSON.stringify(next) : null);
  await cyrusAudit({ actorId: admin.id, action: "user.unsuspend", target: `user:${userId}`, before, after: null, note: str(fd, "note") });
  go(fd, "ok", "Suspension lifted.");
}

// ── community moderation ────────────────────────────────────────────────────

/** Resolve a post's open reports: hide the post, or dismiss them (post visible, report count reset). */
export async function adminCyrusResolveReports(fd: FormData) {
  const hide = fd.get("hide") === "1";
  const admin = await guard(hide ? "report.hide" : "report.dismiss");
  const postId = str(fd, "postId", 40);
  const post = await db.cyrusModPost.findUnique({ where: { id: postId } });
  if (!post) go(fd, "err", "That post no longer exists.");
  const open = await db.cyrusModReport.count({ where: { postId, resolvedAt: null } });
  await db.cyrusModReport.updateMany({ where: { postId, resolvedAt: null }, data: { resolvedAt: new Date() } });
  const reason = str(fd, "reason", 200) || "Hidden by Nxeon after review";
  await db.cyrusModPost.update({ where: { id: postId }, data: hide ? { hiddenAt: post.hiddenAt ?? new Date(), hiddenById: admin.id, hiddenReason: reason } : { hiddenAt: null, hiddenById: null, hiddenReason: null, reportCount: 0 } });
  await cyrusAudit({ actorId: admin.id, action: hide ? "report.hide" : "report.dismiss", target: `post:${postId}`, before: { hidden: !!post.hiddenAt, hiddenReason: post.hiddenReason, openReports: open, reportCount: post.reportCount }, after: { hidden: hide, hiddenReason: hide ? reason : null, openReports: 0 } });
  go(fd, "ok", hide ? "Post hidden; reports closed." : "Reports dismissed; post visible.");
}

export async function adminCyrusUnhidePost(fd: FormData) {
  const admin = await guard("post.unhide");
  const postId = str(fd, "postId", 40);
  const post = await db.cyrusModPost.findUnique({ where: { id: postId } });
  if (!post?.hiddenAt) go(fd, "err", "That post is not hidden.");
  await db.cyrusModPost.update({ where: { id: postId }, data: { hiddenAt: null, hiddenById: null, hiddenReason: null } });
  await cyrusAudit({ actorId: admin.id, action: "post.unhide", target: `post:${postId}`, before: { hidden: true, hiddenReason: post.hiddenReason, hiddenById: post.hiddenById }, after: { hidden: false } });
  go(fd, "ok", "Post visible again.");
}

/** Take a mod page down (hidden from everyone but its creator and staff) or restore it. */
export async function adminCyrusPageTakedown(fd: FormData) {
  const down = fd.get("down") === "1";
  const admin = await guard(down ? "page.takedown" : "page.restore");
  const pageId = str(fd, "pageId", 40);
  const page = await db.cyrusModPage.findUnique({ where: { id: pageId } });
  if (!page) go(fd, "err", "No such mod page.");
  const reason = str(fd, "reason", 200);
  if (down && reason.length < 3) go(fd, "err", "Give a short reason (the creator sees it).");
  await db.cyrusModPage.update({ where: { id: pageId }, data: down ? { hiddenAt: new Date(), hiddenReason: reason } : { hiddenAt: null, hiddenReason: null } });
  await cyrusAudit({ actorId: admin.id, action: down ? "page.takedown" : "page.restore", target: `page:${page.slug}`, before: { hidden: !!page.hiddenAt, reason: page.hiddenReason }, after: { hidden: down, reason: down ? reason : null } });
  go(fd, "ok", down ? `“${page.title}” taken down.` : `“${page.title}” restored.`);
}

// ── networking review ───────────────────────────────────────────────────────

export async function adminCyrusNetReview(fd: FormData) {
  const admin = await guard("network.review");
  const root = str(fd, "rootBuildId", 64);
  if (!/^[A-Za-z0-9_-]{1,64}$/.test(root)) go(fd, "err", "Bad mod id.");
  const decision = str(fd, "decision", 10);
  const hosts = str(fd, "hosts", 3000).split(",").map((h) => h.trim().toLowerCase()).filter(Boolean).slice(0, 50);
  const all = parseNetReviews(await settingValue(NET_REVIEWS_KEY));
  const before = all[root] ?? null;
  if (decision === "clear") delete all[root];
  else if (decision === "approved" || decision === "blocked") all[root] = { decision, by: admin.id, at: new Date().toISOString(), note: str(fd, "note", 300), hosts };
  else go(fd, "err", "Pick approve, block or clear.");
  await setOrClear(NET_REVIEWS_KEY, Object.keys(all).length ? JSON.stringify(all) : null);
  await cyrusAudit({ actorId: admin.id, action: "network.review", target: `mod:${root}`, before, after: all[root] ?? null });
  go(fd, "ok", decision === "clear" ? "Review cleared (back to pending)." : `Networking ${decision} for this mod.`);
}

export async function adminCyrusNetKillSwitch(fd: FormData) {
  const admin = await guard("network.killswitch");
  const on = fd.get("on") === "1";
  if (on && !confirmed(fd)) go(fd, "err", "Tick the box to confirm turning mod networking on.");
  const before = await settingValue(NET_KILL_SWITCH);
  await setOrClear(NET_KILL_SWITCH, on ? "true" : null);
  await cyrusAudit({ actorId: admin.id, action: "network.killswitch", target: `setting:${NET_KILL_SWITCH}`, before: before ?? "(default false)", after: on ? "true" : "(default false)" });
  go(fd, "ok", on ? "Mod networking switched ON." : "Mod networking switched OFF (kill switch).");
}

// ── games and settings ──────────────────────────────────────────────────────

export async function adminCyrusSetGameStatus(fd: FormData) {
  const admin = await guard("game.status");
  const gameId = str(fd, "gameId", 20);
  const raw = str(fd, "status", 10);
  const next = raw === "default" ? "default" : isGameStatus(raw) ? raw : null;
  if (!next) go(fd, "err", "Pick live, soon, disabled or the file default.");
  const ok = canSetGameStatus(gameId, next);
  if (!ok.ok) go(fd, "err", ok.error);
  const key = gameStatusKey(gameId);
  const before = await settingValue(key);
  await setOrClear(key, next === "default" ? null : next);
  clearCyrusGameStatusCache();
  await cyrusAudit({ actorId: admin.id, action: "game.status", target: `game:${gameId}`, before: before ?? "(file default)", after: next === "default" ? "(file default)" : next, note: str(fd, "note") });
  go(fd, "ok", `${gameId}: ${next === "default" ? "back to the file default" : next}.`);
}

export async function adminCyrusSetSetting(fd: FormData) {
  const admin = await guard("setting.set");
  const key = str(fd, "key", 80);
  const def = cyrusSettingDef(key);
  if (!def) go(fd, "err", "Not a Cyrus setting.");
  const v = validateSettingValue(key, String(fd.get("value") ?? ""));
  if (!v.ok) go(fd, "err", `${key}: ${v.error}`);
  const before = await settingValue(key);
  if ((before ?? "") === v.value) go(fd, "ok", "No change.");
  // Turning a risky switch ON (or changing a risky value) needs the confirm box.
  if (def.risky && v.value !== "" && v.value !== "false" && !confirmed(fd)) go(fd, "err", `Tick the box to confirm changing ${key}.`);
  if (key === "preview_access_emails_modbuilder" && v.value && !parsePreviewEmails(v.value).includes((admin.email ?? "").toLowerCase())) {
    go(fd, "err", "Keep your own email in the preview list, or you lock yourself out of this page.");
  }
  await setOrClear(key, v.value || null);
  if (key.startsWith("cyrus_tok_")) clearTokenConfigCache();
  await cyrusAudit({ actorId: admin.id, action: "setting.set", target: `setting:${key}`, before: before ?? `(default ${def.default || "unset"})`, after: v.value || `(default ${def.default || "unset"})`, note: str(fd, "note") });
  go(fd, "ok", `${key} saved.`);
}

