// Small server-safe building blocks for /admin/cyrus. Uses only the admin portal's shared classes
// (card, btn-*, input, Badge), so dark and light both come from app/admin/admin-shell.css.
import Link from "next/link";
import { Badge } from "@/components/ui/primitives";

export const n = (x: number | null | undefined) => (x === null || x === undefined || !Number.isFinite(x) ? "–" : Math.round(x).toLocaleString("en-US"));
export const usd = (x: number | null | undefined, d = 2) => (x === null || x === undefined || !Number.isFinite(x) ? "–" : `${x < 0 ? "-" : ""}$${Math.abs(x).toFixed(d)}`);
export const pct = (x: number | null | undefined) => (x === null || x === undefined || !Number.isFinite(x) ? "–" : `${Math.round(x * 100)}%`);
export const secs = (ms: number | null | undefined) => (!ms ? "–" : ms < 60_000 ? `${Math.round(ms / 1000)}s` : `${(ms / 60_000).toFixed(1)}m`);
export const when = (d: Date | string | null | undefined) => (d ? new Date(d).toISOString().replace("T", " ").slice(0, 16) + " UTC" : "–");

export function Flash({ sp }: { sp: Record<string, string | string[] | undefined> }) {
  const ok = typeof sp.ok === "string" ? sp.ok : null;
  const err = typeof sp.err === "string" ? sp.err : null;
  if (!ok && !err) return null;
  return (
    <p role="status" className={`mb-4 rounded-lg border px-3 py-2 text-sm ${err ? "border-red-500/30 bg-red-500/10 text-red-300" : "border-emerald-500/30 bg-emerald-500/10 text-emerald-300"}`}>
      {err ?? ok}
    </p>
  );
}

export function Section({ title, sub, children, right, id }: { title: string; sub?: React.ReactNode; children: React.ReactNode; right?: React.ReactNode; id?: string }) {
  return (
    <section id={id} className="card mb-6 min-w-0">
      <div className="mb-3 flex flex-wrap items-start justify-between gap-2">
        <div className="min-w-0">
          <h2 className="text-sm font-semibold">{title}</h2>
          {sub ? <p className="mt-0.5 text-xs text-slate-400">{sub}</p> : null}
        </div>
        {right}
      </div>
      {children}
    </section>
  );
}

/** Honest empty state: says WHY there is nothing (no data yet, or which merge it waits for). */
export function Empty({ children, waitsFor }: { children: React.ReactNode; waitsFor?: string }) {
  return (
    <div className="rounded-lg border border-dashed border-white/10 px-4 py-6 text-center text-sm text-slate-400" data-empty>
      <p>{children}</p>
      {waitsFor ? <p className="mt-1 text-xs text-slate-500">Arrives with the <span className="font-mono">{waitsFor}</span> merge.</p> : null}
    </div>
  );
}

export function TableWrap({ children }: { children: React.ReactNode }) {
  return <div className="-mx-1 overflow-x-auto px-1">{children}</div>;
}

export const thCls = "text-left text-xs font-medium text-slate-500 [&>th]:px-2 [&>th]:py-1.5 [&>th]:whitespace-nowrap";
export const tdRow = "border-t border-white/[0.06] align-top [&>td]:px-2 [&>td]:py-1.5";

export function Hidden({ name, value }: { name: string; value: string }) {
  return <input type="hidden" name={name} value={value} />;
}

export function Confirm({ label }: { label: string }) {
  return (
    <label className="flex items-start gap-2 text-xs text-slate-400">
      <input type="checkbox" name="confirm" value="1" className="mt-0.5" required />
      <span>{label}</span>
    </label>
  );
}

export function OutcomeBadge({ outcome }: { outcome: string }) {
  const tone = outcome === "succeeded" ? "green" : outcome === "refused" ? "amber" : outcome === "failed" ? "red" : outcome === "cancelled" ? "slate" : "brand";
  return <Badge tone={tone}>{outcome}</Badge>;
}

export function Kv({ rows }: { rows: [string, React.ReactNode][] }) {
  return (
    <dl className="grid grid-cols-[minmax(0,10rem)_minmax(0,1fr)] gap-x-3 gap-y-1.5 text-sm">
      {rows.map(([k, v]) => (
        <div key={k} className="contents">
          <dt className="text-xs text-slate-500">{k}</dt>
          <dd className="min-w-0 break-words">{v}</dd>
        </div>
      ))}
    </dl>
  );
}

export function UserLink({ id, email }: { id: string; email?: string | null }) {
  return <Link className="underline decoration-white/20 underline-offset-2 hover:decoration-current" href={`/admin/cyrus/users?u=${encodeURIComponent(id)}`}>{email ?? id}</Link>;
}

/** Stacked bars per day (succeeded / failed / refused / cancelled / running). Pure SVG, scales to its box. */
export function DayBars({ days }: { days: { day: string; succeeded: number; failed: number; refused: number; cancelled: number; running: number; total: number }[] }) {
  const max = Math.max(1, ...days.map((d) => d.total));
  const W = 720;
  const H = 160;
  const bw = W / days.length;
  const parts: [keyof (typeof days)[number], string][] = [["succeeded", "var(--adm-green, #3fd89a)"], ["failed", "var(--adm-red, #f0607a)"], ["refused", "var(--adm-amber, #f2b64b)"], ["cancelled", "var(--adm-faint, #5f6a8c)"], ["running", "var(--adm-blue, #3b6be8)"]];
  const total = days.reduce((a, d) => a + d.total, 0);
  return (
    <div>
      <svg viewBox={`0 0 ${W} ${H + 18}`} className="h-auto w-full" role="img" aria-label={`Builds per day, ${total} in ${days.length} days`}>
        <line x1="0" x2={W} y1={H} y2={H} stroke="currentColor" strokeOpacity="0.15" />
        {days.map((d, i) => {
          let y = H;
          return (
            <g key={d.day}>
              <title>{`${d.day}: ${d.total} builds (${d.succeeded} ok, ${d.failed} failed, ${d.refused} refused, ${d.cancelled} cancelled, ${d.running} running)`}</title>
              {parts.map(([k, color]) => {
                const v = d[k] as number;
                if (!v) return null;
                const h = (v / max) * (H - 6);
                y -= h;
                return <rect key={String(k)} x={i * bw + bw * 0.15} y={y} width={bw * 0.7} height={h} rx="2" fill={color} />;
              })}
              {(i === 0 || i === days.length - 1 || i % 7 === 0) && (
                <text x={i * bw + bw / 2} y={H + 14} textAnchor={i === 0 ? "start" : i === days.length - 1 ? "end" : "middle"} fontSize="11" fill="currentColor" fillOpacity="0.5">{d.day.slice(5)}</text>
              )}
            </g>
          );
        })}
      </svg>
      <div className="mt-1 flex flex-wrap gap-3 text-xs text-slate-400">
        {parts.map(([k, c]) => (
          <span key={String(k)} className="inline-flex items-center gap-1"><span className="inline-block h-2 w-2 rounded-sm" style={{ background: c }} />{String(k)}</span>
        ))}
      </div>
    </div>
  );
}

