      <Flash sp={sp} />
      <div className="mb-6 grid grid-cols-2 gap-3 lg:grid-cols-4">
        <StatCard label="Builds, 30 days" value={n(counts.total)} delta={`${n(counts.succeeded)} ok · ${n(counts.failed)} failed · ${n(counts.refused)} refused`} deltaGood={counts.failed <= counts.succeeded} />
        <StatCard label="Success rate (finished)" value={pct(rate(counts, "succeeded"))} delta={counts.finished ? `${pct(rate(counts, "refused"))} refused by safety` : "nothing finished yet"} />
        <StatCard label="Build time avg / p95" value={`${secs(mean(finishedMs))} / ${secs(percentile(finishedMs, 95))}`} delta={`${finishedMs.length} timed builds`} />
        <StatCard label="Queue now" value={svc.reachable ? `${n(svc.running)} running · ${n(svc.queued)} queued` : `${running.length} in flight`} delta={svc.reachable ? `service capacity ${n(svc.concurrency)} at once` : "service not answering"} deltaGood={svc.reachable} />
      </div>

      <Section title="Needs attention" sub="Computed from live rows: stuck builds, lost contact with the builder, holds left after a build finished, the service, open reports.">
        {attention.length === 0 ? <Empty>Nothing needs attention right now.</Empty> : (
          <ul className="space-y-2">
            {attention.map((a) => (
              <li key={a.code} className="flex flex-wrap items-start gap-2 text-sm">
                <Badge tone={a.level === "red" ? "red" : "amber"}>{a.level === "red" ? "urgent" : "check"}</Badge>
                <span className="min-w-0 flex-1">{a.text}</span>
                {a.href ? <Link href={a.href} className="btn-secondary text-xs">Open</Link> : null}
              </li>
            ))}
          </ul>
        )}
      </Section>

      <Section title="Builds per day" sub="Last 30 days, UTC, by outcome. Refused = stopped by the safety check; cancelled = stopped by the customer or Nxeon.">
        {counts.total === 0 ? <Empty>No builds in the last 30 days.</Empty> : <DayBars days={perDay(lite, 30, now)} />}
      </Section>

      <div className="grid min-w-0 gap-0 xl:grid-cols-2 xl:gap-6">
        <Section title="By game" sub="Rates are over finished builds. Only Minecraft has a real build pipeline today.">
          <StatsTable rows={statsBy(lite, (b) => b.game)} label="Game" />
        </Section>
        <Section title="By model" sub="The Cyrus model the build ran on; “auto” = older builds where the service picked the model.">
          <StatsTable rows={statsBy(lite, (b) => b.model ?? "auto")} label="Model" />
        </Section>
      </div>

      <Section
        title="AI cost vs tokens charged (margin by model)"
        sub={<>Settled token holds in the last 30 days ({n(settled.length)}). Value of tokens = tokens charged × a reference price: the top-up price (${(topupRate).toFixed(4)}/token) and, as the worst case, the cheapest plan price (${planRate.toFixed(4)}/token). Real revenue depends on how each customer got their tokens: game-server and admin grants earn nothing directly. AI cost of all builds in the window: {usd(cost30, 2)}.</>}
      >
        {settled.length === 0 ? <Empty>No settled token holds in the last 30 days (builds outside the token economy are not charged).</Empty> : (
          <div className="space-y-4">
            <div><p className="mb-1 text-xs font-medium text-slate-400">At the top-up price</p><MarginTable rows={mTop} total={totalMargin(mTop, topupRate)} /></div>
            <div><p className="mb-1 text-xs font-medium text-slate-400">At the cheapest plan price (worst case)</p><MarginTable rows={mPlan} total={totalMargin(mPlan, planRate)} /></div>
          </div>
        )}
      </Section>

      <Section title="Build service" sub="Live GET /health (no secrets are shown). Change the service on the build VM only; nothing here writes to it." right={svc.reachable ? <Badge tone="green">online</Badge> : <Badge tone="red">unreachable</Badge>}>
        {!svc.reachable ? <Empty>The build service did not answer /health (not configured on this host, the tunnel is down, or the VM is offline).</Empty> : (
          <div className="grid gap-x-6 gap-y-1 text-sm sm:grid-cols-2">
            <p><span className="text-slate-500">Image</span> {svc.image ?? "–"}</p>
            <p><span className="text-slate-500">Prompt version</span> {svc.promptVersion ?? "–"}</p>
            <p><span className="text-slate-500">Knowledge</span> {svc.knowledge ?? "–"}</p>
            <p><span className="text-slate-500">AI auth mode</span> {svc.auth ?? "–"}</p>
            <p className="sm:col-span-2"><span className="text-slate-500">Versions</span> {svc.versions.join(", ") || "–"}</p>
            <p className="sm:col-span-2 text-xs text-slate-500">Full knob list: <Link className="underline" href="/admin/cyrus/games#service">Games &amp; models</Link>.</p>
          </div>
        )}
      </Section>
    </div>
  );
}

