import type { Metadata } from "next";
import Link from "next/link";
import { notFound } from "next/navigation";
import { db } from "@/lib/db";
import { realUser } from "@/lib/auth";
import { svcGet } from "@/lib/modbuilder/client";
import { isTerminal, type ModBuildResult } from "@/lib/modbuilder/types";
import { CYRUS_STAGES } from "@/lib/cyrus/models";
import { readCyrusMeta } from "@/lib/cyrus/meta";
import { requireCyrusAdmin, cyrusAdminMetadata } from "@/lib/cyrus/admin/gate";
import { canCyrusAdmin } from "@/lib/cyrus/admin/perms";
import { gameOfBuild, modelOfBuild } from "@/lib/cyrus/admin/data";
import { buildOutcome } from "@/lib/cyrus/admin/metrics";
import { shortModel } from "@/lib/cyrus/admin/service";
import { adminCyrusCancelBuild, adminCyrusRefundBuild, adminCyrusRerunBuild, adminCyrusUndoRefund } from "@/lib/actions-cyrus-admin";
import { Badge } from "@/components/ui/primitives";
import { Confirm, Empty, Flash, Hidden, Kv, OutcomeBadge, Section, TableWrap, UserLink, n, secs, tdRow, thCls, usd, when } from "@/components/admin/cyrus/ui";

export const dynamic = "force-dynamic";
export async function generateMetadata(): Promise<Metadata> {
  return cyrusAdminMetadata("Build");
}

type StageUsage = { n?: number; ms?: number; costUsd?: number; turns?: number; input?: number; cacheWrite?: number; cacheRead?: number; output?: number };

/** Usage per stage (service 0.5+). Read live from the service; older images and an offline service return null. */
async function serviceUsage(id: string): Promise<{ stages: [string, StageUsage][]; autofix: number; savedRepairs: number } | null> {
  try {
    const s = (await svcGet(id)) as unknown as { usage?: { stages?: Record<string, StageUsage>; autofix?: number; savedRepairs?: number } } | null;
    const u = s?.usage;
    if (!u?.stages || typeof u.stages !== "object") return null;
    return { stages: Object.entries(u.stages), autofix: Number(u.autofix) || 0, savedRepairs: Number(u.savedRepairs) || 0 };
  } catch {
    return null;
  }
}

export default async function CyrusAdminBuild({ params, searchParams }: { params: Promise<{ id: string }>; searchParams: Promise<Record<string, string | string[] | undefined>> }) {
  await requireCyrusAdmin("builds");
  const me = (await realUser())!;
  const { id } = await params;
  const sp = await searchParams;
  if (!/^[A-Za-z0-9_-]{1,64}$/.test(id)) notFound();
  const row = await db.modBuild.findUnique({ where: { id } });
  if (!row) notFound();
