            <TableWrap>
              <table className="w-full text-xs">
                <thead><tr className={thCls}><th>Kind</th><th>Model</th><th className="text-right">Turns</th><th className="text-right">Time</th><th className="text-right">Cost</th></tr></thead>
                <tbody>{res.ai.calls.map((c, i) => <tr key={i} className={tdRow}><td>{c.kind}</td><td>{shortModel(c.resolvedModel || c.model)}</td><td className="text-right">{c.turns ?? "–"}</td><td className="text-right">{secs(c.durationMs)}</td><td className="text-right">{usd(c.costUsd, 4)}</td></tr>)}</tbody>
              </table>
            </TableWrap>
          )}
          {res?.ai?.route ? <p className="mt-2 text-xs text-slate-500">Route: {res.ai.route}{res.ai.routeMethod ? ` (${res.ai.routeMethod}${res.ai.routeScore != null ? `, score ${res.ai.routeScore}` : ""})` : ""}</p> : null}
        </Section>
        <Section title="Usage per stage" sub="Service 0.5+ only, read live from the builder.">
          {!usage ? <Empty waitsFor="feature/cyrus-v6-efficiency (service 0.5 deploy)">The builder did not report per-stage usage for this build (older service image, or the builder is unreachable).</Empty> : (
            <TableWrap>
              <table className="w-full text-xs">
                <thead><tr className={thCls}><th>Stage</th><th className="text-right">Runs</th><th className="text-right">Time</th><th className="text-right">Cost</th><th className="text-right">Out tok</th><th className="text-right">Cache write</th><th className="text-right">Cache read</th></tr></thead>
                <tbody>{usage.stages.map(([k, s]) => <tr key={k} className={tdRow}><td>{k}</td><td className="text-right">{n(s.n)}</td><td className="text-right">{secs(s.ms)}</td><td className="text-right">{s.costUsd != null ? usd(s.costUsd, 4) : "–"}</td><td className="text-right">{n(s.output)}</td><td className="text-right">{n(s.cacheWrite)}</td><td className="text-right">{n(s.cacheRead)}</td></tr>)}</tbody>
              </table>
              <p className="mt-2 text-xs text-slate-500">{usage.autofix} automatic fix(es), {usage.savedRepairs} model repair(s) avoided.</p>
            </TableWrap>
          )}
        </Section>
      </div>

      <div className="grid min-w-0 xl:grid-cols-2 xl:gap-6">
        <Section title="Safety findings">
          {!res?.safety ? <Empty>No safety scan result.</Empty> : res.safety.findings.length === 0 ? <p className="text-sm">Verdict <Badge tone="green">{res.safety.verdict}</Badge>, no findings.</p> : (
            <ul className="space-y-2 text-sm">
              <li>Verdict <Badge tone={res.safety.verdict === "block" ? "red" : res.safety.verdict === "warn" ? "amber" : "green"}>{res.safety.verdict}</Badge></li>
              {res.safety.findings.map((f, i) => <li key={i} className="break-words"><Badge tone={f.severity === "block" ? "red" : "amber"}>{f.severity}</Badge> <span className="font-mono text-xs">{f.rule}</span> {f.message} <span className="text-xs text-slate-500">{f.where}</span></li>)}
            </ul>
          )}
        </Section>
        <Section title="Files" sub="Source files in the build (sizes from the service).">
          {!res?.files?.length ? <Empty>No files recorded.</Empty> : (
            <ul className="space-y-1 font-mono text-xs">{res.files.map((f) => <li key={f.path} className="flex justify-between gap-3"><span className="min-w-0 break-all">{f.path}</span><span className="shrink-0 text-slate-500">{n(f.size)} B</span></li>)}</ul>
          )}
        </Section>
      </div>

      <Section title="Versions of this mod" sub="Every build in this project's chain.">
        <TableWrap>
          <table className="w-full text-sm">
            <thead><tr className={thCls}><th>Build</th><th>When</th><th>Version</th><th>Status</th><th>Change</th></tr></thead>
            <tbody>{chain.map((b) => <tr key={b.id} className={`${tdRow} ${b.id === id ? "font-semibold" : ""}`}><td><Link className="font-mono text-xs underline" href={`/admin/cyrus/builds/${b.id}`}>{b.id}</Link></td><td className="whitespace-nowrap text-xs">{when(b.createdAt)}</td><td>{b.version ?? "–"}</td><td><OutcomeBadge outcome={buildOutcome(b)} /></td><td className="max-w-[320px] truncate text-xs text-slate-400">{b.changeRequest ?? "first build"}</td></tr>)}</tbody>
          </table>
        </TableWrap>
      </Section>
    </div>
  );
}

