import type { Metadata } from "next";
import Link from "next/link";
import { randomBytes } from "node:crypto";
import { db } from "@/lib/db";
import { realUser } from "@/lib/auth";
import { loadTokenConfig } from "@/lib/cyrus/tokens/config";
import { dailyCapFor, effectiveTier, TIER_LABEL } from "@/lib/cyrus/tokens/economy";
import { tokenSummary } from "@/lib/cyrus/tokens/ledger";
import { tokensActiveFor } from "@/lib/cyrus/tokens/access";
import { requireCyrusAdmin, cyrusAdminMetadata } from "@/lib/cyrus/admin/gate";
import { canCyrusAdmin } from "@/lib/cyrus/admin/perms";
import { abuseSignals, countOutcomes } from "@/lib/cyrus/admin/metrics";
import { emailMap } from "@/lib/cyrus/admin/data";
import { activeSuspension, loadSuspensions } from "@/lib/cyrus/suspensions";
import { adminCyrusComp, adminCyrusGrant, adminCyrusRevoke, adminCyrusSuspend, adminCyrusUnsuspend } from "@/lib/actions-cyrus-admin";
import { Badge, StatCard } from "@/components/ui/primitives";
import { Empty, Flash, Hidden, Kv, Section, TableWrap, UserLink, n, tdRow, thCls, when } from "@/components/admin/cyrus/ui";

export const dynamic = "force-dynamic";
export async function generateMetadata(): Promise<Metadata> {
  return cyrusAdminMetadata("Users and tokens");
}

const DAY = 86_400_000;
/** The per-account limits in lib/modbuilder/create.ts (shown, not editable: they are code constants). */
const LIMITS = { perMinute: 3, perHour: 20, inflight: 2 };

async function findUser(q: string) {
  const v = q.trim();
  if (!v) return null;
  return db.user.findFirst({ where: v.includes("@") ? { email: { equals: v, mode: "insensitive" } } : { id: v }, select: { id: true, email: true, name: true, createdAt: true, role: true, emailVerifiedAt: true } });
}

export default async function CyrusAdminUsers({ searchParams }: { searchParams: Promise<Record<string, string | string[] | undefined>> }) {
  await requireCyrusAdmin("users");
  const me = (await realUser())!;
  const sp = await searchParams;
  const q = typeof sp.u === "string" ? sp.u.slice(0, 200) : "";
  const now = new Date();
  const cfg = await loadTokenConfig();
  const suspensions = await loadSuspensions();
  const token = randomBytes(8).toString("hex");
  const user = q ? await findUser(q) : null;
  const back = user ? `/admin/cyrus/users?u=${encodeURIComponent(user.id)}` : "/admin/cyrus/users";
  const can = { grant: canCyrusAdmin(me.role, "tokens.grant"), comp: canCyrusAdmin(me.role, "tokens.comp"), suspend: canCyrusAdmin(me.role, "user.suspend") };

  const search = (
    <form method="get" className="mb-5 flex flex-wrap items-end gap-2">
      <input name="u" defaultValue={q} placeholder="Customer email or user id" className="input w-full text-sm sm:w-80" aria-label="Customer" />
      <button className="btn-primary text-sm">Open</button>
      {q ? <Link href="/admin/cyrus/users" className="btn-ghost text-sm">Back to the list</Link> : null}
    </form>
  );

  if (!user) {
    const [accounts, comps, refusals] = await Promise.all([
      db.cyrusTokenAccount.findMany({ orderBy: { balance: "desc" }, take: 50 }),
      db.cyrusTokenAccount.findMany({ where: { tierOverride: { not: null } }, orderBy: { updatedAt: "desc" }, take: 50 }),
      db.modBuild.groupBy({ by: ["userId"], where: { status: "failed", errorCode: "refused", createdAt: { gt: new Date(now.getTime() - 30 * DAY) } }, _count: { _all: true }, orderBy: { _count: { userId: "desc" } }, take: 20 }),
    ]);
    const plans = await db.cyrusPlan.findMany({ where: { userId: { in: accounts.map((a) => a.userId) } } });
    const planBy = new Map(plans.map((p) => [p.userId, p]));
    const emails = await emailMap([...accounts.map((a) => a.userId), ...comps.map((a) => a.userId), ...suspensions.map((s) => s.userId), ...refusals.map((r) => r.userId)]);
    return (
      <div>
        <Flash sp={sp} />
        {search}
        <div className="grid min-w-0 xl:grid-cols-2 xl:gap-6">
          <Section title="Suspended accounts" sub="Building and/or community. Lift a suspension from the account page.">
            {suspensions.length === 0 ? <Empty>No suspended accounts.</Empty> : (
              <ul className="space-y-2 text-sm">{suspensions.map((s) => <li key={s.userId} className="flex flex-wrap items-center gap-2"><UserLink id={s.userId} email={emails.get(s.userId)} />{s.scopes.map((x) => <Badge key={x} tone="red">{x}</Badge>)}<span className="text-xs text-slate-500">{s.until ? `until ${s.until.slice(0, 10)}` : "until lifted"} · {s.reason}</span></li>)}</ul>
            )}
          </Section>
          <Section title="Safety refusals, 30 days" sub="Accounts whose builds the safety check refused (most first).">
            {refusals.length === 0 ? <Empty>No refused builds in 30 days.</Empty> : (
              <ul className="space-y-1 text-sm">{refusals.map((r) => <li key={r.userId} className="flex justify-between gap-2"><UserLink id={r.userId} email={emails.get(r.userId)} /><Badge tone={r._count._all >= 3 ? "red" : "amber"}>{r._count._all} refused</Badge></li>)}</ul>
            )}
          </Section>
        </div>
        <Section title="Token accounts" sub="Top 50 by balance. Open one for its ledger, grants and actions.">
          {accounts.length === 0 ? <Empty>No token accounts yet.</Empty> : (
            <TableWrap>
              <table className="w-full text-sm">
                <thead><tr className={thCls}><th>Account</th><th className="text-right">Balance</th><th className="text-right">Held</th><th>Models</th><th>Plan</th><th className="text-right">Granted</th><th className="text-right">Spent</th></tr></thead>
                <tbody>{accounts.map((a) => { const p = planBy.get(a.userId); const tier = effectiveTier({ plan: p ?? null, override: a.tierOverride, overrideUntil: a.tierOverrideUntil, now, cfg }); return (
                  <tr key={a.userId} className={tdRow}><td className="max-w-[220px] truncate"><UserLink id={a.userId} email={emails.get(a.userId)} /></td><td className="text-right tabular-nums">{n(a.balance)}</td><td className="text-right tabular-nums">{n(a.reserved)}</td><td>{TIER_LABEL[tier]}{a.tierOverride ? <span className="ml-1 text-xs text-amber-400">comp</span> : null}</td><td className="text-xs">{p ? `${p.priceTier} · ${p.status}${p.livemode ? "" : " · test"}` : "–"}</td><td className="text-right tabular-nums">{n(a.lifetimeGranted)}</td><td className="text-right tabular-nums">{n(a.lifetimeSpent)}</td></tr>
                ); })}</tbody>
              </table>
            </TableWrap>
          )}
        </Section>
        <Section title="Comped model tiers" sub="Accounts with an admin override (the owner's earlier comps included).">
          {comps.length === 0 ? <Empty>No comps.</Empty> : (
            <ul className="space-y-1 text-sm">{comps.map((c) => <li key={c.userId} className="flex flex-wrap justify-between gap-2"><UserLink id={c.userId} email={emails.get(c.userId)} /><span className="text-xs text-slate-400">{c.tierOverride === "all" ? "All models" : c.tierOverride} · {c.tierOverrideUntil ? `until ${c.tierOverrideUntil.toISOString().slice(0, 10)}` : "no end"}{c.tierOverrideUntil && c.tierOverrideUntil < now ? " (ended)" : ""}</span></li>)}</ul>
          )}
        </Section>
      </div>
    );
  }

  const since30 = new Date(now.getTime() - 30 * DAY);
  const [summary, acct, plan, lots, ledger, builds, recentHolds, posts, inflight, lastHour, lastMin, writeoffs, active] = await Promise.all([
    tokenSummary(user.id, now),
    db.cyrusTokenAccount.findUnique({ where: { userId: user.id } }),
    db.cyrusPlan.findUnique({ where: { userId: user.id } }),
    db.cyrusTokenLot.findMany({ where: { userId: user.id }, orderBy: { createdAt: "desc" }, take: 40 }),
    db.cyrusTokenLedger.findMany({ where: { userId: user.id }, orderBy: { createdAt: "desc" }, take: 60 }),
    db.modBuild.findMany({ where: { userId: user.id, createdAt: { gt: since30 } }, select: { id: true, status: true, errorCode: true, costUsd: true, createdAt: true, pluginName: true }, orderBy: { createdAt: "desc" }, take: 500 }),
    db.cyrusTokenReservation.findMany({ where: { userId: user.id, createdAt: { gt: new Date(now.getTime() - DAY) } }, select: { status: true, amount: true, charged: true } }),
    db.cyrusModPost.findMany({ where: { userId: user.id }, select: { id: true, reportCount: true, hiddenAt: true } }),
    db.modBuild.count({ where: { userId: user.id, status: { notIn: ["succeeded", "failed"] } } }),
    db.modBuild.count({ where: { userId: user.id, createdAt: { gt: new Date(now.getTime() - 3600_000) } } }),
    db.modBuild.count({ where: { userId: user.id, createdAt: { gt: new Date(now.getTime() - 60_000) } } }),
    db.cyrusTokenLedger.findMany({ where: { userId: user.id, kind: "spend", createdAt: { gt: since30 } }, select: { meta: true } }),
    tokensActiveFor(user, cfg),
  ]);
  const tier = effectiveTier({ plan: plan ?? null, override: acct?.tierOverride, overrideUntil: acct?.tierOverrideUntil, now, cfg });
  const usedToday = recentHolds.reduce((a, x) => a + (x.status === "held" ? x.amount : x.charged ?? 0), 0);
  const cap = dailyCapFor(user.createdAt, now, cfg);
  const writeoffTokens = writeoffs.reduce((a, l) => a + (Number((l.meta as { writeoff?: unknown } | null)?.writeoff) || 0), 0);
  const signals = abuseSignals({ builds30d: builds, reportsAgainst: posts.reduce((a, p) => a + p.reportCount, 0), hiddenPosts: posts.filter((p) => p.hiddenAt).length, usedToday, dailyCap: cap, writeoffTokens });
  const counts = countOutcomes(builds);
  const susp = { build: activeSuspension(suspensions, user.id, "build", now), community: activeSuspension(suspensions, user.id, "community", now) };
  const entry = suspensions.find((s) => s.userId === user.id);

  return (
    <div>
      <Flash sp={sp} />
      {search}
      <Section title={user.email} sub={<>{user.name ?? ""} · account since {when(user.createdAt)} · <span className="font-mono">{user.id}</span></>} right={<div className="flex flex-wrap gap-2">{active ? <Badge tone="green">in token economy</Badge> : <Badge tone="slate">outside token economy</Badge>}{susp.build ? <Badge tone="red">build suspended</Badge> : null}{susp.community ? <Badge tone="red">community suspended</Badge> : null}</div>}>
        <div className="grid grid-cols-2 gap-3 lg:grid-cols-4">
          <StatCard label="Available tokens" value={n(summary.available)} delta={`${n(summary.balance)} balance · ${n(summary.reserved)} held`} />
          <StatCard label="Models" value={TIER_LABEL[tier]} delta={acct?.tierOverride ? `comp: ${acct.tierOverride}${acct.tierOverrideUntil ? ` until ${acct.tierOverrideUntil.toISOString().slice(0, 10)}` : ""}` : plan ? `plan ${plan.priceTier} · ${plan.status}` : "no plan"} />
          <StatCard label="Builds, 30 days" value={n(counts.total)} delta={`${counts.succeeded} ok · ${counts.failed} failed · ${counts.refused} refused`} deltaGood={counts.refused === 0} />
          <StatCard label="Lifetime" value={`${n(summary.lifetimeGranted)} in`} delta={`${n(summary.lifetimeSpent)} spent`} />
        </div>
      </Section>

      <div className="grid min-w-0 xl:grid-cols-2 xl:gap-6">
        <Section title="Abuse flags" sub="Derived from this account's real builds, holds and posts.">
          {signals.length === 0 ? <Empty>No flags.</Empty> : <ul className="space-y-1.5 text-sm">{signals.map((s) => <li key={s.code} className="flex items-start gap-2"><Badge tone={s.level === "red" ? "red" : "amber"}>{s.level === "red" ? "flag" : "watch"}</Badge><span>{s.text}</span></li>)}</ul>}
        </Section>
        <Section title="Rate limits" sub="Today's token cap is a setting; the per-minute/hour limits are code constants (counted here from the DB).">
          <Kv rows={[
            ["Tokens, last 24 h", `${n(usedToday)} of ${n(cap)} (${now.getTime() - user.createdAt.getTime() < cfg.newAccountDays * DAY ? "new-account cap" : "daily cap"})`],
            ["Builds running", `${inflight} of ${LIMITS.inflight}`],
            ["Builds, last hour", `${lastHour} of ${LIMITS.perHour}`],
            ["Builds, last minute", `${lastMin} of ${LIMITS.perMinute}`],
            ["Free failures", `${cfg.freeFailures} per ${cfg.freeFailuresDays} days (settings)`],
          ]} />
        </Section>
      </div>

      {(can.grant || can.comp) && (
        <div className="grid min-w-0 gap-0 lg:grid-cols-3 lg:gap-6">
          {can.grant && (
            <form action={adminCyrusGrant} className="card mb-6 flex flex-col gap-2">
              <h2 className="text-sm font-semibold">Grant tokens</h2>
              <Hidden name="user" value={user.id} /><Hidden name="token" value={token} /><Hidden name="back" value={back} />
              <input name="amount" type="number" min={1} max={1000000} placeholder="amount" className="input text-sm" required />
              <input name="days" type="number" min={1} max={3650} placeholder={`expires in days (${cfg.adminGrantExpiryDays})`} className="input text-sm" />
              <input name="note" placeholder="note (shown in their history)" className="input text-sm" />
              <button className="btn-primary text-sm">Grant</button>
            </form>
          )}
          {can.grant && (
            <form action={adminCyrusRevoke} className="card mb-6 flex flex-col gap-2">
              <h2 className="text-sm font-semibold">Revoke tokens</h2>
              <Hidden name="user" value={user.id} /><Hidden name="token" value={token} /><Hidden name="back" value={back} />
              <input name="amount" type="number" min={1} placeholder="amount" className="input text-sm" required />
              <input name="note" placeholder="reason" className="input text-sm" />
              <button className="btn-secondary text-sm">Revoke</button>
              <p className="text-xs text-slate-500">Never below zero; never touches tokens a running build holds.</p>
            </form>
          )}
          {can.comp && (
            <form action={adminCyrusComp} className="card mb-6 flex flex-col gap-2">
              <h2 className="text-sm font-semibold">Comp a model tier</h2>
              <Hidden name="user" value={user.id} /><Hidden name="back" value={back} />
              <select name="tier" className="input text-sm" defaultValue={acct?.tierOverride ?? ""} aria-label="Tier"><option value="">No comp (remove)</option><option value="katara">Katara</option><option value="saka">Saka (+Katara)</option><option value="all">All models</option></select>
              <input name="days" type="number" min={1} placeholder="days (blank = no end)" className="input text-sm" />
              <input name="note" placeholder="why (audit log)" className="input text-sm" />
              <button className="btn-primary text-sm">Save comp</button>
              <p className="text-xs text-slate-500">Unlocks models without a plan; adds no tokens.</p>
            </form>
          )}
        </div>
      )}

      {can.suspend && (
        <Section title="Suspension" sub="Blocks new builds and/or community posting and publishing. Existing mods, downloads and installs are untouched.">
          {entry ? (
            <form action={adminCyrusUnsuspend} className="flex flex-wrap items-center gap-3 text-sm">
              <Hidden name="userId" value={user.id} /><Hidden name="back" value={back} />
              <span>Suspended from <b>{entry.scopes.join(" + ")}</b> {entry.until ? `until ${entry.until.slice(0, 10)}` : "until lifted"}: {entry.reason}</span>
              <button className="btn-secondary text-sm">Lift suspension</button>
            </form>
          ) : (
            <form action={adminCyrusSuspend} className="grid gap-2 sm:flex sm:flex-wrap sm:items-end">
              <Hidden name="user" value={user.id} /><Hidden name="back" value={back} />
              <label className="flex items-center gap-2 text-sm"><input type="checkbox" name="scope_build" value="1" /> Building</label>
              <label className="flex items-center gap-2 text-sm"><input type="checkbox" name="scope_community" value="1" /> Community</label>
              <input name="days" type="number" min={1} placeholder="days (blank = until lifted)" className="input text-sm sm:w-48" />
              <input name="reason" placeholder="Reason (required, audit log)" className="input text-sm sm:w-72" required minLength={3} />
              <button className="btn-danger text-sm">Suspend</button>
            </form>
          )}
        </Section>
      )}

      <div className="grid min-w-0 xl:grid-cols-2 xl:gap-6">
        <Section title="Grants (token lots)" sub="Each grant is a lot with its own source and expiry; spends draw the soonest-expiring first.">
          {lots.length === 0 ? <Empty>No grants yet.</Empty> : (
            <TableWrap>
              <table className="w-full text-xs">
                <thead><tr className={thCls}><th>Granted</th><th>Source</th><th className="text-right">Amount</th><th className="text-right">Left</th><th>Expires</th></tr></thead>
                <tbody>{lots.map((l) => <tr key={l.id} className={tdRow}><td className="whitespace-nowrap">{when(l.createdAt)}</td><td>{l.source}</td><td className="text-right tabular-nums">{n(l.amount)}</td><td className="text-right tabular-nums">{n(l.remaining)}</td><td className="whitespace-nowrap">{l.expiresAt ? when(l.expiresAt) : "never"}{l.expiresAt && l.expiresAt < now ? " (expired)" : ""}</td></tr>)}</tbody>
              </table>
            </TableWrap>
          )}
        </Section>
        <Section title="Recent builds" sub="Last 30 days.">
          {builds.length === 0 ? <Empty>No builds in 30 days.</Empty> : (
            <ul className="space-y-1 text-sm">{builds.slice(0, 15).map((b) => <li key={b.id} className="flex justify-between gap-2"><Link className="min-w-0 truncate underline" href={`/admin/cyrus/builds/${b.id}`}>{b.pluginName ?? b.id}</Link><span className="shrink-0 text-xs text-slate-500">{b.status}{b.errorCode ? ` (${b.errorCode})` : ""} · {when(b.createdAt).slice(5, 16)}</span></li>)}</ul>
          )}
        </Section>
      </div>

      <Section title="Ledger" sub="Latest 60 rows, append-only.">
        {ledger.length === 0 ? <Empty>No ledger rows.</Empty> : (
          <TableWrap>
            <table className="w-full text-xs">
              <thead><tr className={thCls}><th>When</th><th>Kind</th><th className="text-right">Δ</th><th className="text-right">Balance</th><th>Source / build</th><th>Note</th></tr></thead>
              <tbody>{ledger.map((l) => <tr key={l.id} className={tdRow}><td className="whitespace-nowrap">{when(l.createdAt)}</td><td>{l.kind}</td><td className={`text-right tabular-nums ${l.delta > 0 ? "text-emerald-400" : l.delta < 0 ? "text-rose-300" : ""}`}>{l.delta > 0 ? "+" : ""}{n(l.delta)}</td><td className="text-right tabular-nums">{n(l.balanceAfter)}</td><td className="max-w-[200px] truncate font-mono">{l.buildId ? <Link className="underline" href={`/admin/cyrus/builds/${l.buildId}`}>{l.buildId}</Link> : l.source ?? ""}</td><td>{l.note ?? ""}</td></tr>)}</tbody>
            </table>
          </TableWrap>
        )}
      </Section>
    </div>
  );
}

