import type { Metadata } from "next";
import { existsSync } from "node:fs";
import { join } from "node:path";
import { db } from "@/lib/db";
import { realUser } from "@/lib/auth";
import { svcHealth } from "@/lib/modbuilder/client";
import type { ModBuildResult } from "@/lib/modbuilder/types";
import { loadTokenConfig } from "@/lib/cyrus/tokens/config";
import { CYRUS_MODELS } from "@/lib/cyrus/models";
import { readCyrusMeta } from "@/lib/cyrus/meta";
import { CYRUS_BUILDABLE_GAMES } from "@/lib/cyrus/game-status";
import { loadCyrusGameStatuses } from "@/lib/cyrus/game-status.server";
import { requireCyrusAdmin, cyrusAdminMetadata } from "@/lib/cyrus/admin/gate";
import { canCyrusAdmin } from "@/lib/cyrus/admin/perms";
import { loadReadiness } from "@/lib/cyrus/admin/readiness";
import { EFFICIENCY_KNOBS, TIER_DEFAULTS, observedTierModels, priceFor, readHealth, shortModel } from "@/lib/cyrus/admin/service";
import { mean } from "@/lib/cyrus/admin/metrics";
import { adminCyrusSetGameStatus } from "@/lib/actions-cyrus-admin";
import { Badge } from "@/components/ui/primitives";
import { Empty, Flash, Hidden, Section, TableWrap, n, tdRow, thCls, usd } from "@/components/admin/cyrus/ui";

export const dynamic = "force-dynamic";
export async function generateMetadata(): Promise<Metadata> {
  return cyrusAdminMetadata("Games and models");
}

const DAY = 86_400_000;
const statusTone = (s: string) => (s === "live" ? "green" : s === "disabled" ? "red" : "slate") as "green" | "red" | "slate";

export default async function CyrusAdminGames({ searchParams }: { searchParams: Promise<Record<string, string | string[] | undefined>> }) {
  await requireCyrusAdmin("games");
  const me = (await realUser())!;
  const sp = await searchParams;
  const canSet = canCyrusAdmin(me.role, "game.status");
  const [games, cfg, health, recent] = await Promise.all([
    loadCyrusGameStatuses(true),
    loadTokenConfig(),
    svcHealth(),
    db.modBuild.findMany({ where: { createdAt: { gt: new Date(Date.now() - 30 * DAY) } }, select: { cyrus: true, result: true, costUsd: true, status: true }, take: 3000 }),
  ]);
  const readiness = await Promise.all(games.map((g) => loadReadiness(g.id)));
  const svc = readHealth(health);
  const observed = observedTierModels(recent.map((r) => ({ tier: readCyrusMeta(r.cyrus).model ?? null, calls: (r.result as unknown as ModBuildResult | null)?.ai?.calls ?? [] })));
  const costBy = (m: string) => mean(recent.filter((r) => readCyrusMeta(r.cyrus).model === m && (r.status === "succeeded" || r.status === "failed")).map((r) => r.costUsd));
  const supportFile = (id: string) => existsSync(join(process.cwd(), "lib", "cyrus", "games", `${id}.ts`));
  const reported = new Map(svc.features.map((f) => [f.key, f.value]));

  return (
    <div>
      <Flash sp={sp} />
      <Section title="Games" sub={<>The file <span className="font-mono">lib/cyrus/games.ts</span> is the default; a setting <span className="font-mono">cyrus_game_&lt;id&gt;_status</span> overrides it. Only games with a real build pipeline ({CYRUS_BUILDABLE_GAMES.join(", ")}) can be live. Disabled = hidden and no new builds; existing mods are untouched.</>}>
        <TableWrap>
          <table className="w-full text-sm">
            <thead><tr className={thCls}><th>Game</th><th>Now</th><th>File default</th><th>Builds</th><th>Pipeline</th><th>GameSupport</th><th>Readiness</th>{canSet ? <th>Change</th> : null}</tr></thead>
            <tbody>
              {games.map((g, i) => {
                const r = readiness[i];
                const buildable = CYRUS_BUILDABLE_GAMES.includes(g.id);
                return (
                  <tr key={g.id} className={tdRow}>
                    <td className="whitespace-nowrap font-medium">{g.name}<div className="font-mono text-xs text-slate-500">{g.id}</div></td>
                    <td><Badge tone={statusTone(g.adminStatus)}>{g.adminStatus}</Badge>{g.overridden ? <div className="text-xs text-amber-400">override</div> : null}</td>
                    <td className="text-xs">{g.defaultStatus}</td>
                    <td className="max-w-[220px] text-xs text-slate-400">{g.builds}<div className="text-slate-500">{g.loader}{g.versions.length ? ` · ${g.versions.join(", ")}` : ""}</div></td>
                    <td>{buildable ? <Badge tone="green">real builds</Badge> : <Badge tone="slate">template preview</Badge>}</td>
                    <td className="text-xs">{supportFile(g.id) ? "yes" : <span className="text-slate-500">not merged yet</span>}</td>
                    <td className="whitespace-nowrap text-xs">{r ? <>{r.open} open · {r.decisions} decision(s) · {r.done} done</> : <span className="text-slate-500">no checklist</span>}</td>
                    {canSet ? (
                      <td>
                        <form action={adminCyrusSetGameStatus} className="flex items-center gap-1">
                          <Hidden name="gameId" value={g.id} /><Hidden name="back" value="/admin/cyrus/games" />
                          <select name="status" defaultValue={g.overridden ? g.adminStatus : "default"} className="input py-1 text-xs" aria-label={`${g.name} status`}>
                            <option value="default">file default ({g.defaultStatus})</option>
                            <option value="live" disabled={!buildable}>live{buildable ? "" : " (no pipeline)"}</option>
                            <option value="soon">soon</option>
                            <option value="disabled">disabled</option>
                          </select>
                          <button className="btn-secondary px-2 py-1 text-xs">Save</button>
                        </form>
                      </td>
                    ) : null}
                  </tr>
                );
              })}
            </tbody>
