                    <p className="mt-1 break-words"><b>{p.title ?? "(reply)"}</b> {p.body.slice(0, 300)}</p>
                    <p className="mt-1 text-xs text-slate-500">Reasons: {rs.map((r) => r.reason).join(" · ")}</p>
