                  {can.mod ? (
                    <div className="flex shrink-0 flex-wrap gap-2">
                      <form action={adminCyrusResolveReports} className="flex gap-1"><Hidden name="postId" value={p.id} /><Hidden name="hide" value="1" /><Hidden name="back" value={BACK} /><input name="reason" placeholder="Reason" className="input w-32 py-1 text-xs" /><button className="btn-danger text-xs">Hide</button></form>
                      <form action={adminCyrusResolveReports}><Hidden name="postId" value={p.id} /><Hidden name="hide" value="0" /><Hidden name="back" value={BACK} /><button className="btn-secondary text-xs">Dismiss</button></form>
