          )}
        </Section>
        <Section title="Creator suspensions" sub="Accounts that cannot post, report or publish. Manage on Users & tokens.">
          {community.length === 0 ? <Empty>No community suspensions.</Empty> : (
            <ul className="space-y-1 text-sm">{community.map((s) => <li key={s.userId} className="flex flex-wrap justify-between gap-2"><UserLink id={s.userId} email={emails.get(s.userId)} /><span className="text-xs text-slate-500">{s.until ? `until ${s.until.slice(0, 10)}` : "until lifted"} · {s.reason}</span></li>)}</ul>
          )}
        </Section>
      </div>

      <Section title="Takedowns" sub="A taken-down page is hidden from everyone but its creator and staff; the creator sees the reason. Restore reverses it.">
        {takenDown.length > 0 ? (
          <ul className="mb-4 space-y-2 text-sm">{takenDown.map((p) => <li key={p.id} className="flex flex-wrap items-center justify-between gap-2"><span className="min-w-0"><Badge tone="red">down</Badge> <Link className="underline" href={`/dashboard/nxlabs/cyrus/${p.slug}`}>{p.title}</Link> <span className="text-xs text-slate-500">{p.hiddenReason ?? ""} · {when(p.hiddenAt)}</span></span>{can.page ? <form action={adminCyrusPageTakedown}><Hidden name="pageId" value={p.id} /><Hidden name="down" value="0" /><Hidden name="back" value={BACK} /><button className="btn-secondary text-xs">Restore</button></form> : null}</li>)}</ul>
