            </table>
          </TableWrap>
        )}
      </Section>

      <Section title="Remixes and disputes" sub="Recent “build on this mod” copies. Dispute records (credit or licence complaints between creators) need the community branch's data.">
        {forks.length === 0 ? <Empty>No remixes yet.</Empty> : (
          <ul className="mb-3 space-y-1 text-sm">{forks.map((f) => { const src = pageBy.get(f.sourcePageId); return <li key={f.buildId} className="flex flex-wrap justify-between gap-2"><span className="min-w-0"><UserLink id={f.userId} email={emails.get(f.userId)} /> remixed {src ? <Link className="underline" href={`/dashboard/nxlabs/cyrus/${src.slug}`}>{src.title}</Link> : f.sourcePageId}</span><span className="text-xs text-slate-500">{when(f.createdAt)} · <Link className="underline" href={`/admin/cyrus/builds/${f.buildId}`}>copy</Link></span></li>; })}</ul>
        )}
        <Empty waitsFor="feature/cyrus-v6-community">No dispute queue yet: the community branch adds remix permissions, credit chains and community versions; disputes plug in here.</Empty>
      </Section>

      <Section title="Networking review queue" sub="Mods whose latest version declares network hosts (capability manifest). Approving covers exactly the hosts listed; a new host sends the mod back to review. Nothing networks while the global switch is off." right={netOn ? <Badge tone="red">networking ON</Badge> : <Badge tone="green">networking OFF</Badge>}>
        {can.net ? (
          <form action={adminCyrusNetKillSwitch} className="mb-4 flex flex-wrap items-center gap-3 rounded-lg border border-white/[0.06] p-3">
            <Hidden name="on" value={netOn ? "0" : "1"} /><Hidden name="back" value={BACK} />
            <span className="text-sm">Global switch <span className="font-mono text-xs">{NET_KILL_SWITCH}</span>: <b>{netOn ? "on" : "off"}</b></span>
            {netOn ? null : <Confirm label="Turn on only after the capabilities branch is merged, its scanner is deployed and the threat model is approved." />}
            <button className={netOn ? "btn-danger text-sm" : "btn-secondary text-sm"}>{netOn ? "Kill switch: turn off" : "Turn on"}</button>
          </form>
        ) : null}
        {netMods.length === 0 ? <Empty waitsFor="feature/cyrus-v6-capabilities">No mod declares network hosts. Today the build service blocks all networking, so this stays empty until the capability manifest ships.</Empty> : (
          <TableWrap>
            <table className="w-full text-sm">
              <thead><tr className={thCls}><th>Mod</th><th>Hosts (purpose · player data)</th><th>State</th>{can.net ? <th>Decide</th> : null}</tr></thead>
              <tbody>{netMods.map(({ page, hosts, state }) => (
                <tr key={page.id} className={tdRow}>
                  <td><Link className="underline" href={`/dashboard/nxlabs/cyrus/${page.slug}`}>{page.title}</Link><div className="text-xs text-slate-500">{page.visibility.toLowerCase()}</div></td>
                  <td className="text-xs"><ul>{hosts.map((h) => <li key={h.host}><span className="font-mono">{h.host}</span>{h.purpose ? ` · ${h.purpose}` : ""}{h.sendsPlayerData === true ? <Badge tone="amber">player data</Badge> : null}</li>)}</ul></td>
                  <td><Badge tone={state === "approved" ? "green" : state === "blocked" ? "red" : "amber"}>{state}</Badge></td>
                  {can.net ? <td><form action={adminCyrusNetReview} className="flex flex-wrap gap-1"><Hidden name="rootBuildId" value={page.rootBuildId} /><Hidden name="hosts" value={hosts.map((h) => h.host).join(",")} /><Hidden name="back" value={BACK} /><input name="note" placeholder="Note" className="input w-28 py-1 text-xs" /><button name="decision" value="approved" className="btn-secondary text-xs">Approve</button><button name="decision" value="blocked" className="btn-danger text-xs">Block</button>{reviews[page.rootBuildId] ? <button name="decision" value="clear" className="btn-ghost text-xs">Clear</button> : null}</form></td> : null}
                </tr>
              ))}</tbody>
            </table>
          </TableWrap>
        )}
      </Section>

      <Section title="Moderation log" sub="Latest 30 moderation actions (all of them are in Audit & settings).">
        {audit.length === 0 ? <Empty>No moderation actions yet.</Empty> : (
          <ul className="space-y-1 text-xs">{audit.map((a) => { const d = readAuditDetail(a.detail); return <li key={a.id} className="flex flex-wrap gap-2"><span className="whitespace-nowrap text-slate-500">{when(a.createdAt)}</span><span className="font-mono">{a.action.replace(CYRUS_AUDIT_PREFIX, "")}</span><span className="text-slate-400">{a.target ?? d.text ?? ""}</span><span className="text-slate-500">by {emails.get(a.userId ?? "") ?? a.userId}</span></li>; })}</ul>
        )}
      </Section>
    </div>
  );
}

