import { Badge, StatCard } from "@/components/ui/primitives";
import { Confirm, Empty, Flash, Hidden, Section, TableWrap, UserLink, n, tdRow, thCls, when } from "@/components/admin/cyrus/ui";

export const dynamic = "force-dynamic";
export async function generateMetadata(): Promise<Metadata> {
  return cyrusAdminMetadata("Community moderation");
}

const BACK = "/admin/cyrus/community";

export default async function CyrusAdminCommunity({ searchParams }: { searchParams: Promise<Record<string, string | string[] | undefined>> }) {
  await requireCyrusAdmin("community");
  const me = (await realUser())!;
  const sp = await searchParams;
  const can = { mod: canCyrusAdmin(me.role, "report.hide"), page: canCyrusAdmin(me.role, "page.takedown"), net: canCyrusAdmin(me.role, "network.review") };
  const [reports, hiddenPosts, pages, forks, suspensions, netOn, netRaw, audit] = await Promise.all([
    db.cyrusModReport.findMany({ where: { resolvedAt: null }, orderBy: { createdAt: "desc" }, take: 300 }),
    db.cyrusModPost.findMany({ where: { hiddenAt: { not: null } }, orderBy: { hiddenAt: "desc" }, take: 100 }),
    db.cyrusModPage.findMany({ orderBy: { updatedAt: "desc" }, take: 300, select: { id: true, slug: true, title: true, userId: true, visibility: true, hiddenAt: true, hiddenReason: true, latestBuildId: true, rootBuildId: true, forkOfPageId: true, updatedAt: true } }),
    db.cyrusFork.findMany({ orderBy: { createdAt: "desc" }, take: 30 }),
    loadSuspensions(),
    getSettingBool(NET_KILL_SWITCH, false),
    db.setting.findUnique({ where: { key: NET_REVIEWS_KEY } }),
    db.auditLog.findMany({ where: { OR: [{ action: { in: ["cyrus.admin.report.hide", "cyrus.admin.report.dismiss", "cyrus.admin.post.unhide", "cyrus.admin.page.takedown", "cyrus.admin.page.restore", "cyrus.admin.user.suspend", "cyrus.admin.user.unsuspend", "cyrus.admin.network.review", "cyrus.admin.network.killswitch"] } }, { action: { in: ["cyrusmods.report.hide", "cyrusmods.report.dismiss", "cyrusmods.page.hide", "cyrusmods.page.unhide", "cyrusmods.hide", "cyrusmods.unhide"] } }] }, orderBy: { createdAt: "desc" }, take: 30 }),
  ]);
  const reportedPosts = await db.cyrusModPost.findMany({ where: { id: { in: [...new Set(reports.map((r) => r.postId))] } } });
  const pageBy = new Map(pages.map((p) => [p.id, p]));
  const missingPageIds = [...new Set([...reportedPosts, ...hiddenPosts].map((p) => p.pageId))].filter((id) => !pageBy.has(id));
  if (missingPageIds.length) for (const p of await db.cyrusModPage.findMany({ where: { id: { in: missingPageIds } }, select: { id: true, slug: true, title: true, userId: true, visibility: true, hiddenAt: true, hiddenReason: true, latestBuildId: true, rootBuildId: true, forkOfPageId: true, updatedAt: true } })) pageBy.set(p.id, p);
  const latest = await db.modBuild.findMany({ where: { id: { in: pages.map((p) => p.latestBuildId).filter((x): x is string => !!x) } }, select: { id: true, result: true, cyrus: true } });
  const latestBy = new Map(latest.map((b) => [b.id, b]));
  const reviews = parseNetReviews(netRaw?.value);
  const netMods = pages
    .map((p) => {
      const b = p.latestBuildId ? latestBy.get(p.latestBuildId) : null;
      const hosts = b ? declaredNetwork(b.result, b.cyrus) : null;
      return hosts ? { page: p, hosts, state: reviewState(hosts, reviews[p.rootBuildId]) } : null;
    })
    .filter((x): x is NonNullable<typeof x> => !!x);
  const emails = await emailMap([...reportedPosts.map((p) => p.userId), ...hiddenPosts.map((p) => p.userId), ...pages.map((p) => p.userId), ...forks.map((f) => f.userId), ...suspensions.map((s) => s.userId), ...audit.map((a) => a.userId ?? "")]);
  const community = suspensions.filter((s) => s.scopes.includes("community"));
  const takenDown = pages.filter((p) => p.hiddenAt);
  const publicPages = pages.filter((p) => p.visibility === "PUBLIC" && !p.hiddenAt);

  return (
    <div>
      <Flash sp={sp} />
      <div className="mb-6 grid grid-cols-2 gap-3 lg:grid-cols-4">
        <StatCard label="Open reports" value={n(reports.length)} delta={`${reportedPosts.length} post(s)`} deltaGood={reports.length === 0} />
        <StatCard label="Hidden posts" value={n(hiddenPosts.length)} />
        <StatCard label="Pages taken down" value={n(takenDown.length)} delta={`${publicPages.length} public pages`} />
        <StatCard label="Mod networking" value={netOn ? "ON" : "OFF"} delta={`${netMods.filter((m) => m.state === "pending" || m.state === "changed").length} waiting for review`} deltaGood={!netOn} />
      </div>

      <Section title="Reports queue" sub="Open reports, grouped by post. Hide closes them and hides the post; Dismiss closes them and keeps it visible (3 reports auto-hide a post until review).">
        {reportedPosts.length === 0 ? <Empty>No open reports.</Empty> : (
          <ul className="divide-y divide-white/[0.06]">
            {reportedPosts.map((p) => {
              const pg = pageBy.get(p.pageId);
              const rs = reports.filter((r) => r.postId === p.id);
              return (
                <li key={p.id} className="flex flex-col gap-2 py-3 sm:flex-row sm:items-start sm:justify-between">
                  <div className="min-w-0 text-sm">
                    <p className="flex flex-wrap items-center gap-2"><Badge tone="amber">{rs.length} report(s)</Badge>{p.hiddenAt ? <Badge tone="red">hidden</Badge> : <Badge tone="green">visible</Badge>}<span className="text-xs text-slate-500">on {pg ? <Link className="underline" href={`/dashboard/nxlabs/cyrus/${pg.slug}#community`}>{pg.title}</Link> : p.pageId} by <UserLink id={p.userId} email={emails.get(p.userId)} /></span></p>
                    <p className="mt-1 break-words"><b>{p.title ?? "(reply)"}</b> {p.body.slice(0, 300)}</p>
                    <p className="mt-1 text-xs text-slate-500">Reasons: {rs.map((r) => r.reason).join(" · ")}</p>
                  </div>
                  {can.mod ? (
                    <div className="flex shrink-0 flex-wrap gap-2">
                      <form action={adminCyrusResolveReports} className="flex gap-1"><Hidden name="postId" value={p.id} /><Hidden name="hide" value="1" /><Hidden name="back" value={BACK} /><input name="reason" placeholder="Reason" className="input w-32 py-1 text-xs" /><button className="btn-danger text-xs">Hide</button></form>
                      <form action={adminCyrusResolveReports}><Hidden name="postId" value={p.id} /><Hidden name="hide" value="0" /><Hidden name="back" value={BACK} /><button className="btn-secondary text-xs">Dismiss</button></form>
                    </div>
                  ) : null}
                </li>
              );
            })}
          </ul>
        )}
      </Section>

      <div className="grid min-w-0 xl:grid-cols-2 xl:gap-6">
        <Section title="Hidden posts" sub="Hidden by a moderator, the mod's creator, or auto-hidden by reports.">
          {hiddenPosts.length === 0 ? <Empty>No hidden posts.</Empty> : (
            <ul className="space-y-2 text-sm">{hiddenPosts.map((p) => <li key={p.id} className="flex flex-wrap items-start justify-between gap-2"><div className="min-w-0"><p className="truncate"><b>{p.title ?? "(reply)"}</b> {p.body.slice(0, 120)}</p><p className="text-xs text-slate-500">{p.hiddenReason ?? "hidden"} · {when(p.hiddenAt)} · {pageBy.get(p.pageId)?.title ?? p.pageId}</p></div>{can.mod ? <form action={adminCyrusUnhidePost}><Hidden name="postId" value={p.id} /><Hidden name="back" value={BACK} /><button className="btn-secondary text-xs">Unhide</button></form> : null}</li>)}</ul>
          )}
        </Section>
        <Section title="Creator suspensions" sub="Accounts that cannot post, report or publish. Manage on Users & tokens.">
          {community.length === 0 ? <Empty>No community suspensions.</Empty> : (
            <ul className="space-y-1 text-sm">{community.map((s) => <li key={s.userId} className="flex flex-wrap justify-between gap-2"><UserLink id={s.userId} email={emails.get(s.userId)} /><span className="text-xs text-slate-500">{s.until ? `until ${s.until.slice(0, 10)}` : "until lifted"} · {s.reason}</span></li>)}</ul>
          )}
        </Section>
      </div>

      <Section title="Takedowns" sub="A taken-down page is hidden from everyone but its creator and staff; the creator sees the reason. Restore reverses it.">
        {takenDown.length > 0 ? (
          <ul className="mb-4 space-y-2 text-sm">{takenDown.map((p) => <li key={p.id} className="flex flex-wrap items-center justify-between gap-2"><span className="min-w-0"><Badge tone="red">down</Badge> <Link className="underline" href={`/dashboard/nxlabs/cyrus/${p.slug}`}>{p.title}</Link> <span className="text-xs text-slate-500">{p.hiddenReason ?? ""} · {when(p.hiddenAt)}</span></span>{can.page ? <form action={adminCyrusPageTakedown}><Hidden name="pageId" value={p.id} /><Hidden name="down" value="0" /><Hidden name="back" value={BACK} /><button className="btn-secondary text-xs">Restore</button></form> : null}</li>)}</ul>
        ) : <div className="mb-4"><Empty>No pages taken down.</Empty></div>}
        {publicPages.length === 0 ? <Empty>No public mod pages yet (pages stay private until their creator publishes them).</Empty> : (
          <TableWrap>
            <table className="w-full text-sm">
              <thead><tr className={thCls}><th>Public page</th><th>Creator</th><th>Updated</th>{can.page ? <th>Take down</th> : null}</tr></thead>
              <tbody>{publicPages.slice(0, 50).map((p) => <tr key={p.id} className={tdRow}><td><Link className="underline" href={`/dashboard/nxlabs/cyrus/${p.slug}`}>{p.title}</Link>{p.forkOfPageId ? <span className="ml-1 text-xs text-slate-500">(remix)</span> : null}</td><td className="max-w-[200px] truncate"><UserLink id={p.userId} email={emails.get(p.userId)} /></td><td className="whitespace-nowrap text-xs">{when(p.updatedAt)}</td>{can.page ? <td><form action={adminCyrusPageTakedown} className="flex gap-1"><Hidden name="pageId" value={p.id} /><Hidden name="down" value="1" /><Hidden name="back" value={BACK} /><input name="reason" required minLength={3} placeholder="Reason" className="input w-32 py-1 text-xs" /><button className="btn-danger text-xs">Take down</button></form></td> : null}</tr>)}</tbody>
            </table>
          </TableWrap>
        )}
      </Section>

      <Section title="Remixes and disputes" sub="Recent “build on this mod” copies. Dispute records (credit or licence complaints between creators) need the community branch's data.">
        {forks.length === 0 ? <Empty>No remixes yet.</Empty> : (
          <ul className="mb-3 space-y-1 text-sm">{forks.map((f) => { const src = pageBy.get(f.sourcePageId); return <li key={f.buildId} className="flex flex-wrap justify-between gap-2"><span className="min-w-0"><UserLink id={f.userId} email={emails.get(f.userId)} /> remixed {src ? <Link className="underline" href={`/dashboard/nxlabs/cyrus/${src.slug}`}>{src.title}</Link> : f.sourcePageId}</span><span className="text-xs text-slate-500">{when(f.createdAt)} · <Link className="underline" href={`/admin/cyrus/builds/${f.buildId}`}>copy</Link></span></li>; })}</ul>
        )}
        <Empty waitsFor="feature/cyrus-v6-community">No dispute queue yet: the community branch adds remix permissions, credit chains and community versions; disputes plug in here.</Empty>
      </Section>

      <Section title="Networking review queue" sub="Mods whose latest version declares network hosts (capability manifest). Approving covers exactly the hosts listed; a new host sends the mod back to review. Nothing networks while the global switch is off." right={netOn ? <Badge tone="red">networking ON</Badge> : <Badge tone="green">networking OFF</Badge>}>
        {can.net ? (
          <form action={adminCyrusNetKillSwitch} className="mb-4 flex flex-wrap items-center gap-3 rounded-lg border border-white/[0.06] p-3">
            <Hidden name="on" value={netOn ? "0" : "1"} /><Hidden name="back" value={BACK} />
            <span className="text-sm">Global switch <span className="font-mono text-xs">{NET_KILL_SWITCH}</span>: <b>{netOn ? "on" : "off"}</b></span>
            {netOn ? null : <Confirm label="Turn on only after the capabilities branch is merged, its scanner is deployed and the threat model is approved." />}
            <button className={netOn ? "btn-danger text-sm" : "btn-secondary text-sm"}>{netOn ? "Kill switch: turn off" : "Turn on"}</button>
          </form>
        ) : null}
