import type { Metadata } from "next";
import Link from "next/link";
import { db } from "@/lib/db";
import { getSettingBool } from "@/lib/settings";
import type { ModBuildResult } from "@/lib/modbuilder/types";
import { requireCyrusAdmin, cyrusAdminMetadata } from "@/lib/cyrus/admin/gate";
import { emailMap } from "@/lib/cyrus/admin/data";
import { loadLibraryIndex, optionalFindMany } from "@/lib/cyrus/admin/optional";
import { Badge, StatCard } from "@/components/ui/primitives";
import { Empty, Flash, Section, TableWrap, UserLink, n, tdRow, thCls, when } from "@/components/admin/cyrus/ui";

export const dynamic = "force-dynamic";
export async function generateMetadata(): Promise<Metadata> {
  return cyrusAdminMetadata("Library and safety");
}

const DAY = 86_400_000;

export default async function CyrusAdminLibrary({ searchParams }: { searchParams: Promise<Record<string, string | string[] | undefined>> }) {
  await requireCyrusAdmin("library");
  const sp = await searchParams;
  const since = new Date(Date.now() - 30 * DAY);
  const [lib, scanned, watchOn, watchDry, alerts, signals] = await Promise.all([
    loadLibraryIndex(),
    db.modBuild.findMany({ where: { createdAt: { gt: since }, status: "failed", errorCode: "refused" }, select: { id: true, userId: true, createdAt: true, error: true, result: true, pluginName: true }, orderBy: { createdAt: "desc" }, take: 200 }),
    getSettingBool("cyrus_compat_watch_enabled", false),
    getSettingBool("cyrus_compat_watch_dry_run", true),
    optionalFindMany("cyrusCreatorAlert", { orderBy: { lastSeenAt: "desc" }, take: 50 }),
    optionalFindMany("cyrusModSignal", { where: { createdAt: { gt: new Date(Date.now() - 7 * DAY) } }, orderBy: { createdAt: "desc" }, take: 50 }),
  ]);
  // Every scanned build with a block/warn finding in 30 days (refused or not), for the rule table.
  const withFindings = await db.modBuild.findMany({ where: { createdAt: { gt: since }, status: { in: ["succeeded", "failed"] } }, select: { id: true, result: true }, take: 3000 });
  const ruleCount = new Map<string, { block: number; warn: number }>();
  for (const b of withFindings) {
    for (const f of (b.result as unknown as ModBuildResult | null)?.safety?.findings ?? []) {
      const c = ruleCount.get(f.rule) ?? { block: 0, warn: 0 };
      c[f.severity === "block" ? "block" : "warn"] += 1;
      ruleCount.set(f.rule, c);
    }
  }
  const rules = [...ruleCount.entries()].sort((a, b) => b[1].block - a[1].block || b[1].warn - a[1].warn);
  const emails = await emailMap(scanned.map((s) => s.userId));
  const cats = new Map<string, { total: number; verified: number }>();
  for (const p of lib?.patterns ?? []) {
    const c = cats.get(p.category) ?? { total: 0, verified: 0 };
    c.total += 1;
    if (p.verified) c.verified += 1;
    cats.set(p.category, c);
  }
  const versions = [...new Set((lib?.patterns ?? []).flatMap((p) => p.versions))].sort().reverse();

  return (
    <div>
      <Flash sp={sp} />
      <div className="mb-6 grid grid-cols-2 gap-3 lg:grid-cols-4">
        <StatCard label="Library patterns" value={lib ? n(lib.patterns.length) : "–"} delta={lib ? `${lib.patterns.filter((p) => p.verified).length} verified` : "library not merged yet"} />
        <StatCard label="Refused by safety, 30 d" value={n(scanned.length)} deltaGood={scanned.length === 0} />
        <StatCard label="Scan rules that fired" value={n(rules.length)} delta={`${n(withFindings.length)} finished builds scanned`} />
        <StatCard label="Compat watch" value={watchOn ? (watchDry ? "dry run" : "sending") : "off"} delta={alerts ? `${alerts.length} alert row(s)` : "lifecycle not merged yet"} />
      </div>

      <Section title="Pattern library coverage" sub="Verified building blocks the generator can retrieve, by universal category, with the game versions they were verified on.">
        {!lib ? <Empty waitsFor="feature/cyrus-v6-library">No pattern library index in this build.</Empty> : lib.patterns.length === 0 ? <Empty>The library index is empty.</Empty> : (
          <>
            <TableWrap>
              <table className="w-full text-sm">
                <thead><tr className={thCls}><th>Category</th><th className="text-right">Patterns</th><th className="text-right">Verified</th><th className="text-right">Coverage</th></tr></thead>
                <tbody>{[...cats.entries()].sort((a, b) => b[1].total - a[1].total).map(([c, v]) => <tr key={c} className={tdRow}><td>{c}</td><td className="text-right">{v.total}</td><td className="text-right">{v.verified}</td><td className="text-right">{Math.round((v.verified / v.total) * 100)}%</td></tr>)}</tbody>
              </table>
            </TableWrap>
            <p className="mt-2 text-xs text-slate-500">Versions covered: {versions.join(", ") || "none recorded"} · source <span className="font-mono">{lib.source}</span></p>
            <details className="mt-3"><summary className="cursor-pointer text-xs text-slate-400">All patterns</summary>
              <ul className="mt-2 space-y-1 text-xs">{lib.patterns.map((p) => <li key={p.id} className="flex flex-wrap gap-2"><Badge tone={p.verified ? "green" : "slate"}>{p.status}</Badge><span className="font-mono">{p.id}</span><span>{p.title}</span><span className="text-slate-500">{p.versions.join(", ")}{p.checkedAt ? ` · checked ${p.checkedAt.slice(0, 10)}` : ""}{p.license ? ` · ${p.license}` : ""}</span></li>)}</ul>
            </details>
          </>
        )}
      </Section>

      <div className="grid min-w-0 xl:grid-cols-2 xl:gap-6">
        <Section title="Recent safety refusals" sub="Builds the safety check refused in the last 30 days.">
          {scanned.length === 0 ? <Empty>No refused builds in 30 days.</Empty> : (
            <ul className="space-y-2 text-sm">{scanned.slice(0, 30).map((b) => { const f = (b.result as unknown as ModBuildResult | null)?.safety?.findings?.find((x) => x.severity === "block"); return <li key={b.id} className="min-w-0"><p className="flex flex-wrap items-center gap-2"><Link className="font-mono text-xs underline" href={`/admin/cyrus/builds/${b.id}`}>{b.id}</Link><span className="text-xs text-slate-500">{when(b.createdAt)} · <UserLink id={b.userId} email={emails.get(b.userId)} /></span></p><p className="break-words text-xs text-slate-400">{f ? <><span className="font-mono">{f.rule}</span>: {f.message}</> : b.error ?? "refused"}</p></li>; })}</ul>
          )}
        </Section>
        <Section title="Scan rules that fired" sub="Block and warn findings across finished builds, 30 days.">
          {rules.length === 0 ? <Empty>No findings in 30 days.</Empty> : (
            <TableWrap>
              <table className="w-full text-sm">
                <thead><tr className={thCls}><th>Rule</th><th className="text-right">Block</th><th className="text-right">Warn</th></tr></thead>
                <tbody>{rules.slice(0, 40).map(([r, c]) => <tr key={r} className={tdRow}><td className="font-mono text-xs">{r}</td><td className="text-right">{c.block}</td><td className="text-right">{c.warn}</td></tr>)}</tbody>
              </table>
            </TableWrap>
          )}
        </Section>
      </div>

      <Section title="Compat watch (creator warnings)" sub={<>The lifecycle sweep that warns creators when a game version change makes their mod likely stale. Switches: <span className="font-mono">cyrus_compat_watch_enabled</span> = {String(watchOn)}, <span className="font-mono">cyrus_compat_watch_dry_run</span> = {String(watchDry)} (edit on Audit &amp; settings). In dry run, rows are recorded and nobody is told.</>}>
        {alerts === null ? <Empty waitsFor="feature/cyrus-v6-lifecycle">The compat watch tables are not in this build yet.</Empty> : alerts.length === 0 ? <Empty>The compat watch has not raised anything{watchOn ? "" : " (it is off)"}.</Empty> : (
          <TableWrap>
            <table className="w-full text-sm">
              <thead><tr className={thCls}><th>Warning</th><th>Kind</th><th className="text-right">Servers</th><th>State</th><th>Last seen</th></tr></thead>
              <tbody>{alerts.map((a) => (
                <tr key={String(a.id)} className={tdRow}>
                  <td className="max-w-[420px] text-xs"><b>{String(a.title ?? "")}</b><div className="text-slate-400">{String(a.body ?? "").slice(0, 240)}</div></td>
                  <td className="text-xs">{String(a.kind ?? "")}</td>
                  <td className="text-right">{n(Number(a.servers) || 0)}</td>
                  <td>{a.dryRun ? <Badge tone="brand">dry run</Badge> : a.resolvedAt ? <Badge tone="green">resolved</Badge> : a.dismissedAt ? <Badge tone="slate">dismissed</Badge> : a.emailedAt ? <Badge tone="green">emailed</Badge> : a.notifiedAt ? <Badge tone="green">notified</Badge> : <Badge tone="amber">open</Badge>}</td>
                  <td className="whitespace-nowrap text-xs">{when(a.lastSeenAt as Date)}</td>
                </tr>
              ))}</tbody>
            </table>
          </TableWrap>
        )}
        {signals && signals.length ? (
          <p className="mt-3 text-xs text-slate-400">Installed-mod health signals, last 7 days: {Object.entries(signals.reduce<Record<string, number>>((a, s) => ({ ...a, [String(s.kind)]: (a[String(s.kind)] ?? 0) + 1 }), {})).map(([k, v]) => `${v} ${k.toLowerCase().replace(/_/g, " ")}`).join(" · ")}</p>
        ) : null}
      </Section>
    </div>
  );
}

