import type { Metadata } from "next";
import Link from "next/link";
import { existsSync } from "node:fs";
import { join } from "node:path";
import { db } from "@/lib/db";
import { realUser } from "@/lib/auth";
import { requireCyrusAdmin, cyrusAdminMetadata } from "@/lib/cyrus/admin/gate";
import { canCyrusAdmin } from "@/lib/cyrus/admin/perms";
import { CYRUS_AUDIT_CATEGORY, CYRUS_AUDIT_PREFIX, LEGACY_CYRUS_ADMIN_ACTIONS, readAuditDetail } from "@/lib/cyrus/admin/audit";
import { CYRUS_SETTINGS, type CyrusSettingDef } from "@/lib/cyrus/admin/settings-catalog";
import { emailMap } from "@/lib/cyrus/admin/data";
import { adminCyrusSetSetting } from "@/lib/actions-cyrus-admin";
import { Badge } from "@/components/ui/primitives";
import { Confirm, Empty, Flash, Hidden, Section, TableWrap, tdRow, thCls, when } from "@/components/admin/cyrus/ui";

export const dynamic = "force-dynamic";
export async function generateMetadata(): Promise<Metadata> {
  return cyrusAdminMetadata("Audit and settings");
}

const PAGE = 100;
const GROUPS: Record<CyrusSettingDef["group"], string> = { launch: "Launch and access", safety: "Safety", games: "Games", lifecycle: "Installed mods (lifecycle)", tokens: "Token economy" };

/** Is the code that reads this setting in this build? (owner branch merged) */
function merged(owner: CyrusSettingDef["owner"]): boolean {
  if (owner === "base" || owner === "admin") return true;
