describe("cyrus admin: game status overrides", () => {
  it("the file is the default; a stored value overrides it", () => {
    const g = applyGameStatusOverrides(CYRUS_GAMES, { [gameStatusKey("minecraft")]: "disabled", [gameStatusKey("rust")]: "soon" });
    const mc = g.find((x) => x.id === "minecraft")!;
    assert.equal(mc.adminStatus, "disabled");
    assert.equal(mc.status, "soon");
    assert.equal(mc.available, false);
    assert.ok(mc.overridden);
    const rust = g.find((x) => x.id === "rust")!;
    assert.equal(rust.adminStatus, "soon");
    assert.ok(!rust.overridden);
  });
  it("a stored 'live' for a game without a real pipeline is ignored (fails safe)", () => {
    const g = applyGameStatusOverrides(CYRUS_GAMES, { [gameStatusKey("palworld")]: "live", [gameStatusKey("valheim")]: "bogus" });
    assert.equal(g.find((x) => x.id === "palworld")!.adminStatus, "soon");
    assert.equal(g.find((x) => x.id === "valheim")!.adminStatus, "soon");
  });
  it("only buildable games can be set live", () => {
    assert.ok(canSetGameStatus("minecraft", "live").ok);
    assert.ok(!canSetGameStatus("rust", "live").ok);
    assert.ok(canSetGameStatus("rust", "disabled").ok);
    assert.ok(canSetGameStatus("rust", "default").ok);
    assert.ok(!canSetGameStatus("nope", "soon").ok);
  });
