    assert.ok(gameBuildable(applyGameStatusOverrides(CYRUS_GAMES, {}), "minecraft"));
    assert.ok(!gameBuildable(applyGameStatusOverrides(CYRUS_GAMES, { [gameStatusKey("minecraft")]: "disabled" }), "minecraft"));
