});

describe("cyrus admin: suspensions", () => {
  it("parses defensively, honours scope and end date, add/remove/prune", () => {
    const raw = JSON.stringify([
      { userId: "u1", scopes: ["build", "nope"], reason: "abuse", by: "a", at: now.toISOString(), until: null },
      { userId: "u2", scopes: ["community"], reason: "spam", by: "a", at: now.toISOString(), until: new Date(now.getTime() - DAY).toISOString() },
      { userId: "bad id!", scopes: ["build"] },
      { userId: "u3", scopes: [] },
      "junk",
    ]);
    const l = parseSuspensions(raw);
    assert.deepEqual(l.map((s) => s.userId), ["u1", "u2"]);
    assert.deepEqual(l[0].scopes, ["build"]);
    assert.ok(activeSuspension(l, "u1", "build", now));
    assert.equal(activeSuspension(l, "u1", "community", now), null);
    assert.equal(activeSuspension(l, "u2", "community", now), null); // ended
    assert.deepEqual(pruneSuspensions(l, now).map((s) => s.userId), ["u1"]);
    const l2 = upsertSuspension(l, { ...l[0], scopes: ["build", "community"] });
    assert.equal(l2.filter((s) => s.userId === "u1").length, 1);
    assert.deepEqual(removeSuspension(l2, "u1").map((s) => s.userId), ["u2"]);
    assert.deepEqual(parseSuspensions("{not json"), []);
  });
});

