// Cyrus admin (/admin/cyrus): pure logic. No DB, no network.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { canCyrusAdmin, canSeeCyrusTab, CYRUS_ADMIN_ACTIONS, landingCyrusTab, visibleCyrusTabs } from "../lib/cyrus/admin/perms";
import {
  abuseSignals, attentionItems, buildOutcome, buildWhere, countOutcomes, filterQuery, marginByModel, marginRow, matchBuild, parseBuildFilter, percentile, perDay, rate, statsBy, totalMargin, type BuildLite,
} from "../lib/cyrus/admin/metrics";
import { applyGameStatusOverrides, canSetGameStatus, gameBuildable, gameStatusKey } from "../lib/cyrus/game-status";
import { CYRUS_GAMES } from "../lib/cyrus/games";
import { activeSuspension, parseSuspensions, pruneSuspensions, removeSuspension, upsertSuspension } from "../lib/cyrus/suspensions";
import { CYRUS_SETTINGS, validateSettingValue } from "../lib/cyrus/admin/settings-catalog";
import { auditDetail, readAuditDetail } from "../lib/cyrus/admin/audit";
import { parseReadiness } from "../lib/cyrus/admin/readiness";
import { observedTierModels, readHealth } from "../lib/cyrus/admin/service";
import { declaredNetwork, parseNetReviews, reviewState } from "../lib/cyrus/admin/networking";
import { readLibraryIndex } from "../lib/cyrus/admin/optional";

const DAY = 86_400_000;
const now = new Date("2026-10-08T12:00:00Z");
const b = (o: Partial<BuildLite> = {}): BuildLite => ({ id: "mb1", userId: "u1", status: "succeeded", errorCode: null, costUsd: 0.1, durationMs: 60_000, createdAt: new Date(now.getTime() - 3600_000), model: "saka", game: "minecraft", ...o });

describe("cyrus admin: permissions", () => {
  it("ADMIN sees every tab and may take every action", () => {
    assert.equal(visibleCyrusTabs("ADMIN").length, 7);
    for (const a of Object.keys(CYRUS_ADMIN_ACTIONS)) assert.ok(canCyrusAdmin("ADMIN", a as keyof typeof CYRUS_ADMIN_ACTIONS), a);
  });
  it("SUPPORT moderates the community but cannot touch tokens, builds, games or settings", () => {
    assert.deepEqual(visibleCyrusTabs("SUPPORT").map((t) => t.id), ["community"]);
    assert.equal(landingCyrusTab("SUPPORT")?.href, "/admin/cyrus/community");
    for (const a of ["report.hide", "report.dismiss", "post.unhide", "page.takedown", "page.restore", "user.suspend", "user.unsuspend"] as const) assert.ok(canCyrusAdmin("SUPPORT", a), a);
    for (const a of ["build.refund", "tokens.grant", "tokens.comp", "build.cancel", "build.rerun", "game.status", "setting.set", "network.killswitch", "network.review"] as const) assert.ok(!canCyrusAdmin("SUPPORT", a), a);
  });
  it("BILLING handles tokens and refunds only", () => {
    assert.deepEqual(visibleCyrusTabs("BILLING").map((t) => t.id), ["users"]);
    assert.ok(canCyrusAdmin("BILLING", "build.refund"));
    assert.ok(canCyrusAdmin("BILLING", "tokens.comp"));
    assert.ok(!canCyrusAdmin("BILLING", "build.cancel"));
    assert.ok(!canCyrusAdmin("BILLING", "report.hide"));
    assert.ok(!canSeeCyrusTab("BILLING", "overview"));
  });
  it("customers and employees without grants get nothing", () => {
    assert.equal(visibleCyrusTabs("CUSTOMER" as never).length, 0);
    assert.equal(landingCyrusTab("CUSTOMER" as never), null);
    assert.ok(!canCyrusAdmin("CUSTOMER" as never, "tokens.grant"));
  });
});

describe("cyrus admin: build outcomes and stats", () => {
  it("separates refusals and cancels from failures", () => {
    assert.equal(buildOutcome({ status: "failed", errorCode: "refused" }), "refused");
    assert.equal(buildOutcome({ status: "failed", errorCode: "cancelled" }), "cancelled");
    assert.equal(buildOutcome({ status: "failed", errorCode: "admin_cancelled" }), "cancelled");
    assert.equal(buildOutcome({ status: "failed", errorCode: "compile" }), "failed");
    assert.equal(buildOutcome({ status: "coding", errorCode: null }), "running");
  });
  it("rates are over finished builds only", () => {
    const c = countOutcomes([b(), b({ status: "failed", errorCode: "refused" }), b({ status: "coding" }), b({ status: "failed" })]);
    assert.equal(c.total, 4);
    assert.equal(c.finished, 3);
    assert.equal(rate(c, "succeeded"), 1 / 3);
    assert.equal(rate(countOutcomes([b({ status: "queued" })]), "succeeded"), null);
  });
  it("nearest-rank percentile", () => {
    assert.equal(percentile([], 95), null);
    assert.equal(percentile([5], 95), 5);
    const v = Array.from({ length: 100 }, (_, i) => i + 1);
    assert.equal(percentile(v, 95), 95);
    assert.equal(percentile(v, 50), 50);
    assert.equal(percentile([3, 1, 2, NaN], 100), 3);
  });
  it("groups by model with avg and p95 over timed finished builds", () => {
    const rows = [b({ durationMs: 10_000 }), b({ durationMs: 30_000 }), b({ model: "katara", durationMs: 5000 }), b({ status: "planning", durationMs: null })];
    const s = statsBy(rows, (x) => x.model ?? "auto");
    assert.equal(s[0].key, "saka");
    assert.equal(s[0].counts.total, 3);
    assert.equal(s[0].avgMs, 20_000);
    assert.equal(s[0].p95Ms, 30_000);
  });
  it("per-day buckets cover exactly N UTC days", () => {
    const d = perDay([b({ createdAt: new Date(now.getTime() - 2 * DAY) }), b(), b({ createdAt: new Date(now.getTime() - 40 * DAY) })], 30, now);
    assert.equal(d.length, 30);
    assert.equal(d[29].day, "2026-10-08");
    assert.equal(d.reduce((a, x) => a + x.total, 0), 2);
  });
});

describe("cyrus admin: margin maths", () => {
  it("value, margin and tokens per dollar by model; holds still running are excluded", () => {
    const m = marginByModel([
      { model: "saka", charged: 120, costUsd: 0.2, status: "settled" },
      { model: "saka", charged: 0, costUsd: 0, status: "released" },
      { model: "yakko", charged: 600, costUsd: 1, status: "settled" },
      { model: "saka", charged: null, costUsd: null, status: "held" },
    ], 1 / 120);
    assert.deepEqual(m.map((x) => x.model), ["saka", "yakko"]);
    const saka = m[0];
    assert.equal(saka.builds, 2);
    assert.equal(saka.tokensCharged, 120);
    assert.ok(Math.abs(saka.valueUsd - 1) < 1e-9);
    assert.ok(Math.abs(saka.marginUsd - 0.8) < 1e-9);
    assert.ok(Math.abs((saka.marginPct ?? 0) - 0.8) < 1e-9);
    assert.equal(saka.tokensPerUsd, 600);
    const t = totalMargin(m, 1 / 120);
    assert.equal(t.tokensCharged, 720);
    assert.ok(Math.abs(t.costUsd - 1.2) < 1e-9);
  });
  it("a loss shows as a negative margin; nothing charged = no percentage", () => {
    const loss = marginRow("yakko", { builds: 1, costUsd: 2, tokensCharged: 100 }, 0.01);
    assert.ok(loss.marginUsd < 0);
    const zero = marginRow("katara", { builds: 1, costUsd: 0.05, tokensCharged: 0 }, 0.01);
    assert.equal(zero.marginPct, null);
    assert.equal(marginRow("x", { builds: 1, costUsd: 0, tokensCharged: 5 }, 0.01).tokensPerUsd, null);
  });
});

