      builds30d: [...Array(3)].map(() => ({ status: "failed", errorCode: "refused", costUsd: 0.1 })).concat([{ status: "succeeded", errorCode: null, costUsd: 0.1 }, { status: "failed", errorCode: null, costUsd: 0 }]),
      reportsAgainst: 1, hiddenPosts: 0, usedToday: 1000, dailyCap: 1000, writeoffTokens: 0,
    });
    assert.deepEqual(s.map((x) => x.code), ["refusals", "failrate", "cap", "reports"]);
    assert.equal(s[0].level, "red");
    assert.equal(abuseSignals({ builds30d: [], reportsAgainst: 0, hiddenPosts: 0, usedToday: 0, dailyCap: 5000, writeoffTokens: 0 }).length, 0);
  });
});

describe("cyrus admin: game status overrides", () => {
  it("the file is the default; a stored value overrides it", () => {
    const g = applyGameStatusOverrides(CYRUS_GAMES, { [gameStatusKey("minecraft")]: "disabled", [gameStatusKey("rust")]: "soon" });
    const mc = g.find((x) => x.id === "minecraft")!;
    assert.equal(mc.adminStatus, "disabled");
    assert.equal(mc.status, "soon");
    assert.equal(mc.available, false);
    assert.ok(mc.overridden);
    const rust = g.find((x) => x.id === "rust")!;
    assert.equal(rust.adminStatus, "soon");
    assert.ok(!rust.overridden);
  });
  it("a stored 'live' for a game without a real pipeline is ignored (fails safe)", () => {
    const g = applyGameStatusOverrides(CYRUS_GAMES, { [gameStatusKey("palworld")]: "live", [gameStatusKey("valheim")]: "bogus" });
    assert.equal(g.find((x) => x.id === "palworld")!.adminStatus, "soon");
    assert.equal(g.find((x) => x.id === "valheim")!.adminStatus, "soon");
  });
  it("only buildable games can be set live", () => {
    assert.ok(canSetGameStatus("minecraft", "live").ok);
    assert.ok(!canSetGameStatus("rust", "live").ok);
    assert.ok(canSetGameStatus("rust", "disabled").ok);
    assert.ok(canSetGameStatus("rust", "default").ok);
    assert.ok(!canSetGameStatus("nope", "soon").ok);
  });
  it("new builds only for live + buildable", () => {
    assert.ok(gameBuildable(applyGameStatusOverrides(CYRUS_GAMES, {}), "minecraft"));
    assert.ok(!gameBuildable(applyGameStatusOverrides(CYRUS_GAMES, { [gameStatusKey("minecraft")]: "disabled" }), "minecraft"));
    assert.ok(!gameBuildable(applyGameStatusOverrides(CYRUS_GAMES, {}), "rust"));
  });
});

describe("cyrus admin: suspensions", () => {
  it("parses defensively, honours scope and end date, add/remove/prune", () => {
    const raw = JSON.stringify([
      { userId: "u1", scopes: ["build", "nope"], reason: "abuse", by: "a", at: now.toISOString(), until: null },
      { userId: "u2", scopes: ["community"], reason: "spam", by: "a", at: now.toISOString(), until: new Date(now.getTime() - DAY).toISOString() },
      { userId: "bad id!", scopes: ["build"] },
      { userId: "u3", scopes: [] },
      "junk",
    ]);
    const l = parseSuspensions(raw);
    assert.deepEqual(l.map((s) => s.userId), ["u1", "u2"]);
    assert.deepEqual(l[0].scopes, ["build"]);
    assert.ok(activeSuspension(l, "u1", "build", now));
    assert.equal(activeSuspension(l, "u1", "community", now), null);
    assert.equal(activeSuspension(l, "u2", "community", now), null); // ended
    assert.deepEqual(pruneSuspensions(l, now).map((s) => s.userId), ["u1"]);
    const l2 = upsertSuspension(l, { ...l[0], scopes: ["build", "community"] });
    assert.equal(l2.filter((s) => s.userId === "u1").length, 1);
    assert.deepEqual(removeSuspension(l2, "u1").map((s) => s.userId), ["u2"]);
    assert.deepEqual(parseSuspensions("{not json"), []);
  });
});

describe("cyrus admin: settings catalog", () => {
