    const keys = CYRUS_SETTINGS.map((s) => s.key);
    assert.equal(new Set(keys).size, keys.length);
    for (const s of CYRUS_SETTINGS) assert.ok(s.description.length > 10, s.key);
    assert.ok(keys.includes("cyrus_mod_networking_enabled"));
    assert.ok(keys.includes("cyrus_compat_watch_enabled"));
  });
  it("validates by type; blank or default clears; edit-elsewhere keys are refused", () => {
    assert.deepEqual(validateSettingValue("cyrus_mods_public_enabled", "true"), { ok: true, value: "true" });
    assert.deepEqual(validateSettingValue("cyrus_mods_public_enabled", "false"), { ok: true, value: "" });
