    const s = auditDetail({ before: { balance: 10 }, after: { balance: 20 }, note: "refund" });
    assert.deepEqual(readAuditDetail(s), { before: { balance: 10 }, after: { balance: 20 }, note: "refund" });
    assert.deepEqual(readAuditDetail("a@b.c +40 promo"), { text: "a@b.c +40 promo" });
    assert.deepEqual(readAuditDetail(null), {});
    const big = auditDetail({ before: "x".repeat(10_000), after: null });
