describe("cyrus admin: readiness parser", () => {
  it("reads checkboxes, numbered tasks under checklist headings and owner decisions", () => {
    const md = [
      "# Rust readiness",
      "## What is done",
      "- [x] GameSupport file",
      "## Background",
      "1. not a task",
      "## Before Rust can go live",
      "### Must have",
      "1. **Real AI path.** more",
      "2. Load test",
      "- [ ] Flip to live",
      "## Owner decisions",
      "1. Decided: Linux only.",
      "2. Open: Carbon?",
    ].join("\n");
    const r = parseReadiness(md, "x.md");
    assert.equal(r.title, "Rust readiness");
