describe("cyrus admin: service health is display-only and secret-safe", () => {
  it("whitelists fields and drops anything that looks like a credential", () => {
    const s = readHealth({ ok: true, image: "0.5", running: 1, queued: 2, concurrency: 2, auth: "subscription", versions: ["1.21.11"], features: { images: true, dedupe: false, apiKey: "sk-abc", note: "sk-live-123" }, routing: { models: { simple: "claude-haiku-4-5" }, token: "x" } });
    assert.equal(s.reachable, true);
    assert.equal(s.image, "0.5");
    assert.equal(s.queued, 2);
    assert.ok(s.features.some((f) => f.key === "images"));
    assert.ok(!JSON.stringify(s).includes("sk-"));
    assert.ok(!s.routing.some((r) => r.key === "token"));
    assert.ok(s.routing.some((r) => r.key === "models.simple"));
    assert.equal(readHealth(null).reachable, false);
    assert.equal(readHealth({ ok: true, auth: "Bearer abc.def" }).auth, null);
  });
  it("observed tier models count real calls", () => {
    const o = observedTierModels([{ tier: "saka", calls: [{ model: "claude-sonnet-5" }, { model: "x", resolvedModel: "claude-sonnet-5-20260101" }] }, { tier: null, calls: [{ model: "claude-haiku-4-5" }] }]);
