    assert.deepEqual(o.auto, [{ model: "claude-haiku-4-5", calls: 1 }]);
  });
});

describe("cyrus admin: networking review", () => {
  it("reads declared hosts from the capability manifest shapes; invalid hosts dropped", () => {
    assert.equal(declaredNetwork({ summary: null }), null);
    const h = declaredNetwork({ capabilities: { network: { hosts: [{ host: "API.example.com", purpose: "weather", sendsPlayerData: false }, "discord.com", "http://evil", "10.0.0.1"] } } });
    assert.deepEqual(h?.map((x) => x.host), ["api.example.com", "discord.com"]);
    assert.deepEqual(declaredNetwork(null, { capabilities: { hosts: ["a.io"] } })?.map((x) => x.host), ["a.io"]);
  });
  it("an approval covers exactly the reviewed hosts", () => {
    const hosts = [{ host: "a.io", purpose: null, sendsPlayerData: null }];
    const reviews = parseNetReviews(JSON.stringify({ mb1: { decision: "approved", hosts: ["a.io"] }, mb2: { decision: "blocked" }, "bad id": { decision: "approved" }, mb3: { decision: "maybe" } }));
    assert.deepEqual(Object.keys(reviews), ["mb1", "mb2"]);
    assert.equal(reviewState(hosts, reviews.mb1), "approved");
    assert.equal(reviewState([...hosts, { host: "b.io", purpose: null, sendsPlayerData: null }], reviews.mb1), "changed");
    assert.equal(reviewState(hosts, reviews.mb2), "blocked");
    assert.equal(reviewState(hosts, undefined), "pending");
  });
});

describe("cyrus admin: library index reader", () => {
