// THROWAWAY seed for node-2's per-worktree DB (wt_cyrus_v6_admin). NEVER COMMITTED. Refuses any
// DATABASE_URL that is not the node-2 agent cluster. Every row is FAKE and labelled so: emails
// *@nxeon.test, names "FAKE ...", prompts "[FAKE DEMO] ...". Tokens move through the real ledger
// (creditTokens / reserveTokens / settleReservation) so balances and the ledger agree.
import { createHash } from "node:crypto";
import { writeFileSync } from "node:fs";
import { SignJWT } from "jose";
import { db } from "../lib/db";
import { creditTokens, reserveTokens, settleReservation } from "../lib/cyrus/tokens/ledger";

const DAY = 86_400_000;
const now = Date.now();
const ADMIN = "cyrus-admin@nxeon.test";
const SUPPORT = "cyrus-support@nxeon.test";

// Deterministic pseudo-random so screenshots are stable.
let seed = 42;
const rnd = () => ((seed = (seed * 1103515245 + 12345) % 2 ** 31) / 2 ** 31);
const pick = <T,>(a: T[]) => a[Math.floor(rnd() * a.length)];

async function user(email: string, name: string, role: string, daysOld: number) {
  const old = await db.user.findUnique({ where: { email } });
  if (old) return old;
  return db.user.create({ data: { email, passwordHash: "x", name, role, emailVerifiedAt: new Date(), heardAboutUs: "other", createdAt: new Date(now - daysOld * DAY) } as never });
}

async function session(userId: string) {
  const token = await new SignJWT({ sub: userId, sv: 0, typ: "session" }).setProtectedHeader({ alg: "HS256" }).setIssuedAt().setExpirationTime("2d").sign(new TextEncoder().encode(process.env.AUTH_SECRET!));
  await db.userSession.create({ data: { userId, tokenHash: createHash("sha256").update(token).digest("hex") } });
  return token;
}

const PROMPTS = [
  ["FrostbiteBlade", "[FAKE DEMO] A frost greatsword that slows enemies on critical hits"],
  ["CoinShop", "[FAKE DEMO] A coin economy: coins for mob kills, /pay, /baltop and a chest-menu shop"],
  ["QuestBoard", "[FAKE DEMO] A daily quest board with three random quests and rewards"],
  ["SpleefArena", "[FAKE DEMO] A spleef mini-game with a lobby, countdown and winner announcement"],
  ["ZoneGuard", "[FAKE DEMO] Protected zones players without permission cannot grief"],
  ["JoinStreak", "[FAKE DEMO] Daily join rewards that grow with the login streak"],
];
const MODELS = ["katara", "saka", "saka", "saka", "yakko"] as const;
const SVC = { katara: "claude-haiku-4-5-20251001", saka: "claude-sonnet-5", yakko: "claude-opus-5" } as const;

async function main() {
  const url = process.env.DATABASE_URL ?? "";
  if (!/127\.0\.0\.1:5433\/wt_/.test(url)) throw new Error("refusing: not the node-2 throwaway DB");

  // Clean slate for the Cyrus tables (throwaway DB only).
  await db.cyrusModReport.deleteMany({});
  await db.cyrusModPost.deleteMany({});
  await db.cyrusFork.deleteMany({});
  await db.cyrusModPage.deleteMany({});
  await db.cyrusTokenLedger.deleteMany({});
  await db.cyrusTokenReservation.deleteMany({});
  await db.cyrusTokenLot.deleteMany({});
  await db.cyrusTokenAccount.deleteMany({});
  await db.cyrusPlan.deleteMany({});
  await db.modBuild.deleteMany({});
  await db.auditLog.deleteMany({ where: { OR: [{ category: "cyrus_admin" }, { action: { startsWith: "cyrus" } }] } });
  await db.setting.deleteMany({ where: { OR: [{ key: { startsWith: "cyrus_" } }, { key: "preview_access_emails_modbuilder" }] } });

  const admin = await user(ADMIN, "FAKE Cyrus Admin", "ADMIN", 400);
  const support = await user(SUPPORT, "FAKE Support Agent", "SUPPORT", 300);
  const creators = [
    await user("demo-creator-ana@nxeon.test", "FAKE Ana (demo)", "CUSTOMER", 120),
    await user("demo-creator-ben@nxeon.test", "FAKE Ben (demo)", "CUSTOMER", 60),
    await user("demo-creator-cleo@nxeon.test", "FAKE Cleo (demo)", "CUSTOMER", 3),
    await user("demo-creator-dev@nxeon.test", "FAKE Dev (demo)", "CUSTOMER", 200),
  ];
  await db.userSession.deleteMany({ where: { userId: { in: [admin.id, support.id] } } });
  await db.setting.create({ data: { key: "preview_access_emails_modbuilder", value: [ADMIN, SUPPORT, ...creators.map((c) => c.email)].join(",") } });
  await db.setting.create({ data: { key: "cyrus_tok_live", value: "true" } });

  for (const c of creators) {
    await creditTokens({ userId: c.id, amount: 2000, kind: "grant", source: "server_initial", sourceRef: "FAKE-server", idemKey: `seed-gs-${c.id}`, expiresAt: new Date(now + 80 * DAY), note: "FAKE demo grant" });
  }
  await creditTokens({ userId: creators[0].id, amount: 3500, kind: "grant", source: "plan", sourceRef: "in_FAKE", idemKey: `seed-plan-${creators[0].id}`, expiresAt: new Date(now + 90 * DAY), note: "FAKE plan month" });
