  await db.cyrusTokenAccount.update({ where: { userId: creators[3].id }, data: { tierOverride: "all", tierOverrideUntil: null } });

  // ~48 builds over 30 days.
  let i = 0;
  const builds: { id: string; userId: string; model: string; outcome: string }[] = [];
  for (let d = 29; d >= 0; d--) {
    const perDay = d % 6 === 0 ? 3 : d % 3 === 0 ? 2 : 1;
    for (let k = 0; k < perDay; k++) {
      i++;
      const c = pick(creators);
      const [plugin, prompt] = pick(PROMPTS);
      const model = pick([...MODELS]);
      const r = rnd();
      const outcome = r < 0.7 ? "succeeded" : r < 0.82 ? "failed" : r < 0.92 ? "refused" : "cancelled";
      const id = `mbseed${String(i).padStart(3, "0")}`;
      const created = new Date(now - d * DAY - Math.floor(rnd() * 8) * 3600_000 - 600_000);
      const cost = outcome === "refused" ? 0.01 + rnd() * 0.02 : model === "katara" ? 0.03 + rnd() * 0.05 : model === "saka" ? 0.08 + rnd() * 0.3 : 0.4 + rnd() * 0.6;
      const dur = Math.round((model === "katara" ? 45 : model === "saka" ? 110 : 190) * (0.6 + rnd()) * 1000);
      const status = outcome === "succeeded" ? "succeeded" : "failed";
      const errorCode = outcome === "failed" ? pick(["compile", "repair_exhausted", "unreachable"]) : outcome === "refused" ? "refused" : outcome === "cancelled" ? "cancelled" : null;
      const safety = outcome === "refused"
        ? { verdict: "block", findings: [{ severity: "block", rule: pick(["net.socket", "proc.exec", "fs.outside"]), where: "src/main/java/Main.java:42", message: "[FAKE DEMO] Opens a raw network socket", evidence: "new Socket(...)" }] }
        : { verdict: rnd() < 0.2 ? "warn" : "pass", findings: rnd() < 0.2 ? [{ severity: "warn", rule: "sched.sync-heavy", where: "Listener.java:10", message: "[FAKE DEMO] Heavy work on the main thread", evidence: "" }] : [] };
      await db.modBuild.create({
