          costUsd: +cost.toFixed(4), durationMs: dur, attempts: outcome === "failed" ? 2 : 1, errorCode, error: errorCode ? `[FAKE DEMO] ${errorCode}` : null,
          createdAt: created, finishedAt: new Date(created.getTime() + dur), cyrus: { model },
          result: {
            summary: null, commands: [], permissions: [], config: [], warnings: [], repairs: outcome === "failed" ? 1 : 0, queuePosition: 0,
            files: [{ path: `src/main/java/dev/cyrus/${plugin.toLowerCase()}/${plugin}Plugin.java`, size: 2400 + Math.floor(rnd() * 3000) }, { path: "src/main/resources/plugin.yml", size: 210 }],
            safety,
            events: [
              { at: created.toISOString(), stage: "queued", message: "Waiting for a free builder" },
              { at: new Date(created.getTime() + 2000).toISOString(), stage: "planning", message: "Planning" },
              { at: new Date(created.getTime() + 9000).toISOString(), stage: "coding", message: "Writing code" },
              ...(outcome === "refused" ? [] : [{ at: new Date(created.getTime() + dur * 0.7).toISOString(), stage: "compiling", message: "Compiling" }]),
              ...(outcome === "failed" ? [{ at: new Date(created.getTime() + dur * 0.8).toISOString(), stage: "repairing", message: "Fixing a compile error" }] : []),
              { at: new Date(created.getTime() + dur * 0.9).toISOString(), stage: "scanning", message: "Safety check" },
              { at: new Date(created.getTime() + dur).toISOString(), stage: status, message: outcome },
            ],
            ai: { route: model === "katara" ? "simple" : "standard", calls: [{ kind: "generate", route: null, model: SVC[model], resolvedModel: SVC[model], costUsd: +cost.toFixed(4), turns: 6, durationMs: Math.round(dur * 0.7) }] },
          },
        } as never,
      });
      // The token hold + settle through the real ledger.
      await reserveTokens({ userId: c.id, buildId: id, model, need: 40, pick: (a) => (a >= 220 ? 220 : a >= 40 ? a : null), dailyCap: () => 1e9, allowShort: true, now: created });
      const charge = outcome === "succeeded" ? Math.ceil(cost * 500 * (model === "yakko" ? 1.25 : 1)) : outcome === "refused" || outcome === "cancelled" ? Math.ceil(cost * 500) : 0;
      await settleReservation({ buildId: id, charge, reason: outcome === "failed" ? "failed_free" : outcome, costUsd: +cost.toFixed(4), now: new Date(created.getTime() + dur) });
      builds.push({ id, userId: c.id, model, outcome });
    }
  }
  // A stuck running build (2 h old) with a hold, a fresh queued one, and an orphan hold.
