// THROWAWAY seed for node-2's per-worktree DB (wt_cyrus_v6_admin). NEVER COMMITTED. Refuses any
// DATABASE_URL that is not the node-2 agent cluster. Every row is FAKE and labelled so: emails
// *@nxeon.test, names "FAKE ...", prompts "[FAKE DEMO] ...". Tokens move through the real ledger
// (creditTokens / reserveTokens / settleReservation) so balances and the ledger agree.
import { createHash } from "node:crypto";
import { writeFileSync } from "node:fs";
import { SignJWT } from "jose";
import { db } from "../lib/db";
import { creditTokens, reserveTokens, settleReservation } from "../lib/cyrus/tokens/ledger";

const DAY = 86_400_000;
const now = Date.now();
const ADMIN = "cyrus-admin@nxeon.test";
const SUPPORT = "cyrus-support@nxeon.test";

// Deterministic pseudo-random so screenshots are stable.
let seed = 42;
const rnd = () => ((seed = (seed * 1103515245 + 12345) % 2 ** 31) / 2 ** 31);
const pick = <T,>(a: T[]) => a[Math.floor(rnd() * a.length)];

async function user(email: string, name: string, role: string, daysOld: number) {
  const old = await db.user.findUnique({ where: { email } });
  if (old) return old;
  return db.user.create({ data: { email, passwordHash: "x", name, role, emailVerifiedAt: new Date(), heardAboutUs: "other", createdAt: new Date(now - daysOld * DAY) } as never });
}

async function session(userId: string) {
  const token = await new SignJWT({ sub: userId, sv: 0, typ: "session" }).setProtectedHeader({ alg: "HS256" }).setIssuedAt().setExpirationTime("2d").sign(new TextEncoder().encode(process.env.AUTH_SECRET!));
  await db.userSession.create({ data: { userId, tokenHash: createHash("sha256").update(token).digest("hex") } });
  return token;
}

const PROMPTS = [
  ["FrostbiteBlade", "[FAKE DEMO] A frost greatsword that slows enemies on critical hits"],
