// THROWAWAY local stand-in for the build service (node-2 verification only, NEVER COMMITTED).
// Answers what the admin reads: GET /health (0.5-shaped, image labelled "0.5-mock"), GET /builds/:id
// (usage per stage for the seeded builds), POST /builds/:id/cancel (marks it cancelled).
import { createServer } from "node:http";

const PORT = Number(process.env.MOCK_PORT || 7398);
const KEY = process.env.MODBUILDER_API_KEY || "local-mock-key";
const cancelled = new Set();

createServer((req, res) => {
  const u = new URL(req.url, "http://x");
  const send = (code, j) => { res.writeHead(code, { "content-type": "application/json" }); res.end(JSON.stringify(j)); };
  if (u.pathname === "/health") {
    return send(200, {
      ok: true, service: "nxeon-modbuilder", image: "0.5-mock (local stand-in)",
      features: { images: true, live: true, liveStream: true, usage: true, autofix: true, leanTools: true, dedupe: false, effort: null, cacheTtl: null, maxTurnsRepair: 25 },
      promptVersion: "mb-2026-10-08.1", knowledge: "mock", model: "sonnet",
      routing: { enabled: true, simpleMax: 3, complexMin: 7, models: { simple: "claude-haiku-4-5-20251001", standard: "claude-sonnet-5", complex: "claude-sonnet-5" } },
      versions: ["1.21.11", "1.21.8", "1.21.4", "1.21.1"], running: 1, queued: 1, concurrency: 2, auth: "subscription",
    });
  }
  if (req.headers.authorization !== `Bearer ${KEY}`) return send(401, { error: "unauthorized" });
  const m = /^\/builds\/([A-Za-z0-9_-]+)(\/cancel)?$/.exec(u.pathname);
  if (!m) return send(404, { error: "not found" });
  const id = m[1];
  if (m[2] && req.method === "POST") { cancelled.add(id); return send(200, { ok: true }); }
  if (!id.startsWith("mbseed")) return send(404, { error: "not found" });
  const isCancelled = cancelled.has(id);
  const running = id === "mbseedstuck01" || id === "mbseedqueued1";
  return send(200, {
    id, status: isCancelled ? "failed" : running ? (id === "mbseedstuck01" ? "coding" : "queued") : "succeeded",
    error: isCancelled ? "Cancelled." : null, errorCode: isCancelled ? "cancelled" : null, attempts: 1, repairs: 0, costUsd: isCancelled ? 0.12 : 0.1, durationMs: 90_000,
    pluginName: null, jar: null, summary: null, commands: [], permissions: [], config: [], warnings: [], files: [], safety: null,
    events: [{ at: new Date().toISOString(), stage: isCancelled ? "failed" : "coding", message: isCancelled ? "Cancelled" : "Writing code" }], queuePosition: 0, finishedAt: isCancelled ? new Date().toISOString() : null,
    usage: { stages: { classify: { n: 1, ms: 900, costUsd: 0.0011, turns: 1, input: 1800, cacheWrite: 0, cacheRead: 0, output: 40 }, generate: { n: 1, ms: 61_000, costUsd: 0.0912, turns: 5, input: 22_000, cacheWrite: 4100, cacheRead: 15_200, output: 6300 }, precheck: { n: 1, ms: 40 }, compile: { n: 2, ms: 14_000 }, autofix: { n: 1, ms: 30 }, scan: { n: 1, ms: 300 } }, autofix: 2, savedRepairs: 1 },
  });
}).listen(PORT, "127.0.0.1", () => console.log("mock modbuilder on", PORT));

