// THROWAWAY Playwright run ON node-2 (devhost run). Real server-rendered /admin/cyrus routes on the
// node-2 dev server. BASE=http://127.0.0.1:<port> OUT=dir. NEVER COMMITTED.
import { chromium } from "playwright";
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";

const BASE = process.env.BASE;
const OUT = process.env.OUT || ".next.shots";
const S = JSON.parse(readFileSync(".next.cyrus-admin-session.json", "utf8"));
mkdirSync(OUT, { recursive: true });
const log = [];
const note = (...a) => { const l = a.join(" "); log.push(l); console.log(l); };
const browser = await chromium.launch({ args: ["--disable-dev-shm-usage"] });

async function ctx(w, theme, token) {
  const mobile = w < 600;
  const c = await browser.newContext({ viewport: { width: w, height: mobile ? 844 : 900 }, deviceScaleFactor: 1, isMobile: mobile, hasTouch: mobile });
  const host = new URL(BASE).hostname;
  await c.addCookies([{ name: "nxeon_session", value: token, domain: host, path: "/" }, { name: "nxeon_authed", value: "1", domain: host, path: "/" }]);
  await c.addInitScript((t) => { try { localStorage.setItem("nxeon.admin.theme", t); } catch {} }, theme);
  return c;
}
async function go(p, url) {
  for (let i = 0; i < 6; i++) {
    try {
      const r = await p.goto(BASE + url, { waitUntil: "domcontentloaded", timeout: 240000 });
      await p.waitForLoadState("networkidle", { timeout: 60000 }).catch(() => {});
      note("GET", url, "->", r?.status(), new URL(p.url()).pathname);
      return r;
    } catch (e) { if (i === 5) throw e; await p.waitForTimeout(6000); }
  }
}
async function overflow(p, tag) {
  const o = await p.evaluate(() => ({ sw: document.documentElement.scrollWidth, cw: document.documentElement.clientWidth }));
  if (o.sw > o.cw + 1) note("OVERFLOW", tag, JSON.stringify(o));
}

const PAGES = [
  ["overview", "/admin/cyrus"],
  ["builds", "/admin/cyrus/builds"],
  ["build-detail", `/admin/cyrus/builds/${S.sample.refund}`],
  ["users", "/admin/cyrus/users"],
  ["user-account", `/admin/cyrus/users?u=${S.creators[1].id}`],
  ["games", "/admin/cyrus/games"],
  ["community", "/admin/cyrus/community"],
  ["library", "/admin/cyrus/library"],
  ["audit", "/admin/cyrus/audit"],
];

// 1. Real writes through the UI (admin, dark 1440): refund, cancel, game status, setting, suspension.
if (process.env.ACTIONS !== "0") {
  const c = await ctx(1440, "dark", S.admin.token);
  const p = await c.newPage();
  p.on("pageerror", (e) => note("PAGEERROR actions", e.message));
  await go(p, `/admin/cyrus/builds/${S.sample.refund}`);
  await p.fill('input[name="note"][placeholder^="Reason"]', "verification refund (FAKE)");
  await p.click('button:has-text("Refund tokens")');
  await p.waitForLoadState("networkidle").catch(() => {});
  note("refund flash:", (await p.locator('[role="status"]').first().textContent().catch(() => "none")) ?? "none");
  await p.screenshot({ path: `${OUT}/action-refund.png`, fullPage: false });
  await go(p, "/admin/cyrus/builds/mbseedstuck01");
  await p.click('button:has-text("Cancel build")');
  await p.waitForLoadState("networkidle").catch(() => {});
  note("cancel flash:", (await p.locator('[role="status"]').first().textContent().catch(() => "none")) ?? "none");
  await go(p, "/admin/cyrus/games");
  await p.selectOption('select[aria-label="Rust status"]', "disabled");
  await p.locator('form:has(select[aria-label="Rust status"]) button').click();
  await p.waitForLoadState("networkidle").catch(() => {});
  note("game flash:", (await p.locator('[role="status"]').first().textContent().catch(() => "none")) ?? "none");
  // An illegal "live" for Rust via a crafted form value must be refused server-side.
  await p.evaluate(() => { const s = document.querySelector('select[aria-label="Palworld status"]'); const o = document.createElement("option"); o.value = "live"; o.textContent = "live"; s.appendChild(o); s.value = "live"; });
  await p.locator('form:has(select[aria-label="Palworld status"]) button').click();
  await p.waitForLoadState("networkidle").catch(() => {});
  note("palworld live (must be refused):", (await p.locator('[role="status"]').first().textContent().catch(() => "none")) ?? "none");
  await go(p, "/admin/cyrus/audit");
  await p.locator('form:has(input[name="key"][value="cyrus_compat_watch_enabled"]) select').selectOption("true");
  await p.locator('form:has(input[name="key"][value="cyrus_compat_watch_enabled"]) button').click();
  await p.waitForLoadState("networkidle").catch(() => {});
  note("setting flash:", (await p.locator('[role="status"]').first().textContent().catch(() => "none")) ?? "none");
  await go(p, `/admin/cyrus/users?u=${S.creators[1].id}`);
  await p.check('input[name="scope_build"]');
  await p.fill('input[name="reason"]', "verification suspension (FAKE)");
  await p.fill('input[name="days"][placeholder^="days (blank = until"]', "2");
  await p.click('button:has-text("Suspend")');
  await p.waitForLoadState("networkidle").catch(() => {});
  note("suspend flash:", (await p.locator('[role="status"]').first().textContent().catch(() => "none")) ?? "none");
  await c.close();
}

// 2. Every tab, dark + light, 1440 + 390 (admin).
for (const [theme, w] of [["dark", 1440], ["light", 1440], ["dark", 390], ["light", 390]]) {
  const c = await ctx(w, theme, S.admin.token);
  const p = await c.newPage();
  p.on("pageerror", (e) => note("PAGEERROR", theme, w, e.message));
  p.on("console", (m) => { if (m.type() === "error") note("CONSOLE", theme, w, m.text().slice(0, 300)); });
  for (const [name, url] of PAGES) {
    if (process.env.ONLY && !process.env.ONLY.split(",").includes(name)) continue;
    await go(p, url);
    await p.waitForTimeout(700);
    await overflow(p, `${name}-${theme}-${w}`);
    await p.screenshot({ path: `${OUT}/${name}-${theme}-${w}.png`, fullPage: true, timeout: 180000 });
  }
  await c.close();
}

// 3. Role gating: SUPPORT lands on Community and is bounced from Builds; a customer gets 404/redirect.
{
  const c = await ctx(1440, "dark", S.support.token);
  const p = await c.newPage();
  await go(p, "/admin/cyrus");
  note("support /admin/cyrus lands on", new URL(p.url()).pathname);
  await go(p, "/admin/cyrus/builds");
  note("support /admin/cyrus/builds lands on", new URL(p.url()).pathname);
  await go(p, "/admin/cyrus/community");
  await p.screenshot({ path: `${OUT}/support-community-dark-1440.png`, fullPage: false });
  const tabs = await p.locator(".adm-subtab").allTextContents();
  note("support tabs:", JSON.stringify(tabs));
  await c.close();
}
writeFileSync(`${OUT}/log.txt`, log.join("\n"));
await browser.close();

